insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3), 1, 'Merge away dead values', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3) and s.position = 1), 'think', 'predict', 'The closed files hold records for set a 1, set b 2, set a 3, del b and set c 4, in that order, and the active file is empty. A merge rewrites all the closed files into one new file. How many records does the new file hold? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"Only the latest live value of each key survives. a keeps its value 3 and drops 1. b was deleted, so its value and its tombstone both go, since no older copy of b is left anywhere. c keeps 4. That leaves 2 records. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3) and s.position = 1), 'build', 'build', 'Add a merge that runs in the background over every closed file, writes new files holding only the live value of each key, points the keydir at the new copies and then deletes the old files to free the space.');
