insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3), 2, 'Hint files', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3) and s.position = 2), 'think', 'explain', 'A hint file holds, for each record in a merged file, the timestamp, the key size, the value size, the value position and the key, but not the value. Why does reading hint files make startup faster, and why can a merged file have one when the active file does not?', null, null, '[{"id":"p1","point":"Rebuilding the keydir only needs where each value is, not the value, so the hint file is much smaller to read than the data file"},{"id":"p2","point":"Values can be large, so skipping them saves most of the reading at startup"},{"id":"p3","point":"A merged file is closed and never changes, so its hint file is written once and stays correct, while the active file is still growing"}]'::jsonb);
