insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3), 3, 'Recover after a crash', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3) and s.position = 3), 'think', 'trace', 'The active file holds complete records for set a 1 and set b 2. The program crashed while appending a third record, for set a 3, and only the first 10 bytes of it reached the disk. On restart the store replays the active file, checking each record''s CRC. What does get a return? Answer with one number.', null, '{"match":"number_exact","expected":1,"derivation":"The first two records are whole and pass their CRC, so the keydir gets a with 1 and b with 2. The third record is cut short: 10 bytes is not even a full header, and the bytes that are there cannot pass a CRC check. Recovery drops it, so the keydir still points at the old record and get a returns 1. Proof script output: 1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3) and s.position = 3), 'build', 'build', 'On startup, rebuild the keydir from the hint files of merged files and by replaying the other files from the start. Check every record''s CRC in the active file and drop any record that is incomplete or fails the check, then carry on appending after the last good record.');
