insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3), null, 1, 'Your store has run for months and then crashes in the middle of a write. Explain how merging kept the disk from filling up, and how the store comes back with a correct keydir on restart.', '[{"id":"t1","concept":"log-compaction","point":"Merge rewrites closed files keeping only the latest live value of each key, dropping stale values and tombstones, then deletes the old files"},{"id":"t2","concept":"log-compaction","point":"Merge writes a hint file for each new file, listing where each key''s value is, so the keydir can be rebuilt without reading the values"},{"id":"t3","concept":"crash-recovery","point":"On restart the keydir is rebuilt from the hint files and by replaying the remaining files, with later records overriding earlier ones"},{"id":"t4","concept":"checksums","point":"Each record in the active file is checked against its CRC, and the half-written last record fails the check and is dropped"}]'::jsonb);
