insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 1) and s.position = 1), 'think', 'predict', 'An empty filter has 10 bits, numbered 0 to 9. Adding cat sets the bits its hashes choose: 1, 4 and 6. Adding dog sets bits 2, 4 and 7. How many bits are one after both words are added? Answer with the count.', null, '{"match":"number_exact","expected":5,"derivation":"cat turns on bits 1, 4 and 6. dog turns on bits 2 and 7, and bit 4, which is already one and stays one. The bits that are one are 1, 2, 4, 6 and 7, so 5. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 1) and s.position = 1), 'build', 'build', 'Create a filter with a given number of bits, all zero, and a given number of hash functions. Write an add operation that sets the bit each hash function picks for the word. Writing a few tests first, by hand on a tiny filter like this one, makes the later steps easier to trust.');
