insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 1) and s.position = 2), 'think', 'predict', 'Keep the filter holding cat and dog from the last step. You look up cow, whose hashes point at bits 1, 2 and 7, and fox, whose hashes point at bits 1, 3 and 6. Neither word was ever added. How many of the two does the filter report as probably present? Answer with the count.', null, '{"match":"number_exact","expected":1,"derivation":"The bits that are one are 1, 2, 4, 6 and 7. cow checks 1, 2 and 7, all one, so the filter says probably present even though cow was never added: a false positive. fox checks 1, 3 and 6, and bit 3 is zero, so fox is definitely absent. One of the two is reported present. Proof script output: 1."}'::jsonb, null);
