insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 1) and s.position = 4), 'think', 'predict', 'The filter keeps its bits packed eight to a byte, in bytes numbered from 0, with positions 0 to 7 inside each byte. Bit 0 is position 0 of byte 0 and bit 8 is position 0 of byte 1. Which byte holds bit 21, and at which position inside that byte?', null, '{"match":"numbers_all","expected":[2,5],"derivation":"Bytes 0 and 1 hold bits 0 to 15 and byte 2 holds bits 16 to 23. Bit 21 is the sixth bit of byte 2, counting from position 0, so it is position 5. Proof script output: [2, 5]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 1) and s.position = 4), 'build', 'build', 'Store the bits in an array of bytes, eight per byte, rather than one whole byte or more per bit. Setting and testing a bit then means finding its byte and its position in that byte. Check that a filter of 4,000,000 bits takes 500,000 bytes.');
