insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 1), null, 1, 'Explain how your filter adds a word and answers a lookup, why it can wrongly say yes but never wrongly say no, and how its bits are kept in memory.', '[{"id":"t1","concept":"bloom-filter","point":"Adding sets the bit each hash picks, and a lookup says absent if any of its bits is zero, so a word that was added is always found"},{"id":"t2","concept":"bloom-filter","point":"Other words can turn on all the bits of a word never added, so a lookup can say probably present wrongly, which is a false positive"},{"id":"t3","concept":"hash-functions","point":"Each hash function gives the same number for the same word, and k different values reduced to the bit count give the positions"},{"id":"t4","concept":"bit-packing","point":"The bits are packed eight to a byte, so bit n lives in byte n divided by 8 at position n modulo 8"}]'::jsonb);
