insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2) and s.position = 1), 'think', 'explain', 'Before building, you choose how many bits the filter has and how many hash functions it uses. Explain what goes wrong if you pick far too few bits, and why adding more and more hash functions stops helping and starts to hurt.', null, null, '[{"id":"p1","point":"With too few bits for the number of words, most bits end up as one, so almost any lookup finds all its bits set and false positives become common"},{"id":"p2","point":"Each extra hash function sets more bits per word, which fills the array faster, so past a best number the false positive rate rises again"},{"id":"p3","point":"So the bit count is worked out from the number of words and the false positive rate you accept, and the best hash count follows from the bits per word"}]'::jsonb);
