insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2), 3, 'Write the file', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2) and s.position = 3), 'think', 'predict', 'A filter of 20 bits is saved in the CCBF format: 4 bytes of identifier, 2 bytes of version, 2 bytes of hash count, 4 bytes of bit count, then the bits packed eight to a byte. How many bytes long is the whole file? Answer with one number.', null, '{"match":"number_exact","expected":15,"derivation":"The header is 4 + 2 + 2 + 4 = 12 bytes. 20 bits fill two whole bytes and spill 4 bits into a third, which is padded with zero bits, so the bits take 3 bytes. 12 + 3 = 15. Proof script output: 15."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2) and s.position = 3), 'build', 'build', 'Save the filter to words.bf: the four letters CCBF, a version number of 1, the hash count, the bit count, all big-endian, then the packed bits. The file should be far smaller than the dictionary; the challenge author''s was about a fifth of the size.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2) and s.position = 3), 'hint', '', 'Add up the header fields first, then ask how many whole bytes are needed to hold 20 bits.', 'generated');
