insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2), 4, 'Get the byte order right', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2) and s.position = 4), 'think', 'predict', 'Your writer stores the version, 1, in bytes 4 and 5 of the file in big-endian order, as the format says. A reader written in a hurry reads those two bytes as a little-endian number. What version number does it think it found? Answer with one number.', null, '{"match":"number_exact","expected":256,"derivation":"Big-endian puts the most significant byte first, so bytes 4 and 5 hold 0 then 1. A little-endian reader treats the first byte as the low one and the second as the high one, so it reads 0 plus 1 times 256, which is 256. Proof script output: 256."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2) and s.position = 4), 'build', 'build', 'Look at the start of your file with a hex dump, for example xxd with a limit of 32 bytes. You should see the bytes of CCBF, then 0001 for the version, then your hash count and bit count written most significant byte first. The author''s file showed 4 hash functions and a bit count of 003d0900 in hex.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2) and s.position = 4), 'hint', '', 'Write down the two bytes in the order they sit in the file, then decide which one a little-endian reader treats as the larger.', 'generated');
