insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 2), null, 1, 'Explain how your build turns a dictionary file into words.bf, so that any program on any machine could read the file back and know exactly what it holds.', '[{"id":"t1","concept":"line-endings","point":"Each line is stripped of its carriage return and newline and empty lines are skipped, so the stored words match what users type"},{"id":"t2","concept":"file-header-format","point":"The file starts with a header, the identifier CCBF, a version, the hash count and the bit count, and the packed bits follow it"},{"id":"t3","concept":"byte-order","point":"The header numbers are written big-endian, most significant byte first, so a reader on any processor gets the same values"}]'::jsonb);
