insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 3) and s.position = 1), 'hint', '', 'What does the loader do with bytes 0 to 5, and in which order does the format store its numbers?', 'generated');
