insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 3), 2, 'Check words from the command line', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 3) and s.position = 2), 'think', 'predict', 'Your dictionary holds hello, world, apple, river and stone. You run the checker on hello, helo, world, wrld, apple and river. Depending on the filter''s size and on luck, what is the fewest and what is the most words it could list as spelt wrong?', null, '{"match":"numbers_all","expected":[0,2],"derivation":"hello, world, apple and river were added, and a Bloom filter never misses a word that was added, so they are never listed. helo and wrld were not added. Each is listed when one of its bits is zero, but either can be a false positive. So anything from 0, both wrongly found, to 2, both caught, is possible. The proof builds real FNV-1a filters of many sizes and finds 0 and 2. Proof script output: [0, 2]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 3) and s.position = 2), 'build', 'build', 'Without the build option, load words.bf and treat every argument as a word to check, then print the words that are probably spelt wrong. In the author''s run, checking hi, hello, word, concurrency, coding, challenges, imadethis and up listed coding, challenges and imadethis, the first two only because their dictionary did not contain them.');
