insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 3) and s.position = 3), 'think', 'explain', 'How would you convince yourself that the filter you load from words.bf answers exactly like the one you built, and that its false positive rate is close to the one you chose?', null, null, '[{"id":"p1","point":"Build a filter, save it, load it, and check that the header values and every byte of bits are the same, or that every word gives the same answer"},{"id":"p2","point":"Compare against an exact set of the dictionary words: every dictionary word must be reported present, with no exceptions"},{"id":"p3","point":"Check many words known not to be in the dictionary, such as random strings, and see that the share wrongly reported present is near the chosen rate"}]'::jsonb);
