insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom') and m.position = 3), null, 1, 'Explain how ccspellcheck decides what to do from its arguments, and how you showed that saving, loading and checking all work.', '[{"id":"t1","concept":"cli-subcommands","point":"The build option takes a dictionary file and writes words.bf, otherwise every argument is a word to check, and errors go to the error stream with a non-zero exit status"},{"id":"t2","concept":"round-trip-testing","point":"A filter that is saved and loaded again gives the same header, the same bits and the same answers as the one that was built"},{"id":"t3","concept":"differential-testing","point":"Its answers are compared with an exact word set: no dictionary word is ever reported wrong, and the false positive rate on non-words is near the chosen one"}]'::jsonb);
