insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 1) and s.position = 1), 'think', 'predict', 'The program is "+++>+<-" and it runs on fresh cells. What value does the first cell hold when the program ends? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The three pluses make the first cell 3. The greater-than moves to the second cell and the plus makes it 1. The less-than moves back to the first cell, and the minus takes it down to 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 1) and s.position = 1), 'build', 'build', 'Make ccbf with no arguments start a REPL that reads a line of code and, for now, prints it back. Make ccbf test.bf print the contents of the file instead, using a test.bf that holds the Hello! program from the challenge page. Report a file that cannot be opened on the error stream with a non-zero exit status.');
