insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 1) and s.position = 2), 'think', 'trace', 'The program is "+++[>++<-]" and it runs on fresh cells. What value does the second cell hold when the program ends? Answer with one number.', null, '{"match":"number_exact","expected":6,"derivation":"The first cell is set to 3 before the loop. Each pass of the body adds 2 to the second cell and takes 1 from the first, so the body runs 3 times before the first cell is zero at the closing bracket. The second cell ends at 6. Proof script output: 6."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 1) and s.position = 2), 'build', 'build', 'Interpret the program one character at a time with 30,000 cells starting at zero, a program counter and a data pointer, skipping every character that is not one of the eight commands. Run the challenge''s first test script and check that it prints its short message ending in a question. Then run the Mandelbrot program linked from the page with its output thrown away and time it; an unoptimised interpreter usually takes somewhere around 20 to 40 seconds. Run it once more with output shown and check that it draws the Mandelbrot set. Write the time down, because later milestones compare against it.');
