insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 1) and s.position = 3), 'build', 'build', 'Pair every bracket with its partner before the program runs, using a stack, and refuse to run a program with unbalanced brackets, printing a message that says where the problem is. Check that a program with a loop inside a loop gives the right answer.');
