insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 1), null, 1, 'Explain what your interpreter does from the moment it is given a program file until the program ends, including what happens at each square bracket.', '[{"id":"t1","concept":"cli-subcommands","point":"With a file name it reads and runs that file, with no arguments it starts a REPL, and a missing file or bad program gives a message on the error stream and a non-zero exit status"},{"id":"t2","concept":"interpreter-loop","point":"A loop fetches the command under the program counter, carries it out on the cell under the data pointer, and moves the counter on, skipping any character that is not a command"},{"id":"t3","concept":"bracket-matching","point":"The brackets are paired before running with a stack, so an opening bracket on a zero cell jumps past its partner and a closing bracket on a non-zero cell jumps back to its partner"}]'::jsonb);
