insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 2), 1, 'One instruction per command', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 2) and s.position = 1), 'think', 'predict', 'Your compiler emits one bytecode instruction per command and drops everything else. How many instructions does it emit for the source "Set two ++ Loop [>+<-] Show it >." Answer with the total.', null, '{"match":"number_exact","expected":10,"derivation":"The words Set two, Loop and Show it hold none of the eight commands, so they vanish. What is left is two pluses, the six commands of the loop including both brackets, and a greater-than and a full stop: 2 + 6 + 2 = 10. Proof script output: 10."}'::jsonb, null);
