insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 2) and s.position = 2), 'think', 'predict', 'The source is "x + y [ inner [ - ] outer ]" and it is compiled with comments removed. The instructions are numbered from 0, and each opening bracket stores the number of its matching closing bracket. What number does the first opening bracket store? Answer with one number.', null, '{"match":"number_exact","expected":5,"derivation":"The letters and spaces are dropped, leaving plus, opening bracket, opening bracket, minus, closing bracket, closing bracket, numbered 0 to 5. The inner pair is 2 and 4, so the outer opening bracket at 1 pairs with the closing bracket at 5. Proof script output: 5."}'::jsonb, null);
