insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 2), 3, 'Run it on a VM and time it', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 2) and s.position = 3), 'think', 'explain', 'You time the Mandelbrot program on your new VM and on your first interpreter. One run takes 31 seconds while a video plays, the next takes 24. How do you get timings you can trust and fairly compare?', null, null, '[{"id":"p1","point":"Run each version several times on the same quiet machine and compare a typical value, such as the median, not one run"},{"id":"p2","point":"Throw the output away or send it to a file, so the time spent drawing in the terminal is not measured"},{"id":"p3","point":"Compare the same kind of time for both, such as wall-clock time against wall-clock time, on the same program"},{"id":"p4","point":"Check that both versions print exactly the same picture, because a faster version with different output is broken"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 2) and s.position = 3), 'build', 'build', 'Write a VM with its own program counter and data pointer that reads each instruction and its jump target and updates the cells or the counter. Check that the Hello! program and the first test script still work, then time the Mandelbrot program again and compare with the time from milestone 1.');
