insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 2), null, 1, 'Explain what your compiler does before the VM runs a single instruction, why that makes the VM faster than your first interpreter, and how you showed it.', '[{"id":"t1","concept":"bytecode-compilation","point":"The compiler turns the source into a list with one instruction per command, so comments are removed once and the VM never sees them"},{"id":"t2","concept":"bracket-matching","point":"Jump targets are worked out once with a stack and stored in the bracket instructions, so a jump is a direct move instead of a search"},{"id":"t3","concept":"benchmarking","point":"The speedup is shown by timing the same Mandelbrot program on both versions, several runs each on the same machine, with identical output"}]'::jsonb);
