insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3), 1, 'Merge repeated commands', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3) and s.position = 1), 'think', 'predict', 'Your compiler now merges each run of the same plus, minus, greater-than or less-than command into one instruction with a count. Every other command stays one instruction. How many instructions does it emit for "++++[>+++<-]>." Answer with the total.', null, '{"match":"number_exact","expected":9,"derivation":"The four pluses become one add of 4, then the opening bracket, the greater-than, the three pluses as one add of 3, the less-than, the minus, the closing bracket, the greater-than and the full stop. That is 9 instructions instead of 14 commands. Proof script output: 9."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3) and s.position = 1), 'build', 'build', 'Merge runs of the same command into one instruction with a count. The Hello! program has 70 commands and should shrink to about 26 instructions (27 if you merge only plus, minus and the two moves, 26 if you also merge repeated full stops). Check it still prints Hello! and time Mandelbrot again.');
