insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3) and s.position = 2), 'think', 'trace', 'Cells are bytes that wrap around: adding one to 255 gives 0, and taking one from 0 gives 255. The current cell holds 254 and the loop [+] runs. How many times does its body run? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The first pass takes 254 to 255 and the second takes 255 round to 0, so the closing bracket sees zero and the loop ends after 2 passes. Like a minus loop, it always leaves the cell at zero, which is why both can become one clear instruction. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3) and s.position = 2), 'build', 'build', 'Recognise the loop that only takes one from the current cell, and the one that only adds one, and compile each to a single clear instruction that sets the cell to zero. Run Hello! and Mandelbrot to check the output is unchanged.');
