insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3) and s.position = 3), 'think', 'spot_bug', 'This optimiser turns the clear-cell loop into one instruction, but some programs now go wrong. Find the two problems and say how to fix them.', 'ops = compile(source)      # one op per command, jump targets already stored
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3) and s.position = 3), 'build', 'build', 'Also compile the clear-and-move-right pattern, a clear loop followed by a greater-than, into one instruction. Resolve jump targets only after all rewrites, time Mandelbrot once more, and compare the output with the first interpreter''s output byte for byte. The page expects a large speedup over your first version.');
