insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck') and m.position = 3), null, 1, 'Explain how your optimisations cut the work the VM does on Mandelbrot, and how you know they did not change what the program prints.', '[{"id":"t1","concept":"peephole-optimization","point":"Runs of the same command become one instruction with a count, and the clear loop becomes one clear instruction, each doing exactly what the longer form did"},{"id":"t2","concept":"interpreter-loop","point":"Every instruction costs a trip round the VM''s fetch-and-run loop, so fewer instructions, and a clear that replaces many loop passes, mean far fewer trips"},{"id":"t3","concept":"benchmarking","point":"Each change is timed on the same program and machine against the version before, and its output is compared with the original to prove nothing broke"}]'::jsonb);
