insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1) and s.position = 1), 'think', 'predict', 'The expression 10+25 is typed with no spaces at all. How many tokens should your tokenizer produce? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"Digits that follow each other make one number, so 10 is one token and 25 is another, and the plus sign is a third. Spaces only separate tokens and are not needed here. That gives 3. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1) and s.position = 1), 'build', 'build', 'Read the later steps first, since they will shape your design, as the page advises. Then write tests before the code: 2 * 3 should become the tokens 2, times and 3, and the calculator should print 6 for it. Write a tokenizer that skips spaces and reads a number with several digits, such as 22, as one token.');
