insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1), 2, 'Get the star past the shell', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1) and s.position = 2), 'think', 'predict', 'You type calc 2 * 3 in bash, without quotes, in a folder holding exactly three ordinary files whose names do not start with a dot. How many arguments does your program receive, not counting its own name? Answer with one number.', null, '{"match":"number_exact","expected":5,"derivation":"Before the program starts, bash replaces an unquoted lone star with the names of the files in the folder. The program receives 2, the three file names and 3, so 1 + 3 + 1 = 5. Running set -- 2 * 3 in a folder of three files in Git Bash also gives 5 arguments. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1) and s.position = 2), 'build', 'build', 'Take the expression as one quoted argument, as the page shows with calc and 2 * 3 in single quotes, and print the result on standard output. If the program receives more than one argument, or an argument it cannot read, print a clear message on the error stream and exit with a non-zero status.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1) and s.position = 2), 'hint', '', 'Before your program starts, the shell looks at each word you typed. What does it do with a lone star?', 'generated');
