insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1), 3, 'Whole numbers and fractions', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1) and s.position = 3), 'think', 'predict', 'Your first version stores numbers as integers, where dividing one integer by another drops the remainder. It works through 7 / 2 * 2 from left to right. What does it print? Answer with one number.', null, '{"match":"number_exact","expected":6,"derivation":"7 divided by 2 is 3 with the remainder dropped, and 3 times 2 is 6. With floating-point numbers the division would give 3.5 and the answer would be 7, so the choice of number type changes the result. Python''s whole-number division gives the same 6. Proof script output: 6."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1) and s.position = 3), 'build', 'build', 'Decide how your calculator divides, since the page asks you to handle the difference between integer and floating-point results: keep whole numbers and say so, or use floating-point numbers and print 2 rather than 2.0 when a result is whole. Decide what dividing by zero prints, and add tests for each decision.');
