insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 1), null, 1, 'Explain how your calculator gets from what the user types to a list of numbers and operators, what kind of number a division gives, and what happens with bad input.', '[{"id":"t1","concept":"lexical-analysis","point":"The tokenizer reads characters and groups digits that follow each other into one number token, so 22 is one number, and it skips spaces"},{"id":"t2","concept":"floating-point-numbers","point":"Integer division drops the remainder while floating-point division keeps the fraction, so the calculator chooses one and prints a whole result such as 2 without a decimal part"},{"id":"t3","concept":"cli-subcommands","point":"The expression is passed as one quoted argument so the shell does not expand the star, and bad input gives a message on the error stream and a non-zero exit status"}]'::jsonb);
