insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2) and s.position = 1), 'think', 'predict', 'What should your calculator print for 8 / 4 / 2? Answer with one number.', null, '{"match":"number_exact","expected":1,"derivation":"Division groups from the left, so 8 / 4 is worked out first, giving 2, and 2 / 2 gives 1. Grouping from the right would give 8 / 2, which is 4, and is wrong. Python gives 1.0. Proof script output: 1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2) and s.position = 1), 'build', 'build', 'Support expressions that mix operators. 1 + 1 * 5 should give 6, 2 * 3 + 4 should give 10, and the page''s longer example 1 + 22 - 12 * 33 / 2 should give -175. Add a test where a run of minus signs or a run of divide signs must be worked from the left.');
