insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2), 2, 'Run the shunting yard', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2) and s.position = 2), 'think', 'trace', 'Convert 1 + 2 * 3 + 4 * 5 to postfix with the shunting yard algorithm, treating plus and times as left-associative. What is the largest number of operators waiting on the operator stack at any one time? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The first plus waits, then the first times waits above it because it binds tighter: 2 waiting. The second plus moves the times and then the first plus to the output, since both have higher or equal precedence, and waits alone. The second times waits above it: 2 again. At the end both leave. The most at once is 2. Forgetting to move the equal plus would reach 3. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2) and s.position = 2), 'build', 'build', 'Convert infix to postfix with the shunting yard algorithm before evaluating. Check that the page''s example, 1 times 2 in brackets minus 3 times 4 in brackets, becomes 1 2 * 3 4 * - in postfix, and add a debug option that prints the postfix form so you can see it.');
