insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2) and s.position = 3), 'build', 'build', 'Handle brackets: an opening bracket waits on the stack, and a closing bracket moves operators to the output until it reaches its partner, which is then thrown away. Check that 1 plus 1 in brackets times 5 gives 10 and 10 / (6 - 1) gives 2, and that a bracket without a partner on either side is reported as invalid input.');
