insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2) and s.position = 3), 'example', '', 'Pairing socks from a pile: a right sock with no left sock left in the pile means one is missing, and so does a left sock still waiting when the pile is empty.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 2), null, 1, 'Explain how your calculator decides the order in which operators are applied, including brackets and runs of operators with the same precedence.', '[{"id":"t1","concept":"operator-precedence","point":"Times and divide bind tighter than plus and minus, and among operators of equal precedence the leftmost is applied first"},{"id":"t2","concept":"shunting-yard","point":"Numbers go straight to the output, and an incoming operator first moves every waiting operator of higher or equal precedence to the output, then waits on the stack itself"},{"id":"t3","concept":"bracket-matching","point":"An opening bracket waits on the stack, its closing bracket moves everything above it to the output, and a bracket without a partner is reported as an error"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator'), 3, 'Evaluating postfix and testing', 'Evaluate the postfix form with a stack, reject malformed input, and automate the tests.');
