insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3), 1, 'Trace the stack', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3) and s.position = 1), 'think', 'trace', 'Evaluate the postfix expression 6 2 3 * - 4 + with a stack. What is the most numbers the stack holds at any one time? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"6, 2 and 3 are pushed, so the stack holds 3. Times pops 3 and 2 and pushes 6, leaving 2. Minus pops 6 and 6 and pushes 0, leaving 1. The 4 makes 2, and plus leaves 1, the result 4. The most at once is 3. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3) and s.position = 1), 'build', 'build', 'Evaluate the postfix output with a stack: push each number, and for each operator pop two numbers, apply it and push the result. Check that 1 2 * 3 4 * - gives -10, and that the whole calculator still gives 10 for 2 * 3 + 4 and 2 for 10 / (6 - 1).');
