insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3), 3, 'Compare with a reference', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3) and s.position = 3), 'think', 'explain', 'You compare your calculator with the bc tool on a list of expressions. For 7 / 2 your calculator prints 3.5 but bc prints 3. Is your calculator wrong, and what should your comparison do about it?', null, null, '[{"id":"p1","point":"bc keeps zero decimal places by default, so its 3 comes from a setting, not from a mistake in either tool"},{"id":"p2","point":"A reference is only useful with its settings fixed, for example by giving bc a number of decimal places, or by comparing against a reference that divides the same way"},{"id":"p3","point":"The difference shows a design decision, whole-number or floating-point division, that should be written down as a test of its own"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3) and s.position = 3), 'build', 'build', 'Automate your tests, as the page asks: keep a list of expressions and expected results that includes every example from the earlier steps, run it on every change, and add a check that compares your calculator with a reference, such as bc with its decimal places set or your language''s own expression evaluator, on many generated expressions.');
