insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3) and s.position = 3), 'example', '', 'Two kitchen scales show different weights for the same bag because one rounds to the nearest kilogram. Neither is broken, but you must set them the same way before comparing.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator') and m.position = 3), null, 1, 'Explain how your calculator evaluates the postfix form, and how your tests let you rewrite the parser between steps without breaking results that already worked.', '[{"id":"t1","concept":"stack-evaluation","point":"Each number is pushed, each operator pops two numbers and pushes its result, the second number popped is the left operand, and one number is left at the end"},{"id":"t2","concept":"unit-tests-first","point":"Tests written before the code fix the expected results, such as 2 times 3 plus 4 giving 10, and they stay in place so the rewrite to the shunting yard is checked against them"},{"id":"t3","concept":"differential-testing","point":"Comparing against a reference such as bc on many expressions finds cases the hand-written tests missed, as long as the reference''s settings are fixed"}]'::jsonb);
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-code-comment-remover', 'Build your own code comment remover', 'https://codingchallenges.fyi/challenges/challenge-code-comment-remover') on conflict (source, slug) do nothing;
