insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1), id from concept where slug in ('lexical-analysis', 'regex-matching', 'lexer-states');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1), 1, 'Strip a small Python file', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 1), 'think', 'predict', 'A Python file has three lines. The first holds only a comment. The second holds code followed by a comment. The third holds code and no comment. Your tool removes every comment, trims the spaces left at the end of a line, and drops a line completely when nothing is left on it. How many lines does the cleaned file have? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The first line is only a comment, so nothing is left and it is dropped. The second line keeps its code and loses the comment. The third line is unchanged. That leaves 2 lines. Python''s tokenize module finds the same 2 comments on the same input. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 1), 'build', 'build', 'Make your tool read a Python file named on the command line, or standard input when no name is given, and write the code to standard output with every hash comment removed. Try it on the page''s Python example, a list built from a range with comments around it: only the line that builds the list should remain. Then run it over Python files from the Coding Challenges shared solutions repository and check that the cleaned files still run.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 1), 'hint', '', 'Go line by line and ask what is left on each one once the comment has gone.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 1), 'example', '', 'Crossing out the margin notes in a recipe leaves the steps in place, and a line that held only a note is left blank, so you can remove it.', 'generated');
