insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 2), 'build', 'build', 'Replace the pattern with a scanner that walks the source, tracks whether it is inside a single-quoted or double-quoted string, and only removes from a hash that it finds outside a string. Test it on a line that prints a colour code written with a hash.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 2), 'hint', '', 'Think of a line of Python where a hash appears but no comment does.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 2), 'example', '', 'In an email address the at sign is part of the address, while on a price board the same sign means each. The surroundings decide what a symbol means.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1), 3, 'Track both kinds of quote', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 3), 'think', 'predict', 'A Python line assigns to msg a double-quoted string holding the words it''s, a space, a hash and the word fine. Then comes a plus sign and a single-quoted string holding just a hash. The line ends with two spaces, a hash and the word note. Your scanner tracks single and double quotes correctly. How many hash characters are left on the line after it removes the comment? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The apostrophe in it''s sits inside a double-quoted string, so it does not open a new string, and the hash after it is text. The single-quoted string holds the second hash, also text. Only the third hash is in code, and it starts the comment. So 2 hash characters remain. Python''s tokenize module agrees. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 3), 'build', 'build', 'Handle a backslash before a quote mark, which keeps the string open, and triple-quoted strings, which can run over several lines and may contain hash characters. Docstrings are strings, not comments, so leave them in.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 3), 'hint', '', 'Inside a double-quoted string, which quote mark is the only one that can end it?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1) and s.position = 3), 'example', '', 'A remark in round brackets is not closed by a square bracket that appears inside it. Only the matching kind of bracket ends it.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 1), null, 1, 'Explain why searching each line for a hash removes too much, and how your tool decides which hash characters start a comment.', '[{"id":"t1","concept":"regex-matching","point":"A pattern such as a hash followed by anything matches wherever a hash appears, so it cannot tell a comment from a hash inside a string"},{"id":"t2","concept":"lexer-states","point":"The tool remembers whether it is in code or inside a string, and only a hash met while in code starts a comment, which then runs to the end of the line"},{"id":"t3","concept":"lexical-analysis","point":"The tool reads the source as a series of pieces, code, strings and comments, and writes every piece back unchanged except the comments"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover'), 2, 'Slash comments in JavaScript, C and C++', 'Remove line and block comments, carry the scanner''s state across lines, and check the cleaned program still behaves the same.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2), id from concept where slug in ('lexer-states', 'word-state-machine', 'differential-testing');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2), 1, 'Line and block comments', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 1), 'think', 'predict', 'A JavaScript file has four lines. Line one is a block comment that opens and closes on that line. Line two stores the web address https colon slash slash example dot com in a double-quoted string, then has two slashes and the words home page. Line three stores a file pattern, src slash star dot js, in a double-quoted string. Line four sets a counter to zero, then has two slashes and the word counter. How many comments does the file contain? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"Line one is a block comment. The two slashes in the web address and the slash star in the file pattern are inside strings, so they are text. The two slashes after the address and after the counter start real line comments. That is 1 + 1 + 1 = 3. A tool that ignored strings would also cut the address and would open a block comment at the file pattern that swallows the rest of the file. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 1), 'build', 'build', 'Add JavaScript: remove line comments that start with two slashes and block comments from slash star to star slash, and leave strings in single quotes, double quotes and backticks alone. Run it on the page''s JavaScript example, a factorial function with a block comment above it and line comments inside it: the function should come out with its code unchanged and no comments left.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 1), 'hint', '', 'Mark every pair of slashes and every slash star, then cross out the ones that sit between quote marks.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 1), 'example', '', 'A news story that quotes someone saying stop here does not tell the reader to stop. Quoted words are part of the text.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2), 2, 'Block comments across lines', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 2), 'think', 'trace', 'A C file has five lines. Line one declares x. Line two declares y, then opens a block comment with slash star and the words the next value. Line three holds only the words is set below. Line four starts with the words in one step, closes the comment with star slash, and then declares z. Line five returns the sum. A buggy tool scans each line on its own and starts every line in the code state. How many lines of its output still contain words from the comment? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"On line two the comment opens and the buggy tool removes the rest of that line, which is correct by luck. Line three starts in the code state, so is set below is kept as if it were code. Line four also starts in the code state, so in one step and the star slash are kept. Lines three and four leak comment text, so 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 2), 'build', 'build', 'Carry the scanner''s state from one line to the next, or scan the whole file as one stream, so a block comment can open on one line and close several lines later. Decide what to do with lines that a block comment leaves empty, and check that the code after the comment still starts where it should.');
