insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2), 3, 'Character literals in C', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 3), 'think', 'predict', 'In C a single character is written between single quotes, and that character can be a double quote. A C file has two lines. Line one stores a double quote character between single quotes, then has two slashes and the words a double quote. Line two sets n to zero, then has two slashes and the words a counter. A scanner knows double-quoted strings, treats single quotes as ordinary characters, and ends any open string at the end of a line. How many comments does it remove? Answer with one number.', null, '{"match":"number_exact","expected":1,"derivation":"On line one the scanner skips the single quote as ordinary, then sees the double quote and thinks a string has started. Everything after it on the line, including the two slashes, is treated as string text, until the end of the line closes it. Line two is read correctly and its comment is removed. So 1 comment is removed instead of 2. Proof script output: 1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 3), 'build', 'build', 'Add C and C++: the same two comment styles, plus character literals in single quotes, which can hold a quote mark or a backslash escape. Run it on the page''s C example, a factorial function with an assert and comments about checking validity, the base case and the other cases: the assert and every line of code must survive. Compile the original and the cleaned file and check that both give the same results.');
