insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 3), 'example', '', 'A proofreader who thinks every apostrophe opens a quotation loses track in a sentence about the dog''s bone and the cat''s bowl.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2), 4, 'Do not glue code together', 15);
