insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 4), 'build', 'build', 'Replace each removed block comment with a single space, or with the line breaks it contained, and add tests where a comment sits between two words with no spaces and where one spans lines. Compile or run the original and the cleaned versions on the same inputs and compare their outputs.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 4), 'hint', '', 'Try it on a declaration where the comment is the only thing between the type and the name.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2) and s.position = 4), 'example', '', 'Cutting a sticker off a page that was the only thing between two words makes the words run into each other. Leaving a gap the size of a space keeps them readable.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 2), null, 1, 'Explain how your tool finds comments in JavaScript and C when comment markers can also appear inside strings and block comments can run over many lines, and how you would show that the cleaned program still behaves the same.', '[{"id":"t1","concept":"lexer-states","point":"The scanner is always in one context, such as code, string, character literal, line comment or block comment, and two slashes or slash star only start a comment when it is in code"},{"id":"t2","concept":"word-state-machine","point":"The context is remembered from one line to the next, so a block comment stays open until its star slash, the way a word counter keeps its inside-a-word state across chunks"},{"id":"t3","concept":"differential-testing","point":"Compile or run the original and the cleaned program on the same inputs and compare the outputs, with the original acting as the reference"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover'), 3, 'Comments that must stay', 'Support Go, keep its doc comments, and keep the directives that linters and build tools read.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3), id from concept where slug in ('meaningful-comments', 'regex-matching', 'unit-tests-first');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3), 1, 'Go doc comments', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 1), 'think', 'predict', 'A Go file holds five comments. One sits directly above the package line. One is followed by a blank line and then a type declaration. One sits directly above a top-level function. One is inside that function''s body, directly above an indented var declaration. One is at the end of the line that returns the result. Using the page''s rule for doc comments, how many of the five does your tool keep? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"A doc comment sits directly above a top-level package, const, func, type or var declaration with no blank line between. The comment above the package line and the one above the top-level function qualify. The one before the type has a blank line in between, the var inside the function body is not at the top level, and the one at the end of the return line is not above any declaration. So 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 1), 'build', 'build', 'Add Go, which uses the same comment markers as C plus raw strings in backticks. Keep doc comments, the comments directly above a top-level package, const, func, type or var declaration with no blank line in between, and remove every other comment. Check by running go doc on the package before and after cleaning: the output should be identical.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 1), 'hint', '', 'For each comment, ask whether the very next line is a declaration at the top level of the file.', 'generated');
