insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 2), 'build', 'build', 'Treat a run of comment lines with nothing between them as one group, and keep or remove the whole group. Write a test for each rule before the code: a one-line doc comment, a three-line one, one separated from its declaration by a blank line, and one inside a function body.');
