insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 2), 'example', '', 'A caption that runs over three lines belongs to the photo below it, all three lines, not only the line touching the photo.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3), 3, 'Keep tool directives', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 3), 'think', 'predict', 'Across two files there are five comments, and none of them sits directly above a declaration. In Python, a noqa comment naming one rule sits at the end of a line that assigns a lambda, and a full-line comment says tidy this later. In Go, one comment is two slashes followed directly by go:build ignore, one is two slashes followed directly by go:generate and a command, and one is two slashes, a space, and then go:generate. In Go a directive has no space between the slashes and the tool name. How many of the five comments does your tool keep? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"The noqa comment tells the flake8 linter to skip a rule on that line, so it stays. The go:build and go:generate comments are directives that the Go tools read, so they stay. The tidy note is for people, and the comment with a space before go:generate is not a directive, because Go only recognises a directive written with no space, so both are removed. That keeps 3. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 3), 'build', 'build', 'Keep linter and build directives: in Python, noqa comments, as in the page''s lambda example, and in Go, directives such as go:generate and go:build ignore. Recognise them with a precise pattern applied only to comment text your scanner has already found, never to the raw line. Run your earlier Python, JavaScript and C tests again to check nothing else changed.');
