insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3) and s.position = 3), 'example', '', 'A sticker on a parcel saying fragile is an instruction to the courier, while one saying happy birthday is for the person. Peeling off every sticker loses the instruction.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover') and m.position = 3), null, 1, 'Explain which comments your tool keeps and why removing them would change things, how it recognises them, and how you make sure that adding these rules did not break the earlier languages.', '[{"id":"t1","concept":"meaningful-comments","point":"Go doc comments become the package documentation, and directives such as noqa, go:generate and go:build change what a linter checks or what gets built, so removing them changes more than the look of the file"},{"id":"t2","concept":"regex-matching","point":"Directives are recognised with a precise pattern, such as two slashes directly followed by a lowercase tool name and a colon, applied only to comments the scanner has already found"},{"id":"t3","concept":"unit-tests-first","point":"Each new rule gets a small failing test written first, and the tests for earlier languages stay and run again, so a new rule cannot silently break them"}]'::jsonb);
