insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1), 1, 'Split the URL', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1) and s.position = 1), 'think', 'predict', 'cccurl is given http://eu.httpbin.org/ip, which has no port written in it. Which port does it connect to? Answer with one number.', null, '{"match":"number_exact","expected":80,"derivation":"The URL names no port, so the usual port of its scheme is used. The scheme is http, whose usual port is 80. Proof script output: 80."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1) and s.position = 1), 'build', 'build', 'Read a URL from the command line and split it into the scheme, host, port and path. Print a line saying which host you are connecting to, then the request you would send, without sending anything yet. Both http://eu.httpbin.org/get and http://eu.httpbin.org:80/get should print the same three lines: GET /get HTTP/1.1, a Host header of eu.httpbin.org and an Accept header of */*.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1) and s.position = 1), 'hint', '', 'The scheme at the front of the URL decides which port is used when the URL does not name one.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1) and s.position = 1), 'example', '', 'A phone number dialled without an area code goes to your own area. Leaving a part out does not mean there is none; a usual value fills the gap.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1), 2, 'Write the request line', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1) and s.position = 2), 'think', 'predict', 'The user types http://eu.httpbin.org, with nothing at all after the host name. What request line does cccurl send? Answer with the request line only.', null, '{"match":"text_ci","expected":"GET / HTTP/1.1","derivation":"A request line always holds a method, a path and a version. The method is GET, the version is HTTP/1.1, and a URL with no path asks for the root of the site, which is the single slash. So the line is GET, a space, a slash, a space and HTTP/1.1. Proof script output: GET / HTTP/1.1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1) and s.position = 2), 'build', 'build', 'Build the request as text: the request line, a Host header and an Accept header, each line ending in a carriage return and a line feed, then an empty line. Check a URL with no path, and reject a URL whose scheme is not http, such as https or ftp, with a message on the error stream and a non-zero exit status.');
