insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 1), null, 1, 'Explain how cccurl turns the URL typed on the command line into the exact text of a GET request, and what it does with a URL it cannot handle.', '[{"id":"t1","concept":"url-parsing","point":"It splits the URL into scheme, host, port and path, using port 80 when no port is given and a single slash when there is no path"},{"id":"t2","concept":"http-message-format","point":"The request is a request line with the method, path and version, then the Host and Accept headers, each line ending in a carriage return and line feed, then an empty line"},{"id":"t3","concept":"cli-subcommands","point":"The URL comes from the command-line arguments, and a missing URL or a scheme other than http gives a message on the error stream and a non-zero exit status"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl'), 2, 'Send it and read the reply', 'Open a TCP connection, send the request, read until the server closes, and print the body or everything.');
