insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2), 1, 'Send over a socket', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 1), 'think', 'trace', 'The server''s reply is 250 bytes long, all of it has already arrived, and then the server closes the connection. cccurl reads into a buffer that holds 100 bytes, and each read hands back as many waiting bytes as fit. How many bytes does the last read that hands back data return? Answer with one number.', null, '{"match":"number_exact","expected":50,"derivation":"The first read fills the buffer with 100 bytes and so does the second, leaving 50. The third read hands back those 50, which is fewer than the buffer holds, and the read after that reports the end because the server has closed. Proof script output: 50."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 1), 'build', 'build', 'Open a TCP connection to the host and port, add a Connection: close header to the request, send it, and read until the server closes the connection, printing everything you received. For http://eu.httpbin.org/get the reply should start with HTTP/1.1 200 OK, carry a Content-Type of application/json, and end with a JSON body that echoes your Host and Accept headers and the URL.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 1), 'hint', '', 'Each read stops at the size of the buffer. Work out what is left over after every full read.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 1), 'example', '', 'Carrying 25 books in a box that holds 10 takes three trips, and the last box has only 5 books in it.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2), 2, 'Know when the reply is over', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 2), 'think', 'explain', 'cccurl reads until the server closes the connection. Explain what happens if you leave out the Connection: close header, and why HTTP/1.1 behaves that way.', null, null, '[{"id":"p1","point":"HTTP/1.1 keeps the connection open after a reply by default, so the server does not close it"},{"id":"p2","point":"A client that waits for the close then hangs after the whole reply has arrived, until the server gives up and times out"},{"id":"p3","point":"Connection: close asks the server to close after this reply, so the end of the stream marks the end of the reply"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 2), 'build', 'build', 'Leave out the Connection: close header once on purpose and watch cccurl sit waiting after the reply has arrived, then put the header back.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 2), 'hint', '', 'Unless told otherwise, what does an HTTP/1.1 server do with the connection after it has replied?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 2), 'example', '', 'A phone call where nobody hangs up stays open in silence. When one person says goodbye and hangs up, the other knows the call is over.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2), 3, 'Verbose mode', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 3), 'think', 'predict', 'A reply is a status line, three header lines, an empty line, and then a body of three lines whose middle line is empty. With -v, cccurl puts a less-than sign in front of the status line, every header line and the empty line that ends the headers, and prints the body unmarked. How many lines of output begin with the less-than sign? Answer with one number.', null, '{"match":"number_exact","expected":5,"derivation":"Only the first empty line ends the headers. Before it come the status line and three headers, 4 lines, and the empty line itself is marked too, making 5. The empty line inside the body comes after the first empty line, so it belongs to the body and is not marked. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 3), 'build', 'build', 'By default print only the body of the reply. With -v, print every line you sent with a greater-than sign in front, then every line of the reply head with a less-than sign in front, then the body. As on the page, the sent block ends with a line holding only the greater-than sign, and the received head ends with a line holding only the less-than sign.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 3), 'hint', '', 'Find the first empty line in the reply. Which side of it does each line fall on?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2) and s.position = 3), 'example', '', 'A letter has an address block, a gap, then the letter itself. A gap between two paragraphs further down does not make those paragraphs part of the address.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 2), null, 1, 'Explain how cccurl gets the whole reply from the server and how it decides which parts to print with and without -v.', '[{"id":"t1","concept":"tcp-sockets","point":"It opens a TCP connection to the host and port, writes the request bytes, and reads the reply from the same two-way byte stream"},{"id":"t2","concept":"stream-read-contract","point":"It reads in a loop, because each read may return only part of the reply, and stops when a read reports that the server closed the connection"},{"id":"t3","concept":"message-framing","point":"With Connection: close the end of the stream marks the end of the reply, and the first empty line splits the head from the body"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl'), 3, 'Methods and bodies', 'Choose the method with -X, send a body with -d and headers with -H, and support DELETE, POST and PUT.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3), id from concept where slug in ('cli-subcommands', 'rest-api-design', 'message-framing', 'idempotency');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3), 1, 'Choose the method', 15);
