insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 1), 'build', 'build', 'Add -X to choose the method, and send DELETE to http://eu.httpbin.org/delete. The JSON reply should echo your headers and the URL, with an empty data field and a json field of null.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 1), 'hint', '', 'Walk the arguments one at a time and write down what the parser thinks the URL is after each one.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 1), 'example', '', 'A waiter hears table four, two coffees, writes down an order for table four, and then also counts four as an order of its own. The same word was used twice.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3), 2, 'Send a body', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 2), 'think', 'predict', 'cccurl is run with -X POST on http://eu.httpbin.org/post, with -d giving the four-letter word café, whose e is accented, and with -H setting a plain text Content-Type. What value does cccurl put in the Content-Length header? Answer with one number.', null, '{"match":"numbers_all","expected":[5],"derivation":"Content-Length counts the bytes of the body, not its letters. c, a and f are one byte each in UTF-8 and the accented e takes two, so café is 4 letters but 5 bytes. Matched with numbers_all, so an answer that also mentions the letter count or the encoding still passes. Proof script output: [5]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 2), 'build', 'build', 'Add -d for a body and -H for extra headers. Send the body after the empty line, with a Content-Length header giving its size in bytes. The page''s POST to http://eu.httpbin.org/post with the body {"key": "value"} and a Content-Type of application/json should come back with a Content-Length of 16 among the echoed headers, and the same key and value under json.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 2), 'hint', '', 'The length is measured in the units that travel over the connection, not in letters.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 2), 'example', '', 'The word naïve has 5 letters, but its ï takes 2 bytes in UTF-8, so it is 6 bytes long.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3), 3, 'PUT and retries', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 3), 'think', 'predict', 'cccurl now supports GET, DELETE, POST and PUT. A request is idempotent when sending it twice leaves the server in the same state as sending it once. Under the rules of HTTP, how many of these four methods are idempotent? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"GET only reads, so repeating it changes nothing. PUT replaces the resource with the body, and doing that twice leaves the same resource. DELETE removes it, and a second delete leaves it removed. POST asks the server to create or submit something, and a second POST can create a second resource. That makes GET, PUT and DELETE, 3. The proof runs each method once and twice on a small simulated store and compares. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 3), 'build', 'build', 'Support PUT, which sends a body just as POST does. A PUT to http://eu.httpbin.org/put with the body {"key": "value2"} and a JSON Content-Type should echo a Content-Length of 17 and the new value under json.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 3), 'hint', '', 'For each method, picture the server''s data after one request and after the same request twice.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3) and s.position = 3), 'example', '', 'Setting a thermostat to 20 degrees twice leaves it at 20, but pressing the up button twice raises it two steps.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3), null, 1, 'Explain how cccurl builds DELETE, POST and PUT requests from its options, how the server knows where a body ends, and which of these requests are safe to resend after a reply is lost.', '[{"id":"t1","concept":"cli-subcommands","point":"-X sets the method, -d gives the body and -H adds a header, and each option takes its value from the argument right after it"},{"id":"t2","concept":"rest-api-design","point":"The method says what to do with the resource the path names: GET reads it, DELETE removes it, POST creates or submits, and PUT replaces it with the body"},{"id":"t3","concept":"message-framing","point":"The body follows the empty line, and a Content-Length header gives its size in bytes so the server knows where it ends"},{"id":"t4","concept":"idempotency","point":"GET, PUT and DELETE are idempotent, so resending them after a lost reply is safe, while resending a POST can create a second resource"}]'::jsonb);
