insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 1), 'think', 'predict', 'A line holds apple, a tab, banana, a tab, cherry. What does cut -f2 print for that line?', null, '{"match":"text_ci","expected":"banana","derivation":"The tab is the default delimiter, so the line has three fields: apple, banana and cherry. Fields are numbered from 1, so field 2 is banana. Proof script output: banana."}'::jsonb, null);
