insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 1), 'hint', '', 'Count the fields from the left, starting at 1, not at 0.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 1), 'example', '', 'In a row of three seats labelled first, second and third, the second seat is the middle one.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1), 2, 'Choose the delimiter', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 2), 'think', 'predict', 'A line holds red, two commas in a row, then blue. cut -d, -f2 prints the second field followed by a newline. How many bytes is that output line, counting the newline?', null, '{"match":"number_exact","expected":1,"derivation":"cut splits at every comma, so the two commas in a row make three fields: red, an empty field and blue. Field 2 is empty, so the output line holds only the newline, which is 1 byte. A splitter that merged the two commas would wrongly print blue and a newline, 5 bytes. GNU cut piped into wc -c gives 1. Proof script output: 1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 2), 'build', 'build', 'Add -d to set the delimiter, keeping tab as the default. cut -f1 -d, on fourchords.csv, cut to its first five lines with head, should print Song title and then the quoted titles of 10000 Reasons, 20 Good Reasons, Adore You and Africa. cut -f1 on sample.tsv should still print f0, 0, 5, 10, 15 and 20.');
