insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1), 3, 'Field lists', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 3), 'think', 'predict', 'A line holds red,green,blue,black. You run cut -d, -f3,1 on it. Write the output line exactly as cut prints it.', null, '{"match":"text_ci","expected":"red,blue","derivation":"cut treats the field list as a set of wanted fields and prints them in the order they appear in the line, not the order they were typed. So -f3,1 prints field 1 then field 3, joined by one comma: red,blue. GNU cut prints red,blue. Proof script output: red,blue."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 3), 'build', 'build', 'Accept a field list written with commas, such as -f1,2, or with spaces inside quotes, such as -f "1 2". Print the chosen fields in line order, joined by one delimiter. cut -f1,2 on sample.tsv should print f0 and f1, then 0 and 1, and so on to 20 and 21, separated by tabs. cut -d, -f "1 2" on fourchords.csv should start with Song title,Artist. A field of 0, a list that is not numbers, or no -f at all should print a message on the error stream and exit with a non-zero status, as the real cut does.');
