insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1), 4, 'Windows line endings', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 4), 'think', 'predict', 'A file saved on Windows holds the line x,y, ending with a carriage return and then a newline. cut -d, -f2 prints that line''s second field followed by a newline. How many bytes is that output line?', null, '{"match":"number_exact","expected":3,"derivation":"cut only treats the newline as the end of the line. The carriage return is an ordinary byte to it, so it stays at the end of the last field. Field 2 is y and the carriage return, then cut writes a newline: 3 bytes. GNU cut piped into wc -c gives 3. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 4), 'build', 'build', 'Remove only the newline from each line before splitting, and write one newline after each output line. Run your cut and the real one on a file with Windows line endings and on a file whose last line has no final newline, and make the outputs match byte for byte.');
