insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1) and s.position = 4), 'example', '', 'If a Windows line reads 5,7 and then the carriage return, asking for field 1 gives just 5, because the stray byte sits at the far end of the line, inside the last field.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 1), null, 1, 'Explain how your cut turns one input line into one output line for a command such as cut -d, -f1,3, and what it does when the command line is wrong.', '[{"id":"t1","concept":"delimited-fields","point":"It splits the line at every delimiter and numbers the fields from 1, so two delimiters in a row make an empty field"},{"id":"t2","concept":"delimited-fields","point":"It prints the chosen fields in the order they appear in the line, joined by one delimiter, whatever order the list was typed in"},{"id":"t3","concept":"line-endings","point":"It removes only the newline before splitting and adds one after each output line, so a carriage return stays in the last field"},{"id":"t4","concept":"cli-subcommands","point":"A field of 0, a list that is not numbers or a missing -f gives a message on the error stream and a non-zero exit status"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut'), 2, 'Pipes and pipelines', 'Read from standard input, stream line by line, and use cut as one step in a pipeline with uniq and wc.');
