insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 1), 'build', 'build', 'When no file name is given, or the name is a single dash, read standard input. Piping the last five lines of fourchords.csv into cut -d, -f "1 2" should print Young Volcanoes with Fall Out Boy, You Found Me with The Fray, You''ll Think Of Me with Keith Urban, You''re Not Sorry with Taylor Swift and Zombie with The Cranberries, and adding a dash as the file name should print exactly the same.');
