insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 1), 'example', '', 'A shop that only accepts parcels with a printed address turns away the courier who hands one over in person. The parcel is the same either way; only the way it arrives differs.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2), 2, 'One line at a time', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 2), 'think', 'explain', 'Your cut could be handed a 30 GB log, or the output of a program that never stops writing. Why should it print each output line as soon as it has read that input line, rather than reading everything first and printing at the end?', null, null, '[{"id":"p1","point":"Holding only the current line keeps memory small and the same whatever the input size, so a huge file cannot run it out of memory"},{"id":"p2","point":"An input that never ends never reaches a printing stage at the end, so nothing would ever come out"},{"id":"p3","point":"Output starts at once, so the next tool in the pipe, such as head, can work, and even stop the pipeline, while cut is still reading"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 2), 'build', 'build', 'Read and print one line at a time, keeping only the current line in memory. Check that cut, then head with five lines, on fourchords.csv prints at once, and that a large file does not make memory grow.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 2), 'hint', '', 'Think about what the end of the input means for a program that never stops writing.', 'generated');
