insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2), 3, 'cut, uniq and wc together', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 3), 'think', 'predict', 'A small CSV holds four songs, and the artist column reads Toto, Toto, Queen and Toto, in that order. You run cut for the artist field, pipe it into uniq, then into wc -l. What number does wc print?', null, '{"match":"number_exact","expected":3,"derivation":"cut prints Toto, Toto, Queen, Toto. uniq only drops a line that repeats the line just before it, so the second Toto goes but the last Toto stays, because Queen sits between them: Toto, Queen, Toto. wc counts 3 lines, although there are only 2 different artists. Putting sort before uniq would give 2. GNU cut, uniq and wc give 3, and 2 with sort. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 3), 'build', 'build', 'Run your cut in a pipeline: the artist field of fourchords.csv, comma-separated, into uniq, into wc -l. It should print 155, and you can use the wc you built in the first challenge. Then put sort before uniq and explain why the number changes.');
