insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2) and s.position = 3), 'example', '', 'In a queue, each person only checks whether the person directly in front wears the same colour hat. Two red hats with a blue hat between them never meet.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-cut') and m.position = 2), null, 1, 'In the pipeline cut, then uniq, then wc -l, explain where your cut gets its input, how much of it it holds at once, and why the order of the tools changes the answer.', '[{"id":"t1","concept":"stdin-vs-file","point":"With no file name, or a dash, it reads standard input with the same line loop it uses for a file"},{"id":"t2","concept":"streaming-constant-memory","point":"It reads, cuts and prints one line at a time, so memory does not grow with the input and output starts at once"},{"id":"t3","concept":"unix-pipelines","point":"Each tool reads the previous one''s output as lines on standard input and writes lines to standard output"},{"id":"t4","concept":"unix-pipelines","point":"uniq only removes duplicates that are next to each other, so counting distinct values needs sort before uniq"}]'::jsonb);
