insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1), 1, 'What a common subsequence is', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1) and s.position = 1), 'think', 'predict', 'Take the words SPRING and STRING. How long is their longest common subsequence? Answer with one number.', null, '{"match":"number_exact","expected":5,"derivation":"The words differ only in the second letter, P against T. Skipping that letter in each leaves S, R, I, N, G in both, in the same order, and no common subsequence can be 6 long because the words are not equal. GNU diff on the two words written one letter per line marks only one letter removed. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1) and s.position = 1), 'build', 'build', 'Set up a unit testing library and write tests before any code. Start with the page''s cases: ABCDEF with ABCDEF gives ABCDEF, ABC with XYZ gives an empty string, AABCXY with XYZ gives XY, two empty strings give an empty string, and ABCD with AC gives AC. Run them and watch them fail.');
