insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1) and s.position = 2), 'think', 'trace', 'Take ABCD and ACBD. More than one common subsequence may tie for the longest, so give only its length. How long is the longest common subsequence? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"A, then B or C, then D appears in both: ABD and ACD both work. All four letters cannot work, because B comes before C in the first string and after it in the second. So the length is 3, reached by two different subsequences. GNU diff, one letter per line, marks one letter removed out of four. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1) and s.position = 2), 'build', 'build', 'Build a table with one row per prefix of the first string and one column per prefix of the second. Each cell holds the length for those two prefixes: one more than the cell up and to the left when the letters match, otherwise the larger of the cell above and the cell to the left.');
