insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1) and s.position = 3), 'example', '', 'Looking for a friend in two queues, stepping past only the person at the front of the first queue will never help if the mismatch is at the front of the second.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1), 4, 'Tests that allow ties', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1) and s.position = 4), 'think', 'explain', 'A classmate''s LCS function returns AC for ABC and ACB, and your test expects AB. Their code may be correct. Why, and how would you write tests that do not fail correct code?', null, null, '[{"id":"p1","point":"Two strings can have several longest common subsequences of the same length, here AB and AC, so expecting one exact string can reject a correct answer"},{"id":"p2","point":"A better test checks that the result has the right length and is a subsequence of both strings"},{"id":"p3","point":"Exact-string tests are still fine for cases with only one longest answer, such as the ones on the page"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1) and s.position = 4), 'build', 'build', 'Add your own edge cases: one empty string, a single letter, no letters in common, one string inside the other and a case with tied answers. Think about how the time and memory grow with the lengths of the strings.');
