insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 1), null, 1, 'Explain how your function finds the longest common subsequence of two strings, why it uses a table, and how writing tests first shaped it.', '[{"id":"t1","concept":"longest-common-subsequence","point":"When the current letters match they extend the common subsequence, otherwise the answer is the longer of skipping a letter from one string or from the other"},{"id":"t2","concept":"dynamic-programming","point":"Each table cell holds the answer for two prefixes and is computed once from its neighbours, so the work is the number of cells instead of an exponential search"},{"id":"t3","concept":"unit-tests-first","point":"The tests were written before the code, from the page''s cases and edge cases such as empty strings and no common letters, so they defined what correct means and failed first"}]'::jsonb);
