insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 2), 1, 'Removed lines', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 2) and s.position = 1), 'think', 'predict', 'The old file holds apple, banana, cherry and date, one per line. The new file holds apple, cherry and egg. How many lines does the diff mark as removed, with a less-than sign? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The longest run of lines both files share in order is apple then cherry. Every old line outside it is removed: banana and date, so 2. Egg is the one added line. GNU diff marks the same two lines with a less-than sign. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 2) and s.position = 1), 'build', 'build', 'Make your LCS work on lists of lines as well as strings, comparing whole lines. Write the page''s two line tests first: in the short one the result is the single shared line this is the lcs, and in the paragraph one it is the two shared lines about the weekly challenge and about writing a full application.');
