insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 2) and s.position = 2), 'think', 'predict', 'The old file holds the lines one and two, each ending in a plain newline. Someone saves the same two lines on Windows, so each now ends in a carriage return and a newline. Your ccdiff splits at newlines and compares the lines exactly as read. How many lines does it mark as removed? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"Splitting at the newline leaves the carriage return on the end of every new line, so one with a carriage return is not equal to one. No line is shared, both old lines are removed and both new lines added, so 2. GNU diff on the same files marks 2 lines removed and 2 added. Proof script output: 2."}'::jsonb, null);
