insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 2), null, 1, 'Explain how your tool turns two files into lines marked with less-than and greater-than signs, and why two lines that look the same on screen can still be reported as different.', '[{"id":"t1","concept":"longest-common-subsequence","point":"The same LCS algorithm runs on lists of lines, comparing whole lines, and the lines it finds are the ones that stay the same"},{"id":"t2","concept":"edit-scripts","point":"Old lines outside the common lines are printed as removed with a less-than sign, new lines outside them as added with a greater-than sign, in file order"},{"id":"t3","concept":"line-endings","point":"Lines are compared byte for byte, so a carriage return, trailing space or missing final newline makes them differ unless the tool strips or reports them"}]'::jsonb);
