insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 3), 2, 'How the table grows', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 3) and s.position = 2), 'think', 'predict', 'Comparing a file of n lines with a file of m lines needs a table of about n times m cells. If both files become twice as long, about how many times more cells does the table need? Answer with one number.', null, '{"match":"number_exact","expected":4,"derivation":"Twice as many rows and twice as many columns gives two times two as many cells, so 4 times as many. Time grows the same way, because each cell is filled once. This is why the plain table is fine for small files and hopeless for two files of a million lines each. Proof script output: 4."}'::jsonb, null);
