insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 3), 3, 'Trim what is shared', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 3) and s.position = 3), 'think', 'predict', 'Two versions of a file have 1000 lines each and differ only in line 500, which was rewritten. Before building the table, ccdiff strips the lines both files share at the start and at the end. How many lines of the old file are left to go into the table? Answer with one number.', null, '{"match":"number_exact","expected":1,"derivation":"Lines 1 to 499 match at the start and are stripped, and lines 501 to 1000 match at the end and are stripped. Only line 500 is left from each file, so the table shrinks from about a million cells to one. GNU diff on the same files reports a single change, 500c500. Proof script output: 1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 3) and s.position = 3), 'build', 'build', 'Strip the shared lines at the start and end before building the table. Then write a check that runs the real diff and ccdiff on many pairs of files and compares the lines starting with a less-than or greater-than sign, since the real diff also prints change headers that ccdiff does not.');
