insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-diff') and m.position = 3), null, 1, 'Explain what ccdiff does from the moment it is run to the moment it exits, what it costs in time and memory for large files, and how you would show its output matches the real diff.', '[{"id":"t1","concept":"cli-subcommands","point":"It takes two file paths, reports a missing argument or unreadable file on the error stream with a non-zero exit status, and prints nothing when the files are the same"},{"id":"t2","concept":"dynamic-programming","point":"It fills a table with one cell for each pair of line prefixes, each computed once from its neighbours, then walks back through it to produce the differences"},{"id":"t3","concept":"time-space-complexity","point":"Time and memory grow with the product of the two file lengths, so doubling both files makes it four times slower, and trimming shared lines or a smarter algorithm such as Myers helps"},{"id":"t4","concept":"differential-testing","point":"It runs the real diff and ccdiff on the same pairs of files, including edge cases, and compares the removed and added lines"}]'::jsonb);
