insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1), 1, 'Encode the name', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1) and s.position = 1), 'think', 'predict', 'Your resolver writes the name dns.google.com into the question of a query, as length-prefixed labels ending with a zero byte. How many bytes does the encoded name take? Answer with one number.', null, '{"match":"number_exact","expected":16,"derivation":"The labels are dns, google and com. Each costs one length byte plus its letters, so 1 + 3, 1 + 6 and 1 + 3, which is 15, and the zero byte at the end makes 16. The proof encodes the name into a Buffer and takes its length. Proof script output: 16."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1) and s.position = 1), 'build', 'build', 'Write a routine that encodes a host name as labels, each preceded by its length, followed by a zero byte. For dns.google.com you should get the byte 3, then dns, the byte 6, then google, the byte 3, then com, and the zero byte.');
