insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1), 2, 'Set the flags', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1) and s.position = 2), 'think', 'predict', 'The 16-bit flags field is sent as two bytes, high byte first. Reading the first byte from its leftmost bit, it holds QR as one bit, the opcode as four bits, and then AA, TC and RD as one bit each. A query has only recursion desired, RD, set. What is the value of the first flags byte? Answer with one decimal number.', null, '{"match":"number_exact","expected":1,"derivation":"QR takes the top bit, the opcode the next four, then AA and TC, so RD is the last, lowest bit of the first byte. With only RD set, that byte is 00000001 in binary, which is 1, and the second byte is 0. The proof packs the bits into a Buffer and reads the byte back. Proof script output: 1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1) and s.position = 2), 'build', 'build', 'Build the 12-byte header: the ID 22, the flags with recursion desired set, a question count of 1 and zero for the answer, authority and additional counts, each written as two bytes, high byte first. In hex the header should read 00 16 01 00 00 01 00 00 00 00 00 00.');
