insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1), 3, 'Put the query together', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1) and s.position = 3), 'think', 'predict', 'The full query for dns.google.com is the header, then the question: the encoded name, a two-byte type and a two-byte class. The answer, authority and additional sections are empty. How many bytes long is the whole query? Answer with the total only.', null, '{"match":"number_exact","expected":32,"derivation":"The header is always 12 bytes. The name dns.google.com encodes to 16 bytes, and the type and class add 2 each. 12 + 16 + 2 + 2 is 32. The proof builds the query in a Buffer, checks that its hex is exactly the query shown on the challenge page, and takes its length. Proof script output: 32."}'::jsonb, null);
