insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1), null, 1, 'Explain how your resolver turns the name dns.google.com and the ID 22 into the bytes of a query, and why each number and flag is written the way it is.', '[{"id":"t1","concept":"dns-message-format","point":"The query is a 12-byte header with the ID, the flags and four counts, then a question holding the name as length-prefixed labels ending in a zero byte, a type and a class"},{"id":"t2","concept":"byte-order","point":"Every number is big-endian, high byte first, so the ID 22 goes out as 00 16 in hex"},{"id":"t3","concept":"bit-packing","point":"Recursion desired is a single bit, the lowest of the first flags byte, so setting only it makes the flags 01 00 in hex"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver'), 2, 'Send it and read the reply', 'Send the query over UDP, check the reply''s header, and decode its names and addresses.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2), id from concept where slug in ('udp-datagrams', 'bit-packing', 'dns-message-format', 'dns-name-compression');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2), 1, 'Send over UDP', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 1), 'think', 'explain', 'Your resolver sends the query to 8.8.8.8 on port 53 over UDP and then reads. Explain what UDP does and does not promise here, and what the resolver should check and do as a result.', null, null, '[{"id":"p1","point":"One read returns one whole datagram, so the reply arrives as a single message and needs no framing"},{"id":"p2","point":"A datagram can be lost and nothing resends it, so the resolver needs a timeout and then resends the query or tries another server"},{"id":"p3","point":"It checks that the reply''s ID matches the ID it sent, and ignores a datagram that does not match"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 1), 'build', 'build', 'Open a UDP socket, send the query to 8.8.8.8 on port 53, read one datagram and print it as hex. Check that its first two bytes are 00 16, the ID you sent, and stop with an error if no reply comes within a few seconds.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 1), 'hint', '', 'Compare it with TCP. Who resends a lost packet, and who decides where a message ends?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 1), 'example', '', 'A postcard arrives whole or not at all. If no answer comes back, you send another, and you check the reply is about the card you sent.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2), 2, 'Read the header', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 2), 'think', 'spot_bug', 'This code reads the header of the page''s sample reply, whose first four bytes are 00 16 80 80 in hex. It reports the wrong ID and says the message is not a response. Find the problems.', 'id = reply[0] + reply[1] * 256
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 2), 'build', 'build', 'Parse the 12-byte header of the reply and print the ID, whether QR marks it as a response, and the four counts. The sample reply on the page should give the ID 22, 1 question, 2 answers, 0 authority records and 0 additional records.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 2), 'hint', '', 'Write the first flags byte out as eight bits. Which of them is QR, and which is RD?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 2), 'example', '', 'In the number 47 the 4 is worth ten times the 7 because it comes first. DNS writes its two-byte numbers the same way, the first byte worth 256 times the second.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2), 3, 'Follow a pointer', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 3), 'think', 'predict', 'While reading a name, your parser meets the byte 192 followed by the byte 28, which are c0 and 1c in hex. The top two bits of 192 are both set. At which offset in the message does the rest of the name start? Answer with one decimal number.', null, '{"match":"number_exact","expected":28,"derivation":"Two set top bits mark a compression pointer, and the other 14 bits of the two bytes give the offset. 192 is 11000000 in binary, so once the two flag bits are removed the first byte adds nothing, and the offset is the second byte, 28. Taking all 16 bits as a number would give the wrong 49180. Proof script output: 28."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 3), 'build', 'build', 'Decode names in the reply, joining labels with dots, and follow a pointer whenever a length byte has its top two bits set. The page''s reply uses c0 0c, a pointer to offset 12, where the name in the question starts.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 3), 'hint', '', 'Of the 16 bits in the two bytes, two only say this is a pointer. What do the other 14 say?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 3), 'example', '', 'A footnote mark tells you the text continues somewhere else, and the number beside it says exactly where.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2), 4, 'Read the answers', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 4), 'think', 'trace', 'In the sample reply, the first answer record begins with the two bytes c0 0c, a pointer to the name dns.google.com at offset 12. How many bytes does the name take up inside the answer record itself, before the type field starts? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The pointer stands in for the whole name, so the record spends only the 2 pointer bytes on it. The 16 bytes of dns.google.com live at offset 12 and are not repeated, and reading the record continues right after the pointer. The proof decodes the page''s sample reply and measures where the type field starts. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 4), 'build', 'build', 'After each answer''s name, read the type, class, TTL, data length and data, and print an A record''s data as four numbers joined by dots. The sample reply should give two answers for dns.google.com, each of type 1 and class 1 with a TTL above zero, with the addresses 8.8.8.8 and 8.8.4.4.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 4), 'hint', '', 'The pointer replaces the name in the record. How many bytes did the record itself spend on it?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2) and s.position = 4), 'example', '', 'A note saying see page 12 takes a few words on this page, however long the text on page 12 is.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 2), null, 1, 'Explain how your resolver sends a query over UDP and turns the reply that comes back into names and addresses.', '[{"id":"t1","concept":"udp-datagrams","point":"It sends one datagram and reads one back whole, with a timeout and a retry because UDP may lose it, and it checks that the ID matches"},{"id":"t2","concept":"bit-packing","point":"It checks the QR bit, the top bit of the flags, to confirm that the message is a response"},{"id":"t3","concept":"dns-message-format","point":"It reads the counts in the header, passes over the question, then reads each answer''s name, type, class, TTL, data length and data, where an A record''s data is a 4-byte address"},{"id":"t4","concept":"dns-name-compression","point":"A length byte with its top two bits set starts a two-byte pointer whose other 14 bits give the offset of the rest of the name, and reading carries on right after the pointer"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver'), 3, 'Resolve from the root', 'Ask a root server directly and follow referrals down to the server that knows the address.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3), id from concept where slug in ('iterative-resolution', 'bit-packing', 'dns-message-format');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3), 1, 'Ask a root server', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 1), 'think', 'predict', 'Your resolver now sends its query straight to a root server, such as 198.41.0.4, and will follow the referrals itself instead of asking one server to do the whole lookup. What should the recursion desired bit be in this query? Answer with 0 or 1.', null, '{"match":"number_exact","expected":0,"derivation":"Recursion desired asks the server to do the whole lookup for you. Here the resolver does that work itself, and root and authoritative servers do not offer recursion anyway, so the bit is cleared and the flags are 00 00, as the page asks. The proof builds the header for iterative mode in a Buffer and reads the bit back. Proof script output: 0."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 1), 'build', 'build', 'Set the flags to zero and send the query for dns.google.com to the root server 198.41.0.4. Print the reply''s counts and sections: it should hold no answers, NS records for the com servers in the authority section, and usually their addresses in the additional section.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 1), 'hint', '', 'Who is doing the work of following the chain now, your resolver or the server you ask?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 1), 'example', '', 'If you ask a librarian to find a book for you, you say so. If you only want to know which floor to try next, you do not ask them to fetch it.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3), 2, 'Follow the referrals', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 2), 'think', 'trace', 'Your resolver looks up www.example.org with no cache, starting every lookup at the root. The root refers it to the org servers and gives their addresses. An org server refers it to the server ns1.example.net but gives no address for it. Looking up ns1.example.net works the usual way: the root refers to net with addresses, a net server refers to example.net with addresses, and that server returns the address. Finally ns1.example.net returns the address of www.example.org. How many queries does the resolver send in all? Answer with one number.', null, '{"match":"number_exact","expected":6,"derivation":"The main lookup asks the root (1) and an org server (2). The referral names ns1.example.net without an address, so a side lookup starts at the root: the root (3), a net server (4) and the example.net server (5), which returns the address of ns1.example.net. Asking that server (6) gives the address of www.example.org. The proof walks a small model of these servers and counts the queries. Proof script output: 6."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 2), 'build', 'build', 'Loop: send the query to the current server, and if the answer section holds an A record, print the address and stop. Otherwise take a name server from the authority section, find its address in the additional section, and ask it next. Print each server you query. For dns.google.com you should see 198.41.0.4, then a com server such as 192.12.94.30, then a google.com server such as 216.239.34.10, and finally the address 8.8.8.8.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 2), 'hint', '', 'When a referral gives a server''s name but not its address, what must happen before you can ask it?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 2), 'example', '', 'Told to ask Sam at the post office, you first have to find out where the post office is before you can ask Sam anything.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3), 3, 'Handle every kind of referral', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 3), 'think', 'spot_bug', 'This loop resolves some names but fails on others. Find the problems and say how to fix them.', 'server = "198.41.0.4"
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 3), 'build', 'build', 'Handle a referral whose name server has no address in the additional section by resolving that server''s name from the root first, then carry on. Stop with an error after a fixed number of queries, or when a reply reports that the name does not exist.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 3), 'hint', '', 'Look at what kind of value the authority section holds, and ask whether the loop can ever give up.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 3), 'example', '', 'A forwarding note that says ask the town hall is no use until you look up the town hall''s address, and someone who follows notes forever with no limit may walk in circles.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3), null, 1, 'Explain how your resolver finds the address of any name starting from a root server, and how it reads each reply to decide what to do next.', '[{"id":"t1","concept":"iterative-resolution","point":"It asks a root server, which refers it to the top-level domain''s servers, which refer it to the domain''s authoritative servers, which return the address"},{"id":"t2","concept":"bit-packing","point":"It clears the recursion desired bit, because it follows the referrals itself and these servers do not resolve for it"},{"id":"t3","concept":"dns-message-format","point":"An A record in the answer section ends the search, while a referral puts NS records in the authority section and, when given, their addresses in the additional section"},{"id":"t4","concept":"iterative-resolution","point":"When a referral names a server without its address, it resolves that server''s name first and then carries on"}]'::jsonb);
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-duplicate-files', 'Build your own duplicate file finder', 'https://codingchallenges.fyi/challenges/challenge-duplicate-files') on conflict (source, slug) do nothing;
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files'), 1, 'Walk the tree and group by size', 'List every file under a folder, then keep only files that share a size with another file.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1), id from concept where slug in ('recursive-file-walk', 'candidate-filtering', 'time-space-complexity');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1), 1, 'List every file', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 1), 'think', 'predict', 'A folder holds three files and two subfolders. The subfolder photos holds two files, and the subfolder empty holds nothing. How many file paths does ccdupe list when it is run on the folder? Answer with one number.', null, '{"match":"number_exact","expected":5,"derivation":"The three files at the top count, and so do the two inside photos. The two subfolders are folders, not files, and empty adds nothing, so 3 + 2 = 5. Running find with the file type filter and wc -l on the same tree in Git Bash also gives 5. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 1), 'build', 'build', 'Make test data: twenty files of 100 random bytes each, one of them copied to a twenty-first file, and a few subfolders at different depths holding further copies. Then make ccdupe take a folder as its argument and print the path of every file inside it, at any depth. A missing argument or a folder that does not exist should give a message on the error stream and a non-zero exit status.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 1), 'hint', '', 'Count only the things that hold bytes, and look inside every folder, including the ones that turn out to be empty.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 1), 'example', '', 'Counting the books in a bookcase means counting the books on every shelf, not the shelves themselves, and an empty shelf adds nothing.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1), 2, 'Group by size', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 2), 'think', 'predict', 'The top folder holds a.bin of 100 bytes and b.bin of 200 bytes. Its subfolder holds c.bin of 100 bytes and d.bin of 300 bytes. A deeper subfolder holds e.bin of 300 bytes, f.bin of 400 bytes and g.bin of 100 bytes. After grouping by size, how many files still need hashing? Answer with one number.', null, '{"match":"number_exact","expected":5,"derivation":"Size groups are built across the whole tree, not per folder. The 100-byte group holds a, c and g, and the 300-byte group holds d and e. b and f are the only files of their sizes, so they cannot have a duplicate. That leaves 3 + 2 = 5 files. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 2), 'build', 'build', 'Record the path and size of every file, and print one line starting Potential duplicates for each group of two or more files of the same size, in place of the plain listing. On the test data every file is 100 bytes, so they all show up as potential duplicates, which is why the next milestone is needed.');
