insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 2), 'example', '', 'Matching socks from a laundry basket, you would first sort them by colour. A colour with only one sock cannot make a pair, so you never look at that sock again.', 'generated');
