insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1), null, 1, 'Explain how your tool finds every file under a folder, why it groups by size before reading any content, and what that saves as the folder grows from a hundred files to a million.', '[{"id":"t1","concept":"recursive-file-walk","point":"It lists each folder, keeps the files and descends into each subfolder the same way, skipping symbolic links and reporting folders it cannot read"},{"id":"t2","concept":"candidate-filtering","point":"Files of different sizes cannot be duplicates, so only files that share a size with another file go on to be hashed, and the size is known without reading the file"},{"id":"t3","concept":"time-space-complexity","point":"Comparing every file with every other grows with the square of the number of files, while sorting them into size groups is one pass, so the cost stays manageable for a million files"}]'::jsonb);
