insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 2), 1, 'Group by digest', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 2) and s.position = 1), 'think', 'predict', 'Six candidate files, A to F, are all 100 bytes. A, C and F hold exactly the same bytes, B and E hold the same bytes as each other, and D is unlike any other. The tool prints one Probable duplicates line for each group of two or more files with the same MD5 digest. How many lines does it print? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"Equal content always gives an equal digest, so A, C and F share one digest and B and E share another. D has a digest of its own and forms no group. That makes 2 groups, so 2 lines. md5sum in Git Bash on the same six files shows the same two repeated digests. Proof script output: 2."}'::jsonb, null);
