insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 2), 3, 'Confirm byte by byte', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 2) and s.position = 3), 'think', 'explain', 'Two files of the same size have the same MD5 digest. Why does your tool still compare them byte by byte before it calls them duplicates, and why is that step affordable?', null, null, '[{"id":"p1","point":"Different files can share an MD5 digest, and such pairs can be made on purpose, so a matching digest is strong evidence but not proof"},{"id":"p2","point":"The tool may offer to delete one of them, so a false match would lose data, which makes the certainty worth paying for"},{"id":"p3","point":"Only files that already match on size and digest reach this check, and the comparison reads both files in chunks and stops at the first byte that differs"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 2) and s.position = 3), 'build', 'build', 'Compare every pair in a digest group byte by byte, reading both files in chunks, and print one line starting Duplicates for each set that matches completely.');
