insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 2) and s.position = 3), 'example', '', 'Two people with the same first name and birthday are probably not the same person, so a bank still checks their full ID before merging their accounts.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 2), null, 1, 'A folder holds a 20 GB video, a copy of it under another name, and thousands of small files. Explain how your tool finds the pair of videos without running out of memory, and at what point it is sure they match.', '[{"id":"t1","concept":"candidate-filtering","point":"Only files that share a size are hashed, and only files that share a digest are compared byte by byte, so most files are ruled out cheaply"},{"id":"t2","concept":"streaming-constant-memory","point":"Each file is read in fixed-size chunks that are fed to the digest or the comparison, so memory stays the same even for a 20 GB file"},{"id":"t3","concept":"content-digests","point":"Matching MD5 digests make the videos probable duplicates, and the byte-by-byte comparison is what makes them certain, because MD5 collisions can be made"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files'), 3, 'Options, caching and deleting', 'Add a minimum size option, cache digests between runs, and delete duplicates only on a clear answer.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3), id from concept where slug in ('cli-subcommands', 'cache-invalidation', 'safe-destructive-actions');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3), 1, 'A minimum size', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3) and s.position = 1), 'think', 'predict', 'A folder holds files of 0, 0, 500, 999, 1000, 1000 and 4096 bytes, and you run ccdupe with --minsize=1000, which skips any file smaller than 1000 bytes. How many files are left for the size grouping? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"Smaller than 1000 means the two empty files, the 500-byte file and the 999-byte file are skipped. A file of exactly 1000 bytes is not smaller than 1000, so both of those stay, along with the 4096-byte file: 3 files. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3) and s.position = 1), 'build', 'build', 'Accept an optional --minsize option, for example --minsize=1000, and skip every file below that many bytes. Reject a value that is not a whole number with a message on the error stream and a non-zero exit status.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3) and s.position = 1), 'hint', '', 'Decide for each file on its own whether it is smaller than the limit, and look closely at a file that is exactly at the limit.', 'generated');
