insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3), 2, 'Cache the digests', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3) and s.position = 2), 'think', 'trace', 'Your tool stores each file''s MD5 in a cache keyed by its path, size and modification time, and hashes a file only when the cache has no entry for that key. The first run hashes five candidate files. Before the second run you edit one file without changing its size, touch a second so that only its modification time changes, and rename a third. The other two are untouched and all five are still candidates. How many files does the second run hash? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"The edited file has a new modification time, so its key changed. The touched file holds the same bytes, but its modification time changed, so its key changed too. The renamed file has a new path, so its key is new. The two untouched files hit the cache. That is 3 files hashed again. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3) and s.position = 2), 'build', 'build', 'Cache each file''s digest between runs, in memory or in a small local database such as SQLite, together with the size and modification time it was computed for, and hash the file again when either has changed.');
