insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3) and s.position = 2), 'example', '', 'A cloakroom ticket is checked against the number, the colour and the coat. If any of them is different, the attendant does not hand anything over, even if it might be the same coat.', 'generated');
