insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3), null, 1, 'Explain how a run of ccdupe with --minsize goes from the command line to a deleted file, and how it avoids both repeating work from the last run and deleting the wrong thing.', '[{"id":"t1","concept":"cli-subcommands","point":"It reads the folder and the --minsize option from its arguments, skips files below that size, and rejects a bad option with a message on the error stream and a non-zero exit status"},{"id":"t2","concept":"cache-invalidation","point":"A cached digest is reused only when the file''s path, size and modification time all match what was stored, and otherwise the file is hashed again"},{"id":"t3","concept":"safe-destructive-actions","point":"It shows each duplicate set, deletes only when the answer is a valid listed number, keeps every file on any other answer, and says what it removed"}]'::jsonb);
