insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo'), 1, 'Echo one client over TCP', 'Accept a connection on port 7, echo its bytes until it closes, and learn how a byte stream really arrives.');
