insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1), 1, 'Accept a connection', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 1), 'think', 'predict', 'Your server listens on port 7 and accepts one client that connects with netcat. While that client is connected, how many sockets does the server have open, counting the listening one? Answer with the count.', null, '{"match":"number_exact","expected":2,"derivation":"The listening socket stays open to wait for more clients, and accepting the client hands back a second, new socket that is used only for talking to that client. That makes 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 1), 'build', 'build', 'Start a server, ccecho, that binds to every local address on port 7, accepts one TCP connection, logs a line such as Accepted connection from: 127.0.0.1:63798 with the client''s address and port, and then exits. Test it by running nc localhost 7 in a second terminal. On Linux and macOS a port below 1024 needs extra privileges, so you may need to run it as an administrator.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 1), 'hint', '', 'Does the listening socket go away when a client arrives, and what does accepting give you back?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 1), 'example', '', 'A receptionist who answers the front desk phone puts each caller through to an extension and is free to answer the next call.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1), 2, 'Echo until the client leaves', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 2), 'think', 'trace', 'The server loop reads up to 1024 bytes, writes back exactly what it read, and stops when a read returns zero bytes. A client sends hello and a newline, later sends world and a newline, then closes the connection. Each line arrives in its own read. How many reads does the loop make in total? Answer with the count.', null, '{"match":"number_exact","expected":3,"derivation":"The first read returns the 6 bytes of hello and its newline, and the second the 6 bytes of world and its newline. After the client closes, the next read returns zero bytes, which means the connection is over, and the loop stops. That is 3 reads. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 2), 'build', 'build', 'After accepting, read from the client and write the same bytes back until a read reports that the client has closed, then log Client disconnected. In netcat, a line you type should appear twice, once as typed and once as the echo, and closing netcat should end the session.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 2), 'hint', '', 'Count the reads that bring data, then ask how the loop learns that there is nothing more to come.', 'generated');
