insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1), 3, 'A line that arrives in pieces', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 3), 'think', 'predict', 'A client sends hello world and a newline, 12 bytes, in one write. The network delivers it as three packets of 5, 5 and 2 bytes. Each read returns everything that has arrived and not been read yet, and the buffer holds 1024 bytes. Depending on when the server happens to read, what is the fewest and what is the most reads that return data for this line?', null, '{"match":"numbers_all","expected":[1,3],"derivation":"If all three packets have arrived before the server reads, one read returns all 12 bytes. If the server reads just after each packet lands, each read returns one packet, so 3. Every case in between gives 2. The proof lists every way the packets can be gathered into reads. Proof script output: [1, 3]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 3), 'build', 'build', 'Test the echo with input that may be split: paste a long block of text into netcat, and pipe a file through netcat and compare what comes back with the file. The bytes must come back complete and in order, however many reads it takes.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 3), 'hint', '', 'The number of reads depends on timing, not on how the client wrote. Picture the server reading early, then late.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 3), 'example', '', 'A letter sent in three envelopes might all be in the letterbox when you look, or you might check after each one is delivered.', 'generated');
