insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 4), 'build', 'build', 'Keep your echo server writing back the raw bytes it reads, which needs no framing. Make sure every byte is written: a write can also send less than it was given, so loop until all of it has gone, or use a call your language offers that does this for you.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 4), 'hint', '', 'Look back at the line that arrived in pieces. What would this loop write for each of those reads?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1) and s.position = 4), 'example', '', 'Reading a dictated message aloud each time the speaker pauses for breath splits sentences in odd places. Waiting for each full stop gives whole sentences.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 1), null, 1, 'Explain what your server does from the moment a client connects until it leaves, and why code that needs whole lines must never assume that one read is one message.', '[{"id":"t1","concept":"tcp-sockets","point":"The server listens on port 7, and accepting a client gives that client its own socket while the listening socket keeps waiting"},{"id":"t2","concept":"stream-read-contract","point":"A read returns whatever has arrived, which can be part of what was sent, and a read of zero bytes means the client closed, which ends the loop"},{"id":"t3","concept":"message-framing","point":"TCP keeps no message boundaries, so code that needs whole lines buffers bytes until a newline, while a plain echo can just write back what it read"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo'), 2, 'Many clients, UDP and a clean stop', 'Serve clients side by side, add a UDP mode behind a flag, and stop without losing echoes.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2), id from concept where slug in ('concurrent-connections', 'udp-datagrams', 'cli-subcommands', 'graceful-shutdown');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2), 1, 'Serve clients side by side', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 1), 'think', 'trace', 'A server handles one connection at a time: it echoes for a client until that client leaves, then accepts the next. Client A connects at second 0, sends nothing and leaves at second 30. Client B connects at second 5 and sends a line straight away. At which second does B get its echo back? Answer with one number.', null, '{"match":"number_exact","expected":30,"derivation":"The server is busy with A from second 0 until A leaves at second 30. B''s connection and its line wait in the queue all that time, even though A sends nothing. At second 30 the server accepts B and echoes the line at once, so B gets it at second 30. Proof script output: 30."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 1), 'build', 'build', 'Keep the server running after each client and accept connections in a loop, handing each one to its own thread or async task. With the server in one terminal and nc localhost 7 in two others, both clients should be echoed at once, and the server should log one Accepted connection from line per client.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 1), 'hint', '', 'Follow the server''s attention through time. Who is it waiting on between second 5 and second 30?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 1), 'example', '', 'A shop with one till and a customer who stands there chatting makes everyone behind them wait, however quick their own purchase is.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2), 2, 'Echo over UDP', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 2), 'think', 'trace', 'In UDP mode a client sends five datagrams, numbered 1 to 5, one line each. Datagram 3 is lost on the way to the server, and the echo of datagram 5 is lost on the way back. Nothing else is lost. How many echoes reach the client? Answer with the count.', null, '{"match":"number_exact","expected":3,"derivation":"The server receives 1, 2, 4 and 5, since 3 never arrives, and echoes each of them. The echo of 5 is lost, so the client gets the echoes of 1, 2 and 4. Nothing resends a lost datagram, so that is 3. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 2), 'build', 'build', 'Add a flag, ccecho -udp, that runs the server over UDP on port 7 instead of TCP and logs UDP Echo server listening on :7. Test it with nc -u localhost 7, whose flag may differ in your version of netcat: a line you send should come back. Reject an option you do not know with a message on the error stream and a non-zero exit status.');
