insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 4), 'build', 'build', 'On Ctrl+C or a stop signal, stop accepting new connections, let every client finish the echo in progress, close all open connections, and exit, with a time limit after which the rest are closed anyway. Check it with two connected netcat clients.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2) and s.position = 4), 'hint', '', 'Put the shutdown in order. What should stop first, what should be allowed to finish, and what if it never finishes?', 'generated');
