insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-echo') and m.position = 2), null, 1, 'Explain how your server serves several clients at once, what changes when it is started in UDP mode, and how it stops without losing anyone''s echo.', '[{"id":"t1","concept":"concurrent-connections","point":"Each accepted connection gets its own thread or task, so a slow or silent client does not hold up the others"},{"id":"t2","concept":"udp-datagrams","point":"In UDP mode each read is one whole datagram with its sender''s address, the reply goes to that address, and a lost datagram is never resent"},{"id":"t3","concept":"cli-subcommands","point":"A command-line flag picks UDP instead of TCP, and an unknown option is rejected with a message on the error stream and a non-zero exit status"},{"id":"t4","concept":"graceful-shutdown","point":"Shutdown stops accepting first, lets echoes in flight finish within a time limit, then closes every connection and exits"}]'::jsonb);
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-grep', 'Build your own grep', 'https://codingchallenges.fyi/challenges/challenge-grep') on conflict (source, slug) do nothing;
