insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1), id from concept where slug in ('regex-matching', 'line-endings', 'cli-subcommands');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1), 1, 'Find a letter', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 1), 'think', 'predict', 'A file holds three lines: cat, cow and dog. How many lines does grep print when the pattern is the letter o?', null, '{"match":"number_exact","expected":2,"derivation":"A line is printed when the pattern appears anywhere in it. cow and dog each contain an o, cat does not, so 2 lines are printed. GNU grep piped into wc -l gives 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 1), 'build', 'build', 'Make your grep take a pattern and a file name and print every line that contains the pattern. With the pattern J, rockbands.txt should give Judas Priest, Bon Jovi and Junkyard. On the easy route, hand the pattern to your language''s regex library. On the hard route, start an engine that matches plain letters.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 1), 'hint', '', 'Look at each line on its own and ask whether the letter is anywhere in it.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 1), 'example', '', 'Searching a guest list for the letter z picks out every name with a z in it, wherever the z sits.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1), 2, 'The empty pattern', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 2), 'think', 'predict', 'A file holds the letter a, a newline, and the letter b, with no newline after the b, so wc -l on the file reports 1. You run grep with an empty pattern on the file and pipe its output into wc -l. What does wc report?', null, '{"match":"number_exact","expected":2,"derivation":"An empty pattern fits at the start of any line, so both a and b are printed. grep writes a newline after every line it prints, including the last one that had none in the file, so the output holds 2 newlines and wc -l reports 2. GNU grep piped into wc -l gives 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 2), 'build', 'build', 'Make an empty pattern match every line. Running grep with an empty pattern on test.txt and comparing the output with test.txt using diff should print nothing at all. Then try a file with no final newline on your grep and the real one, and make them agree.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 2), 'hint', '', 'Does a pattern with nothing in it fit inside the line b? Then look at what grep writes after each line it prints.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 2), 'example', '', 'A sieve with no mesh lets everything through. Asking whether nothing appears in a word is always answered yes.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1), 3, 'Exit status', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 3), 'think', 'predict', 'rockbands.txt has no line containing zebra, and missing.txt does not exist. What exit status does grep return for a search for zebra in rockbands.txt, and what for the same search in missing.txt?', null, '{"match":"numbers_all","expected":[1,2],"derivation":"grep returns 0 when it printed at least one line, 1 when it read everything and found no match, and 2 when something went wrong, such as a file that cannot be opened. The first search finds nothing, so 1. The second cannot open the file, so 2, with a message on the error stream. GNU grep returns 1 and 2. Proof script output: [1, 2]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 3), 'build', 'build', 'Return exit status 0 when a line matched, 1 when none did, and 2 on an error, with the error message on the error stream. Check each case by printing the exit status straight after running your grep, for example after the search for J in rockbands.txt, which should report 0.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 3), 'hint', '', 'There are three outcomes, not two. Which of them is each search?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 3), 'example', '', 'A librarian asked for a book can say here it is, we do not have it, or the catalogue is broken. Not having the book is not the same as being unable to look.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1), null, 1, 'Explain how your grep decides which lines to print for a plain pattern and for an empty one, how it treats the ends of lines, and how a script calling it can tell what happened.', '[{"id":"t1","concept":"regex-matching","point":"A line is printed when the pattern fits starting at some position in it, so a plain letter can match anywhere and an empty pattern matches every line"},{"id":"t2","concept":"line-endings","point":"It splits the input into lines at newlines, matches each line without its newline, and writes a newline after every printed line, even a last line that had none"},{"id":"t3","concept":"cli-subcommands","point":"Exit status 0 means a line matched, 1 means none did, and 2 means an error such as a missing file, reported on the error stream"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep'), 2, 'Files, folders and pipes', 'Search a folder tree with file name prefixes, invert the match, and read from a pipe.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2), id from concept where slug in ('recursive-file-walk', 'stdin-vs-file', 'unix-pipelines');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2), 1, 'Search a folder tree', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 1), 'think', 'predict', 'Your current folder holds a folder called sub. sub holds b.txt and a folder called deeper, and deeper holds c.txt. Each file has one line containing x. You run grep -r x sub. Using forward slashes, what text comes before the colon on the line printed from c.txt?', null, '{"match":"text_ci","expected":"sub/deeper/c.txt","derivation":"grep -r starts at the folder it was given and joins each name it walks through onto that path, so the file is reached as sub, then deeper, then c.txt, and printed as sub/deeper/c.txt followed by a colon and the line. GNU grep prints sub/deeper/c.txt:x. Proof script output: sub/deeper/c.txt."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 1), 'build', 'build', 'Add -r. List a folder''s entries, search each file, and walk into each subfolder the same way, printing the path, a colon and the line for each match. From the test folder, grep -r Nirvana with a star for the file names should print rockbands.txt:Nirvana and five lines from test-subdir/BFS1985.txt, each starting with that path. Decide what to do with a folder you cannot read and with a link that leads back up the tree.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 1), 'hint', '', 'Follow the path grep builds as it walks down, starting from the name you gave it.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 1), 'example', '', 'Directions to a room in a building start from the entrance you named: east wing, second floor, room 12. The room number alone does not say where it is.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2), 2, 'Invert the match', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 2), 'think', 'predict', 'A file holds five lines: apple, berry, an empty line, banana and cherry. How many lines does grep -v with the pattern a print?', null, '{"match":"number_exact","expected":3,"derivation":"-v prints the lines where the pattern does not fit. apple and banana contain an a, so they are dropped. berry, cherry and the empty line contain no a, and the empty line is still a line, so 3 are printed. GNU grep piped into wc -l gives 3. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 2), 'build', 'build', 'Add -v to print the lines that do not match. Piping grep -r Nirvana with a star into grep -v Madonna should leave only rockbands.txt:Nirvana, because every matching line from BFS1985.txt also mentions Madonna. Make sure the exit status follows the lines printed, not the lines matched.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 2), 'hint', '', 'Go through the lines one by one, and do not skip the one that looks like nothing.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 2), 'example', '', 'A bouncer told to keep out everyone in red lets in the person in blue, the person in green, and the person with no coat at all.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2), 3, 'Read from a pipe', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 3), 'think', 'spot_bug', 'This grep works when given one file, but goes wrong after a pipe and prints oddly for a single file. Find the two problems and say how to fix them.', 'pattern, names = parse_options(args)
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 3), 'build', 'build', 'When no file name is given, read standard input with the same line loop, so the second grep in the Nirvana and Madonna pipeline works. Print the file name prefix only when more than one file is searched or -r is used.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 3), 'hint', '', 'In a pipeline, what does the second grep receive as its list of file names?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2) and s.position = 3), 'example', '', 'A translator who only works from printed letters is no help on a phone call, even though the words are the same.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 2), null, 1, 'In grep -r Nirvana with a star, piped into grep -v Madonna, explain how the first grep finds its files, what each grep reads, and what the second one sees.', '[{"id":"t1","concept":"recursive-file-walk","point":"The first grep lists each folder''s entries, searches the files and walks into each subfolder the same way, putting the path before each printed line"},{"id":"t2","concept":"stdin-vs-file","point":"The second grep is given no file names, so it reads standard input with the same line loop it uses for files"},{"id":"t3","concept":"unix-pipelines","point":"The second grep only sees the first one''s output lines, with their path prefix, and drops every line that contains Madonna"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep'), 3, 'Classes, anchors and case', 'Match digit and word classes, anchor to the start or end of a line, ignore case, and compare against a reference.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3), id from concept where slug in ('regex-matching', 'case-folding', 'differential-testing');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3), 1, 'Digit and word classes', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 1), 'think', 'predict', 'A file holds five lines: a plus sign, the word ok, two dashes, a single underscore, and a question mark. How many lines does grep print for the word-character class, written as a backslash and a w?', null, '{"match":"number_exact","expected":2,"derivation":"The word class matches one letter, digit or underscore. ok is made of letters, and the underscore line is itself a word character, so both are printed. The plus sign, the dashes and the question mark are not word characters, so 2 lines. GNU grep piped into wc -l gives 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 1), 'build', 'build', 'Support the digit class, a backslash and a d, and the word class, a backslash and a w. On BFS1985.txt the digit class should print five lines, each with a digit in it, and on symbols.txt the word class should print the lines pound and dollar. The grep in Git Bash reads a backslash d as a plain d, so compare with its Perl-style option instead. On the hard route, a class is a test on one character against a set.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 1), 'hint', '', 'Check exactly which characters the word class includes. It is more than letters.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 1), 'example', '', 'A form that says letters only may still quietly accept one or two other symbols. Read the full list for the word class rather than guessing from its name.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3), 2, 'Start and end anchors', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 2), 'think', 'predict', 'A file holds four lines: Banana, nachos, Ana and banana split. How many lines does grep print for the pattern n, a, then a dollar sign?', null, '{"match":"number_exact","expected":2,"derivation":"The dollar sign pins the match to the end of the line, so the line must end in na. Banana and Ana do. nachos only starts with na, and banana split has na in the middle but ends in split. That is 2 lines. GNU grep piped into wc -l gives 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 2), 'build', 'build', 'Support a caret for the start of a line and a dollar sign for the end. On rockbands.txt, caret A should print AC/DC, Aerosmith, Accept, April Wine and Autograph, and n, a, dollar should print Nirvana. On the hard route, a pattern without a caret is tried at every start position in the line, and one with a caret only at the first.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 2), 'hint', '', 'Ask how each line ends, not whether na appears in it somewhere.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 2), 'example', '', 'A list of words that end in ing keeps singing and ring, but not ingot, even though ingot contains ing.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3), 3, 'Ignore case', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 3), 'think', 'predict', 'A file holds ABBA, abba, Toto and a-ha, one per line. How many lines does grep print for the pattern A, and how many when -i is added?', null, '{"match":"numbers_all","expected":[1,3],"derivation":"Without -i, A only matches a capital A, which only ABBA has, so 1 line. With -i, A and a count as the same letter, so ABBA, abba and a-ha are printed, and Toto still has no a: 3 lines. GNU grep piped into wc -l gives 1 and 3. Proof script output: [1, 3]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 3), 'build', 'build', 'Add -i. grep A on rockbands.txt piped into wc -l should print 8, and with -i it should print 58. On the hard route, compare characters in one common case, and make sure classes and anchors behave the same with and without -i.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 3), 'hint', '', 'Without -i, a capital letter and a small one are different characters. Check each line twice.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 3), 'example', '', 'A search for the name Smith that ignores case also finds SMITH and smith, but never Smyth.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3), 4, 'Compare with the real grep', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 4), 'think', 'explain', 'On the same file, your grep prints the lines with digits for a backslash d, but the grep in Git Bash prints the lines containing the letter d. What does this tell you about checking your tool against a reference, and how would you set up a comparison you can trust?', null, null, '[{"id":"p1","point":"The tools read the pattern in different dialects, so a difference can come from the reference''s version or mode rather than a bug in your code"},{"id":"p2","point":"Fix the reference and its mode, such as grep''s Perl-style option or one regex library, so both read patterns the same way"},{"id":"p3","point":"Compare many small cases, including an empty pattern, an empty line and mixed case, checking both the printed lines and the exit status"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 4), 'build', 'build', 'Write a check that runs your grep and a pinned reference on the same patterns and files, including the empty pattern, anchors, both classes, -v and -i, and reports any difference in output or exit status. On the hard route, run your engine against your language''s regex library on many short patterns and lines.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 4), 'hint', '', 'Before deciding which tool is wrong, ask whether both understood the pattern the same way.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3) and s.position = 4), 'example', '', 'Two people reading the date 03/04 can both be right, one meaning March and the other April. Agree on the format first, then compare the answers.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 3), null, 1, 'Take the pattern caret, backslash w, backslash d, with -i. Explain how your grep decides whether a line such as X7 matches, and how you would show that your matcher agrees with grep.', '[{"id":"t1","concept":"regex-matching","point":"The caret pins the match to the start of the line, so only the first position is tried, while a pattern without it is tried at every position"},{"id":"t2","concept":"regex-matching","point":"Each class matches exactly one character from its set, so the line needs a word character followed by a digit, as X then 7"},{"id":"t3","concept":"case-folding","point":"With -i the pattern and the line are compared in one common case, so capital and small letters count as the same, while digits and symbols are unchanged"},{"id":"t4","concept":"differential-testing","point":"Run the same patterns and lines through a pinned reference, the real grep in a matching mode or a regex library, and compare outputs and exit statuses"}]'::jsonb);
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-huffman', 'Build your own compression tool', 'https://codingchallenges.fyi/challenges/challenge-huffman') on conflict (source, slug) do nothing;
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman'), 1, 'Counting and building the tree', 'Count every symbol in one pass, then build the Huffman tree by always joining the two lightest nodes.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1), id from concept where slug in ('frequency-map', 'priority-queue', 'huffman-coding');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1), 1, 'Count the symbols', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 1), 'think', 'predict', 'You count the symbols in the word mississippi. How many entries does the frequency table hold?', null, '{"match":"number_exact","expected":4,"derivation":"m occurs once, i four times, s four times and p twice. The table has one entry per different letter, however often it repeats, so it holds 4 entries even though the word has 11 letters. Also checked with fold, sort, uniq and wc in Git Bash. Proof script output: 4."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 1), 'build', 'build', 'Take a file name on the command line, report an error and exit with a non-zero status if the file is missing or cannot be read, and count how often each symbol occurs in a single pass. Counting bytes rather than characters works for any file and keeps decoding simple. On the challenge''s Les Misérables text, X should occur 333 times and t 223000 times.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 1), 'hint', '', 'One entry per different letter, however many times it repeats.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 1), 'example', '', 'A tally of votes has one line per candidate, not one line per vote.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1), 2, 'Build the tree', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 2), 'think', 'trace', 'The word abracadabra gives a 5, b 2, r 2, c 1 and d 1. You build the tree by always joining the two lightest nodes into a new node whose weight is the sum of the two. List the weights of the new nodes in the order you create them.', null, '{"match":"numbers_all","expected":[2,4,6,11],"derivation":"First c and d, 1 and 1, join into 2. That leaves 2, 2, 2 and 5, so two of the 2s join into 4; which two depends on the tie rule, but the new weight is 4 either way. That leaves 2, 4 and 5, so 2 and 4 join into 6. Last, 5 and 6 join into 11, the root, which equals the number of letters. Proof script output: [2, 4, 6, 11]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 2), 'build', 'build', 'Build the Huffman tree from your frequency table with a priority queue that always hands back the lightest node. Use the worked examples in the OpenDSA Huffman tutorial linked from the challenge as unit tests for your builder.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 2), 'hint', '', 'After each join, put the new node back with the others and look again for the two lightest.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 2), 'example', '', 'Merging piles of sand by always combining the two smallest piles: when two piles are the same size, it does not matter which you pick, because the merged pile weighs the same.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1), 3, 'Keep the queue in order', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 3), 'think', 'spot_bug', 'This tree builder gives a wrong tree on some inputs and crashes on one kind of file. Find the two problems and say how to fix them.', 'nodes = leaves sorted by weight, lightest first
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 3), 'build', 'build', 'Make your builder handle an empty file, and a file that holds one symbol many times. A single symbol still needs a code at least one bit long, or the data would take no bits at all.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 3), 'hint', '', 'After the first join, is the list still in order of weight? Then run the builder in your head on the smallest input you can think of.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 3), 'example', '', 'A ticket desk that sends every newly arrived urgent case to the back of the queue no longer serves the most urgent person first.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1), null, 1, 'Explain how you get from the input file to a Huffman tree, and why the tree ends up giving frequent symbols short codes.', '[{"id":"t1","concept":"frequency-map","point":"One pass over the input fills a map from each symbol to its count, and the map grows with the number of different symbols, not with the file size"},{"id":"t2","concept":"priority-queue","point":"A priority queue always hands back the two lightest nodes, and each joined node goes back into the queue by its weight"},{"id":"t3","concept":"huffman-coding","point":"Rare symbols are joined early, so they end up deep in the tree with long codes, while frequent symbols are joined late and stay near the root with short codes"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman'), 2, 'Codes, bits and the file format', 'Read the codes off the tree, pack them into bytes, and write a header the decoder can rely on.');
