insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2), 1, 'The code table', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 1), 'think', 'predict', 'The text aaaabbc has a 4, b 2 and c 1. After you build a Huffman tree and read off the codes, how many bits does the encoded text take, not counting the header or any padding?', null, '{"match":"number_exact","expected":10,"derivation":"c and b join first, then that node joins a, so a gets a 1-bit code and b and c get 2-bit codes. The four a''s take 4 bits, the two b''s 4 bits and the c 2 bits, which is 10. Every valid Huffman tree for these counts gives the same total, even when the tie rule changes the codes themselves. Two bits for every letter would take 14, and eight bits per letter 56. Proof script output: 10."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 1), 'build', 'build', 'Walk the tree from the root, adding 0 for a left turn and 1 for a right turn, and record each leaf''s code in a table. Check that no symbol has a longer code than a rarer one.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 1), 'hint', '', 'Find how long each letter''s code is, then add up the bits that every copy of every letter uses.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 1), 'example', '', 'In a busy kitchen, the dish ordered most often gets the shortest name on the order slip, and the rare special gets written out in full.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2), 2, 'Why prefix-free matters', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 2), 'think', 'trace', 'Someone picks the codes x 1, y 01 and z 10 by hand instead of reading them off a tree. How many different texts could the bits 101 stand for?', null, '{"match":"number_exact","expected":2,"derivation":"Reading 1 and then 01 gives xy, and reading 10 and then 1 gives zx. There are two readings because the code for x is the start of the code for z. Codes read off the leaves of a tree never have this problem, since no leaf sits on the path to another. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 2), 'build', 'build', 'Add a test that checks no code in your table is the start of another code, and run it on every table your tool builds.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 2), 'hint', '', 'Start from the left and try every code that matches the first bit or the first two bits, then see what is left.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 2), 'example', '', 'If one phone extension is 12 and another is 123, the switchboard cannot tell whether you have finished dialling after you press the 2.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2), 3, 'Pack the bits', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 3), 'think', 'predict', 'You encode aaaabbc into 10 bits and pack them into whole bytes, filling the rest of the last byte with 0 bits. The code for a is the single bit 0. The decoder is not told how many bits are real and decodes every bit it reads. How many extra a characters appear at the end of its output?', null, '{"match":"number_exact","expected":6,"derivation":"Ten bits fill the first byte and 2 bits of the second, so 6 padding bits follow. Each padding bit is a 0, and 0 on its own is the whole code for a, so the decoder turns the padding into 6 extra a characters. Storing the number of real bits or symbols in the header stops this. Proof script output: 6."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 3), 'build', 'build', 'Replace each symbol with its code, pack the bits eight to a byte, pad the last byte, and write the bytes after the header. Store the number of real bits or the number of symbols, so the decoder knows where to stop.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 3), 'hint', '', 'Work out how many bits are left unused in the last byte, and what the decoder makes of each one.', 'generated');
