insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 4), 'think', 'spot_bug', 'This header writer works on short test strings, but the decoder fails on the novel. Find the problems.', 'write_byte(out, number of entries in table)
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 4), 'build', 'build', 'Add an option for the output file name. Write a header that starts with a fixed identifier and a version, then the frequency table with each count in a fixed number of bytes in big-endian order, then the number of symbols, so the decoder can rebuild the tree and knows exactly where the data begins.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 4), 'hint', '', 'Ask how big the largest count in the novel is, and how many different values one byte can hold.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2) and s.position = 4), 'example', '', 'A car''s mileage counter with only three digits rolls back to zero after 999 miles.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 2), null, 1, 'Explain what your compressed file contains from the first byte to the last, and why a decoder can read it without guessing.', '[{"id":"t1","concept":"prefix-codes","point":"The codes come from the leaves of the tree, so none is the start of another and the bits can be decoded without separators"},{"id":"t2","concept":"bit-packing","point":"The codes are packed eight bits to a byte, the last byte is padded, and the number of real bits or symbols is stored so the padding is never decoded"},{"id":"t3","concept":"file-header-format","point":"The header starts with an identifier and version, holds the frequency table or the tree, and its layout or a stored length says where the data begins"},{"id":"t4","concept":"byte-order","point":"Numbers wider than one byte are written in one agreed order, such as big-endian, so the file reads the same on every machine"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman'), 3, 'Decoding and the round trip', 'Rebuild the codes from the header, decode the data, and prove the tool returns every file unchanged.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3), id from concept where slug in ('file-header-format', 'huffman-coding', 'round-trip-testing');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3), 1, 'Rebuild from the header', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 1), 'think', 'explain', 'Your file stores only the frequency table, and the decompressor rebuilds the tree from it. The compressor and the decompressor were written separately and break ties between equal weights in different ways. What goes wrong, and how do you prevent it?', null, null, '[{"id":"p1","point":"Equal weights can be joined in a different order, giving a different tree and different codes, so the decoder reads the bits with the wrong table and produces garbage"},{"id":"p2","point":"Both sides must use the same fixed tie rule, ideally the very same tree-building code, for example ordering equal weights by symbol"},{"id":"p3","point":"Another fix is for the header to store the tree or each symbol''s code length, so the decoder does not have to repeat the choice"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 1), 'build', 'build', 'Read the header back: check the identifier and version, read the frequency table and the number of symbols, and rebuild exactly the same tree and code table the compressor used.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 1), 'hint', '', 'With three nodes that all weigh 1, how many different pairs could be joined first?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 1), 'example', '', 'Two people sorting the same hand of cards, each with their own rule for cards of equal rank, can end up with different orders.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3), 2, 'Decode the data', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 2), 'think', 'trace', 'The codes are a 0, b 10 and c 11. Decode the bits 1001110 by walking the tree: start at the root, go left on 0 and right on 1, write down a letter at each leaf and go back to the root. Give the letters as one word with no spaces.', null, '{"match":"text_ci","expected":"bacb","derivation":"1 then 0 reaches the leaf b. The next 0 is a straight away. 1 then 1 reaches c, and the last 1 then 0 reaches b again. Every bit is used, so the word is bacb. Proof script output: bacb."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 2), 'build', 'build', 'Decode the data after the header bit by bit, walking the tree and going back to the root after each leaf. Stop after the stored number of symbols, and write the result to the output file.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 2), 'hint', '', 'Each time you reach a leaf, write its letter down and return to the root before you read the next bit.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 2), 'example', '', 'Following left and right turns at each fork of a path until you reach a house, then walking back to the start for the next address.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3), 3, 'The round trip', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 3), 'think', 'predict', 'One of your round-trip test files holds every possible byte value exactly once. How long, in bits, is the Huffman code for each byte value? Answer with a single number.', null, '{"match":"number_exact","expected":8,"derivation":"All 256 weights are equal, so the lightest nodes are always pairs of equal weight. The leaves join in pairs into 128 nodes, those into 64, and so on, halving each time until one root is left after 8 levels. Every leaf sits at depth 8, so every code is 8 bits, the same as the original, and with the header the compressed file is larger than the input. Proof script output: 8."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 3), 'build', 'build', 'Write a round-trip test that compresses and decompresses many files, including an empty file, one symbol repeated many times, every byte value once and the Les Misérables text, and compares each result with the original byte for byte. Check that the novel''s compressed file is smaller than the original.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 3), 'hint', '', 'When every weight is the same, the tree has nothing to favour. What shape does it take?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3) and s.position = 3), 'example', '', 'In a knockout tournament of equally matched teams where the number of teams is a power of two, every team plays the same number of rounds to reach the final.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 3), null, 1, 'Explain how your decompressor gets from the compressed file back to the original, and how you know the whole tool works.', '[{"id":"t1","concept":"file-header-format","point":"It checks the identifier and version, reads the table and the symbol count from the header, and knows from the header where the data begins and when to stop"},{"id":"t2","concept":"huffman-coding","point":"It rebuilds exactly the same tree with the same tie rule, then walks it bit by bit from the root and writes a symbol at each leaf"},{"id":"t3","concept":"round-trip-testing","point":"Many files go through compress and decompress, including an empty file, one repeated symbol, every byte value and the novel, and each result is compared with the original byte for byte"}]'::jsonb);
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-json-parser', 'Build your own JSON parser', 'https://codingchallenges.fyi/challenges/challenge-json-parser') on conflict (source, slug) do nothing;
