insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 1), 1, 'Tokens first', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 1) and s.position = 1), 'think', 'predict', 'Your lexer reads the text {"name": "Ada Lovelace", "city": "London"}. How many tokens does it hand to the parser?', null, '{"match":"number_exact","expected":9,"derivation":"The tokens are the opening brace, the string name, a colon, the string Ada Lovelace, a comma, the string city, a colon, the string London and the closing brace. Whitespace between tokens is skipped, and the space inside Ada Lovelace belongs to the string, so it does not split it: 9 tokens. Proof script output: 9."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 1) and s.position = 1), 'build', 'build', 'Write a lexer that turns the text into tokens, skipping spaces, tabs and newlines between them, and a parser that accepts an empty object. Your tool should report the valid file in tests/step1 as valid with exit status 0 and the invalid file there as invalid with exit status 1. Check that an empty file is rejected too.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 1) and s.position = 1), 'hint', '', 'Count the pieces the parser cares about. Each brace, colon and comma is one, and so is each quoted string as a whole.', 'generated');
