insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 1) and s.position = 2), 'think', 'trace', 'Number the tokens of {"key": "value",} from 1, starting with the opening brace. The lexer accepts every one of them. Which token number is the first one the parser rejects?', null, '{"match":"number_exact","expected":6,"derivation":"The tokens are 1 opening brace, 2 the string key, 3 colon, 4 the string value, 5 comma and 6 closing brace. A comma inside an object is allowed, but it promises another key. The parser only finds the promise broken at token 6, a closing brace where a string key must be. Proof script output: 6."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 1) and s.position = 2), 'build', 'build', 'Extend the parser to objects whose keys and values are strings, with pairs separated by commas. Run it on tests/step2: the valid files must pass and the invalid ones, such as an object with a comma just before the closing brace, must be rejected.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 1) and s.position = 2), 'hint', '', 'A comma on its own is fine. Ask what the parser expects to see right after one, and when it can tell that it is missing.', 'generated');
