insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 2) and s.position = 1), 'think', 'predict', 'Your lexer follows the JSON number rule and knows the words true, false and null. How many tokens does it produce for {"t": -1.5e3, "ok": false, "v": null}?', null, '{"match":"number_exact","expected":13,"derivation":"The minus sign, the digits, the fraction and the exponent all belong to one number token, and false and null are one token each. So each of the three pairs is a key, a colon and a value, which is 3 tokens per pair and 9 in all, plus 2 commas and the 2 braces: 13. Proof script output: 13."}'::jsonb, null);
