insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 2) and s.position = 3), 'think', 'trace', 'Your parser has one function for values, one for objects and one for arrays, and the value function calls the other two. It reads {"a": [1, [2]]}. At the deepest point, how many object and array calls are active at the same time?', null, '{"match":"number_exact","expected":3,"derivation":"The object call starts at the opening brace. Its value is an array, so an array call starts inside it. That array''s second item is another array, so a third call starts while the other two are still waiting for their closing bracket and brace. The number 2 is a plain value and opens nothing, so the deepest point is 3 calls. Proof script output: 3."}'::jsonb, null);
