insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 2), null, 1, 'Explain how your parser handles a value that can be of any kind, including objects and arrays nested inside each other.', '[{"id":"t1","concept":"lexical-analysis","point":"The lexer reads a whole number, with its minus sign, fraction and exponent, and the keywords true, false and null as single tokens, and rejects anything that does not match those rules exactly"},{"id":"t2","concept":"recursive-descent-parsing","point":"There is one function per grammar rule, and the value function looks at the next token to choose: a brace means an object, a bracket means an array, otherwise a string, number or keyword"},{"id":"t3","concept":"recursive-descent-parsing","point":"Nesting in the input becomes nesting of calls, because the object and array functions call the value function for each item, and it can call them again"},{"id":"t4","concept":"json-grammar","point":"Objects and arrays can hold any kind of value, including empty objects and arrays, so the same rules apply at every level"}]'::jsonb);
