insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 3) and s.position = 3), 'think', 'explain', 'You run the json.org checker suite. Two files in its fail set trouble you: one holds only a quoted string, with no object or array around it, and one is twenty arrays nested inside each other. Under RFC 8259 both are valid JSON. Why might a suite list them as failures, and what should your parser and test runner do?', null, null, '[{"id":"p1","point":"The suite was written for an older rule in which the outermost value had to be an object or an array, while RFC 8259 allows any value at the top"},{"id":"p2","point":"The deep file tests a nesting limit that the original checker chose, not a rule of the grammar, which sets no limit"},{"id":"p3","point":"Choose which rule your parser follows, write the choice down, and mark those files as known differences in the runner instead of hiding them"}]'::jsonb);
