insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser') and m.position = 3), null, 1, 'Explain how you would convince someone that your parser is correct, and why it is safe to run on files sent by strangers.', '[{"id":"t1","concept":"conformance-test-suite","point":"It runs a shared suite of valid and invalid inputs and checks each verdict and exit status, counting an accepted invalid file as a failure just like a rejected valid one"},{"id":"t2","concept":"lexical-analysis","point":"The lexer records the line and column of every token, so an error message can point at the exact token that broke the rules"},{"id":"t3","concept":"recursive-descent-parsing","point":"Each level of nesting is another call, so a file nested thousands of levels deep could overflow the stack, and a depth limit turns that into a clean invalid verdict with a message"}]'::jsonb);
