insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 1) and s.position = 2), 'think', 'trace', 'The bucket for one IP address holds at most 10 tokens and starts full at time 0. One token is added at each whole second after that, at 1 second, 2 seconds, 3 seconds and so on, and a token added to a full bucket is thrown away. The client sends 13 requests at time 0, then 3 requests at 2.5 seconds. How many of the 13 are accepted, and how many of the 3?', null, '{"match":"numbers_all","expected":[10,2],"derivation":"At time 0 the 10 tokens serve the first 10 requests and the other 3 are rejected, leaving the bucket empty. Tokens are added at 1 second and at 2 seconds, so at 2.5 seconds the bucket holds 2 tokens: two of the three requests are accepted and the third is rejected. Proof script output: [10, 2]."}'::jsonb, null);
