insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 1) and s.position = 3), 'build', 'build', 'Answer rejected requests to /limited with 429 Too Many Requests and leave /unlimited alone. Requests are handled at the same time, so protect each bucket while a token is taken. Then load test with Postman or a loop of curl calls, about 10 clients at once: the first burst should pass, after which roughly nine out of ten requests should be rejected.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 1) and s.position = 3), 'hint', '', 'Ask what the token count looks like after an hour of silence, and what a client program sees in the status line.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 1) and s.position = 3), 'example', '', 'A cinema that gives one free ticket per day of membership, with no upper limit, lets a member who skipped a year bring a whole crowd in one evening.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 1), null, 1, 'One client hammers /limited while another calls /unlimited. Explain how your server decides what each request gets back, and what the hammering client sees over its first burst and the seconds after it.', '[{"id":"t1","concept":"rest-api-design","point":"Requests to /unlimited are never checked, and a request to /limited that is over the limit gets 429 Too Many Requests instead of the normal reply"},{"id":"t2","concept":"token-bucket","point":"Each IP address has its own bucket of at most 10 tokens, so a burst of up to 10 passes, and after that only about one request per second is accepted"},{"id":"t3","concept":"token-bucket","point":"Tokens beyond the capacity are thrown away, so a quiet client can never save up more than one full bucket"},{"id":"t4","concept":"concurrent-connections","point":"Many requests are handled at the same time, so taking a token is protected, for example with a lock, or two requests could both take the last token"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter'), 2, 'Fixed windows and the sliding log', 'Count requests in clock-aligned windows, see the burst a boundary allows, and fix it with a log of request times.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2), id from concept where slug in ('fixed-window-counter', 'sliding-window-log', 'key-value-store');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2), 1, 'Windows aligned to the clock', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 1), 'think', 'predict', 'A fixed window limiter allows 3 requests per window of 10 seconds. Windows start at 0, 10, 20 seconds and so on, so a request at exactly 10 seconds belongs to the window that starts at 10. Rejected requests are not counted. One client sends requests at 2, 5, 8, 9, 10 and 11 seconds. How many of the six are accepted?', null, '{"match":"number_exact","expected":5,"derivation":"The requests at 2, 5 and 8 fill the window from 0 to 10, so the one at 9 is rejected. The request at exactly 10 opens the next window with a fresh count, so 10 and 11 are accepted. That is 3 plus 2, so 5 accepted. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 1), 'build', 'build', 'Replace the token bucket with a fixed window counter: each request belongs to the window that starts at its timestamp rounded down to a whole window, so with 60-second windows a request at 10:15:42 counts in the window that starts at 10:15:00. Keep one counter per client and window, and reject requests over the threshold with 429.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 1), 'hint', '', 'Sort the six times into windows first, then count inside each window on its own.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 1), 'example', '', 'A gym that allows 3 visits per calendar week turns away a fourth visit on Saturday, but the same member can come in again first thing on Monday, because the count starts over.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2), 2, 'The boundary burst', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 2), 'think', 'trace', 'A fixed window limiter allows 5 requests per 60-second window, and windows start on each whole minute, so second 60 opens a new window. A client sends 5 requests at second 58 and 5 more at second 61. How many of the 10 requests are accepted in total? Answer with the single total.', null, '{"match":"number_exact","expected":10,"derivation":"The 5 requests at second 58 fall in the window from 0 to 60, which allows exactly 5. The 5 requests at second 61 fall in the new window from 60 to 120, which starts with a count of 0. All 10 are accepted, so twice the limit passes within 3 seconds. Proof script output: 10."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 2), 'build', 'build', 'Test the fixed window with a 60-second window and a threshold of 60, using Postman or a curl loop with about 10 clients at once. Expect a run of successes just after each window starts, followed by rejections until the next window.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 2), 'hint', '', 'Decide which window each group of requests lands in, and what each window''s count was when the group arrived.', 'generated');
