insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2), 3, 'Keep a log of request times', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 3), 'think', 'trace', 'A sliding window log allows 3 requests in any 10 seconds. Before each request it removes log entries that are 10 or more seconds old, so an entry from exactly 10 seconds ago no longer counts. It accepts the request if fewer than 3 entries remain, and only accepted requests are added to the log. One client sends requests at 0, 4, 8, 10, 12 and 14 seconds. At what time is a request rejected?', null, '{"match":"number_exact","expected":12,"derivation":"0, 4 and 8 are accepted and the log holds those three. At 10 the entry from 0 is exactly 10 seconds old and is removed, leaving 4 and 8, so 10 is accepted. At 12 the log holds 4, 8 and 10, all younger than 10 seconds, so the request at 12 is rejected and not logged. At 14 the entry from 4 has expired, leaving 8 and 10, so 14 is accepted. Only the request at 12 is rejected. Proof script output: 12."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 3), 'build', 'build', 'Implement a sliding window log: keep the time of each accepted request per client, drop times older than the window, and accept a new request only if the remaining count is under the limit.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 3), 'hint', '', 'Write the log out after every request, removing old entries first and adding the new time only if it was accepted.', 'generated');
