insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2), 4, 'Test the log', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 4), 'think', 'spot_bug', 'This log is meant to accept up to limit requests in any window, and to keep only recent times in memory. Find the two problems.', 'log = logs[ip]
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 4), 'build', 'build', 'Write tests for the log before or alongside the code. Let the tests set the current time instead of reading the real clock, and cover a request exactly one window after an older one, a request that should be rejected, and a client that keeps retrying after a rejection.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 4), 'hint', '', 'Follow a client that sends one request per second for a minute against a small limit, and look at the log at the end.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2) and s.position = 4), 'example', '', 'A guest book that also records the visitors who were turned away at the door will soon say the house is always full.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 2), null, 1, 'Compare the fixed window counter with the sliding window log: what each remembers for a client, what a client can get away with near a window boundary, and what each costs when one client floods the service.', '[{"id":"t1","concept":"fixed-window-counter","point":"The fixed window starts over at boundaries aligned to the clock, so a client can send a full limit just before a boundary and another just after, up to twice the limit in a short time"},{"id":"t2","concept":"sliding-window-log","point":"The log keeps the time of each accepted request and counts only the ones inside the last window, so no stretch of one window length ever holds more than the limit"},{"id":"t3","concept":"key-value-store","point":"The fixed window keeps one small counter under a key for each client and window, while the log keeps a list of times per client that grows with the limit, which costs memory and time under a flood"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter'), 3, 'Sliding counters and many servers', 'Estimate the last window from two counters, then share the counts between servers through Redis without losing updates.');
