insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3), 1, 'Weight the previous window', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 1), 'think', 'predict', 'A sliding window counter uses 60-second windows and a limit of 10. The previous window, from 0 to 60 seconds, counted 8 requests. The current window started at 60 seconds and has counted 3 so far. A new request arrives at 75 seconds. What is the estimated count for the last 60 seconds just before this request? Answer with the single estimate.', null, '{"match":"number_exact","expected":9,"derivation":"The last 60 seconds run from 15 to 75. The current window covers 60 to 75, and the previous window still overlaps from 15 to 60, which is 45 of its 60 seconds, three quarters. The estimate is the current 3 plus three quarters of 8, which is 6, so 9. Proof script output: 9."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 1), 'build', 'build', 'Implement a sliding window counter: keep the counts of the current and the previous fixed window per client, and estimate the last window as the current count plus the previous count weighted by how much of the previous window still overlaps. Write a test that checks the estimate at a known point in a window.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 1), 'hint', '', 'Draw the last 60 seconds as a span ending now, and ask what share of the previous window falls inside it.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 1), 'example', '', 'If a train carriage holds the last third of yesterday''s passengers and all of today''s so far, you would count today''s riders in full and only a third of yesterday''s.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3), 2, 'Smoothing the boundary', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 2), 'think', 'trace', 'A sliding window counter uses 10-second windows and a limit of 10. The previous window, from 0 to 10 seconds, counted 10 requests and the current window has counted 0. At 12 seconds the client sends 5 requests at once. A request is accepted when the estimate just before it is below 10, and each accepted request adds one to the current count. How many of the 5 does it accept, and how many would a plain fixed window with the same limit accept?', null, '{"match":"numbers_all","expected":[2,5],"derivation":"At 12 seconds the previous window still overlaps 8 of its 10 seconds, so it adds 8 to the estimate. The first request sees 8 and is accepted, the second sees 9 and is accepted, and the third sees 10 and is rejected, as are the last two. The plain fixed window only counts the current window, which is empty, so it accepts all 5. Proof script output: [2, 5]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 2), 'build', 'build', 'Replay the boundary burst from the fixed window milestone against your sliding window counter and check that the client no longer gets twice the limit in a few seconds.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 2), 'hint', '', 'Work out the previous window''s weighted share once, then add the current count as it grows by one per accepted request.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 2), 'example', '', 'A teacher who limits each pupil to 10 questions an hour, and remembers most of the questions asked at the end of the last hour, will not take another 10 at the start of the new one.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3), 3, 'Two servers, one count', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 3), 'think', 'trace', 'Servers A and B share one count in a store, and the limit is 3. The count for a client is already 2. Each server handles a request from that client by reading the count, accepting if it is below 3, and then writing the count it read plus one. The steps interleave in this order: A reads, B reads, A checks and writes, B checks and writes. How many of the two requests are accepted, and what count is stored at the end?', null, '{"match":"numbers_all","expected":[2,3],"derivation":"Both servers read 2. A sees 2 is below 3, accepts, and writes 3. B still holds the 2 it read, so it also accepts and writes 3. Both requests are accepted although only one slot was left, and the store says 3 when 4 requests have really been served: one update is lost. An atomic increment would have returned 3 to one server and 4 to the other, which would reject. Proof script output: [2, 3]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 3), 'build', 'build', 'Move the counters into Redis, or another shared store, and update them with an atomic increment rather than a read followed by a write. Run two copies of your server on different ports against the same store.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 3), 'hint', '', 'Keep track of the value each server holds in its own memory, separately from the value in the store.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 3), 'example', '', 'Two cashiers both glance at a shelf label saying one item left, both sell it, and both write zero on the label, so the shop has sold an item it did not have.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3), 4, 'Keys that last', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 4), 'think', 'spot_bug', 'Two servers run this code against one Redis to enforce a limit of 60 requests per minute for each client. It stops the race between servers, but there are two problems. Find them.', 'window_start = floor(now() / 60) * 60
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 4), 'build', 'build', 'Store the counts under keys made of the client and the window start, with an expiry. Then limit clients to 60 requests per minute, send 60 requests to one server within a couple of seconds, and call the other server with curl: it should answer 429.');
