insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3) and s.position = 4), 'example', '', 'A cloakroom that hangs every guest''s coat on one hook, and never clears hooks from past evenings, soon has neither space nor any idea whose coat is whose.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 3), null, 1, 'Two servers sit behind one address and share one limit. Explain how a request is checked from the moment it arrives until it gets its reply, and why the way the count is updated matters.', '[{"id":"t1","concept":"sliding-window-counter","point":"The server estimates the last window as the current window''s count plus the previous window''s count weighted by how much of it still overlaps"},{"id":"t2","concept":"distributed-counters","point":"The counts live in a shared store, and an atomic increment does the read and the write as one step, so two servers cannot both take the last slot"},{"id":"t3","concept":"key-value-store","point":"Counts are kept under keys made of the client and the window start, with an expiry so old windows are removed"}]'::jsonb);
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-redis', 'Build your own Redis server', 'https://codingchallenges.fyi/challenges/challenge-redis') on conflict (source, slug) do nothing;
