insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 1), 'think', 'predict', 'Your server sends the word hello back as a bulk string. How many bytes does that bulk string take on the wire, counting every marker, digit and line ending? Answer with the total.', null, '{"match":"number_exact","expected":11,"derivation":"A bulk string is a dollar sign, its length in digits, a carriage return and newline, the data, and another carriage return and newline. For hello that is 1 + 1 + 2 + 5 + 2 = 11 bytes. Proof script output: 11."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 1), 'build', 'build', 'Write a serialiser and a deserialiser for the five RESP types: simple string, error, integer, bulk string and array, plus the null bulk string and null array. Test them on the messages the challenge lists, such as the null bulk string, PING as an array of one bulk string, ECHO with hello world, GET with key, OK, an error message, the empty bulk string and hello world as a simple string.');
