insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1), 2, 'Lengths, not delimiters', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 2), 'think', 'predict', 'A client stores a value made of the word up, a single newline byte, and the word down. What number follows the dollar sign in the bulk string that carries this value? Answer with one number.', null, '{"match":"number_exact","expected":7,"derivation":"The length counts every byte of the data, and the newline inside the value is data like any other byte: 2 + 1 + 4 = 7. The reader takes exactly 7 bytes and then expects the closing carriage return and newline, so the newline inside never ends the string early. Proof script output: 7."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 2), 'build', 'build', 'Make the deserialiser read a bulk string by its length rather than by searching for the next line ending, and add tests for invalid input: an unknown first byte, a length that is not a number, and a message that stops before its last byte.');
