insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 2), 'example', '', 'A parcel label that says it holds 3 books tells the receiver to unpack exactly three, even if one of the books has a page that looks like a packing slip.', 'generated');
