insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 3), 'think', 'predict', 'In a shell you type redis-cli ECHO "Hello World", with the double quotes. How many elements does the array that redis-cli sends to your server hold? Answer with one number.', null, '{"match":"number_exact","expected":2,"derivation":"The shell turns the quoted text into one argument, so redis-cli has two arguments, ECHO and Hello World, and sends an array of two bulk strings. The array starts with a star and the count 2, and the second bulk string has length 11 because it holds the space. Proof script output: 2."}'::jsonb, null);
