insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 4), 'build', 'build', 'Give each connection its own input buffer, parse as many complete commands as it holds, and keep any partial command until the rest arrives. Test it by sending two commands in one write and one command split over two writes.');
