insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1) and s.position = 4), 'example', '', 'Letters pushed through a door slot can arrive in a bundle or one at a time. You open each one only when it is complete, and you never throw away the second letter in a bundle.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 1), null, 1, 'A client opens a connection to your server and sends ECHO with a value that contains a line break. Explain how the bytes travel and how your server knows where the command ends and what to send back.', '[{"id":"t1","concept":"tcp-sockets","point":"The server listens on port 6379, accepts the client''s connection as its own socket, and reads and writes a stream of bytes on it"},{"id":"t2","concept":"message-framing","point":"TCP keeps no message boundaries, so the server buffers bytes and only acts once a whole command has arrived"},{"id":"t3","concept":"resp-protocol","point":"The command is an array whose first line gives the number of items, and each bulk string gives its length before its data"},{"id":"t4","concept":"resp-protocol","point":"Because the length is known, a line break inside the value is read as data, and the reply is a bulk string with the same length"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis'), 2, 'Store keys for many clients', 'Store values with SET and GET, serve many clients at once, and measure the server with redis-benchmark.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2), id from concept where slug in ('key-value-store', 'concurrent-connections', 'benchmarking');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2), 1, 'SET and GET', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 1), 'think', 'predict', 'A client sends GET for a key that was never set. Your server replies the way Redis does over RESP2, with a bulk string that means no value at all. How many bytes long is that reply? Answer with one number.', null, '{"match":"number_exact","expected":5,"derivation":"A missing value is the null bulk string: a dollar sign, the length minus one, then a carriage return and newline. That is 1 + 2 + 2 = 5 bytes. An empty string would be different, a length of 0 followed by an empty line, which is 6 bytes. Proof script output: 5."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 1), 'build', 'build', 'Store values in a map in memory. SET Name John should reply OK and GET Name should then reply John, and GET of a missing key should make redis-cli print nil. Reply with an error when a command has the wrong number of arguments.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 1), 'hint', '', 'Nothing and an empty string are not the same reply. Which marker says there is no value at all?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 1), 'example', '', 'An empty envelope and no envelope are different answers to the question did any mail come for me.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2), 2, 'Many clients at once', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 2), 'think', 'explain', 'Your first server serves one connection until it closes and only then accepts the next. redis-benchmark opens 50 connections at once. What happens, and what are two ways to fix it?', null, null, '[{"id":"p1","point":"Only the first connection is served, and the other 49 wait, so the benchmark stalls or times out even though the server is mostly idle"},{"id":"p2","point":"One fix gives each connection its own thread, so a slow or quiet client never blocks the others"},{"id":"p3","point":"Another fix is an event loop with non-blocking sockets, which serves whichever connections have data ready on a single thread"},{"id":"p4","point":"With threads, the shared map has to be protected, for example with a lock, so two clients cannot change it at the same moment"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 2), 'build', 'build', 'Serve many clients at the same time, with a thread per client or with asynchronous input and output, and ideally try both. Run redis-benchmark with -t SET,GET and -q, which opens 50 connections, adding -n 1000 if it takes too long, and check that it finishes with no errors and no crash.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 2), 'hint', '', 'Picture the second client connecting while the first one is still connected but has gone quiet.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 2), 'example', '', 'A shop with one assistant who serves one customer from the moment they walk in until they leave keeps a queue outside, even while that customer is only browsing.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2), 3, 'Measure against the real Redis', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 3), 'think', 'explain', 'redis-benchmark reports about 40,000 requests per second for your server and about 110,000 for the real Redis. Before you change any code, how do you make the comparison fair, and where would you look first for the gap?', null, null, '[{"id":"p1","point":"Run both servers on the same machine with the same benchmark command, the same request count and the same number of connections"},{"id":"p2","point":"Run each benchmark several times and compare the spread, not a single run"},{"id":"p3","point":"Look first at the storage structure, which should find a key in constant time, and at how shared data is locked between clients"},{"id":"p4","point":"Measure again after each change and check the replies are still correct, because a faster wrong answer is a bug"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 3), 'build', 'build', 'Benchmark GET and SET on your server and on a local Redis, running redis-benchmark with the options -t set,get and -n 100000 and -q, and compare the requests per second and the p50 latency. If yours is far behind, check your data structure and how you handle concurrent access, then measure again.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 3), 'hint', '', 'Change one thing at a time, and ask what else differs between the two runs besides your code.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2) and s.position = 3), 'example', '', 'Comparing two runners is only fair on the same track, on the same day, over the same distance.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 2), null, 1, 'Fifty clients send SET and GET to your server at the same time. Explain how the server stores the values, how it serves all fifty, and how you would show it is fast enough.', '[{"id":"t1","concept":"key-value-store","point":"Values live in an in-memory map from key to value, so SET and GET are a single lookup, and a missing key gives a null reply"},{"id":"t2","concept":"concurrent-connections","point":"Each connection is served by its own thread or by an event loop, so no client waits for another to finish"},{"id":"t3","concept":"concurrent-connections","point":"The map they all share is protected, so two clients changing it at once cannot corrupt it"},{"id":"t4","concept":"benchmarking","point":"redis-benchmark is run against the server and the real Redis on the same machine with the same settings, several times, and the results are compared"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis'), 3, 'Expiry, counters, lists and saving', 'Add the expiry options to SET, the counter and list commands, and SAVE with loading on startup.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3), id from concept where slug in ('key-expiry', 'distributed-counters', 'snapshot-persistence');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3), 1, 'Expiry options on SET', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 1), 'think', 'predict', 'When the server clock reads 1,000 seconds, a client sends SET token abc PX 4000. Your server stores the absolute moment the key expires, in seconds. What moment does it store? Answer with one number.', null, '{"match":"number_exact","expected":1004,"derivation":"PX gives the time to live in milliseconds, so 4000 is 4 seconds. Storing the absolute moment means adding it to the current time: 1000 + 4 = 1004. Then any later read only compares the clock with 1004. Proof script output: 1004."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 1), 'build', 'build', 'Extend SET with EX for seconds, PX for milliseconds, EXAT for an absolute Unix time in seconds and PXAT for one in milliseconds. Turn each into the same absolute expiry moment, and write automated tests that read a key before and after it expires.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 1), 'hint', '', 'Two questions, what unit PX uses, and what you add the time to live to.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 1), 'example', '', 'A parking ticket printed at 2 pm with 90 minutes on it is checked against a printed end time of 3:30, not against a clock counting down inside the car.', 'generated');
