insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 2), 'build', 'build', 'Check the stored expiry moment whenever a key is read, and add a light background task that removes some expired keys that nobody reads, so expiry stays cheap however many keys there are.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 2), 'hint', '', 'Ask what a reader sees between the moment a key expires and the next tick of the timer.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 2), 'example', '', 'A shop checks the date on a carton of milk when a customer picks it up, rather than walking every aisle once a minute.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3), 3, 'Counters that do not lose updates', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 3), 'think', 'trace', 'A key named counter holds 5. Two clients, A and B, each want to add one, but instead of INCR each sends GET, adds one itself and sends SET. The server receives them in this order: A''s GET, B''s GET, A''s SET, B''s SET. What does counter hold afterwards? Answer with one number.', null, '{"match":"number_exact","expected":6,"derivation":"Both GETs read 5, before either SET has happened. A sets 5 + 1 = 6, then B also sets 5 + 1 = 6, so one of the two updates is lost. With INCR the server reads and writes in one step, and the result would be 7. Proof script output: 6."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 3), 'build', 'build', 'Add EXISTS and DEL, which take one or more keys and reply with how many exist or were deleted, and INCR and DECR, which change a stored integer by one as a single step on the server. INCR on a missing key starts from 0, and INCR on a value that is not an integer replies with an error.');
