insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 3), 'example', '', 'Two clerks each read a stock count of 5 from the same card, each sell one, and each write 4 on the card. Two items left the shelf, but the card only shows one.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3), 4, 'Lists and saving to disk', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 4), 'think', 'predict', 'A client runs SET a 10, then SAVE, then INCR a twice, then SET b 5. The server crashes, and on restart it loads the saved snapshot. What does GET a return now? Answer with one number.', null, '{"match":"number_exact","expected":10,"derivation":"SAVE writes the whole store as it is at that moment, when a holds 10 and b does not exist. The two INCRs and the SET of b happen only in memory, so the crash loses them. Loading the snapshot gives a back as 10, and b is missing. Proof script output: 10."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 4), 'build', 'build', 'Add LPUSH and RPUSH, which add values to the head or the tail of a list and reply with its new length, and SAVE, which writes the whole store to a file. Load that file on startup, and write it to a temporary file first and rename it over the old one so a crash during SAVE leaves the last snapshot intact.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3) and s.position = 4), 'hint', '', 'List what is in memory at the moment of SAVE, and separately what happened after it.', 'generated');
