insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis') and m.position = 3), null, 1, 'Explain how your server makes a key disappear at the right moment, how INCR stays correct when many clients use it, and what survives a restart.', '[{"id":"t1","concept":"key-expiry","point":"SET turns EX, PX, EXAT or PXAT into one absolute expiry moment, and every read compares the clock with it and treats an expired key as missing"},{"id":"t2","concept":"distributed-counters","point":"INCR reads, adds and writes in one step on the server, so two clients cannot both read the same old value and lose an update"},{"id":"t3","concept":"snapshot-persistence","point":"SAVE writes the whole store to a file that is loaded on startup, so data survives a restart but changes made after the last SAVE are lost in a crash"},{"id":"t4","concept":"snapshot-persistence","point":"The snapshot is written to a temporary file and renamed over the old one, so a crash during SAVE never leaves a half-written snapshot"}]'::jsonb);
