insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 1) and s.position = 1), 'think', 'predict', 'A file holds four lines: pear, apple, cherry and banana. After sorting, on which line of the output does cherry appear? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"All four lines start with different letters, so the first letter decides: a for apple, b for banana, c for cherry and p for pear. The output is apple, banana, cherry, pear, and cherry is third. Proof script output: 3."}'::jsonb, null);
