insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 1), 2, 'Capitals and byte order', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 1) and s.position = 2), 'think', 'predict', 'A file holds banana, Cherry with a capital C, and apple. You sort it with the locale set to C, so letters are compared by their byte values. On which line of the output does Cherry appear? Answer with one number.', null, '{"match":"number_exact","expected":1,"derivation":"In ASCII every capital letter has a smaller byte value than every small letter: capital C is 67, small a is 97 and small b is 98. So Cherry comes before apple and banana, and is first. A dictionary-style locale such as en_US would put it last instead. Proof script output: 1."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 1) and s.position = 2), 'build', 'build', 'Compare lines by their bytes. Piping your output through uniq and taking the first five lines should give A, ACTUAL, AGREE, AGREEMENT and AND, which is what the real sort gives on the word list with the locale set to C. If your system sort prints something else, set LC_ALL to C when you run it.');
