insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 1) and s.position = 3), 'think', 'trace', 'A first version reads all of its input, splits it at every newline and sorts the pieces. The input is pear, a newline, fig and a newline. How many lines does it print, counting any blank line? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"Splitting at both newlines gives three pieces: pear, fig and an empty piece after the last newline. The empty piece sorts first, so the output is a blank line, fig and pear, 3 lines. The real sort prints only 2, because a final newline ends the last line instead of starting a new one. Proof script output: 3."}'::jsonb, null);
