insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 1), null, 1, 'Explain how your sort decides which of two lines goes first, where it reads its lines from, and how you know its output matches the real sort.', '[{"id":"t1","concept":"lexicographic-order","point":"Lines are compared from the left and the first differing byte decides, a line that is a prefix of another goes first, and in byte order capitals come before small letters, while a locale can order them differently"},{"id":"t2","concept":"stdin-vs-file","point":"With a file name it reads that file, with none it reads standard input, and the same line-splitting code serves both"},{"id":"t3","concept":"differential-testing","point":"It runs the real sort with the locale fixed to C and its own tool on the same inputs, including edge cases, and compares the outputs"}]'::jsonb);
