insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 2), 1, 'Why uniq needs sort', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 2) and s.position = 1), 'think', 'predict', 'A file holds pear, fig, pear and fig, one per line. You pipe it straight into uniq without sorting first. How many lines does uniq print? Answer with one number.', null, '{"match":"number_exact","expected":4,"derivation":"uniq only drops a line that is the same as the line just before it. No two neighbours here are equal, so nothing is dropped and all 4 lines come out. Sorting first gives fig, fig, pear, pear, and uniq then prints 2. Proof script output: 4."}'::jsonb, null);
