insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 2), 2, 'Drop duplicates with -u', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 2) and s.position = 2), 'think', 'predict', 'A file holds pear, fig, pear, Fig with a capital F, and fig. Your tool sorts it with -u, comparing bytes as with the locale set to C. How many lines does it print? Answer with one number.', null, '{"match":"number_exact","expected":3,"derivation":"In byte order Fig and fig are different lines, so they are not duplicates. Sorted, the input is Fig, fig, fig, pear, pear, and keeping one of each run gives Fig, fig and pear, 3 lines. Proof script output: 3."}'::jsonb, null);
