insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 2), null, 1, 'Explain why sort and uniq are used together, where your -u option removes duplicates, and what your choice costs compared with the other ways of doing it.', '[{"id":"t1","concept":"unix-pipelines","point":"uniq only removes duplicates that are next to each other, so sort must run first to bring equal lines together, and -u builds that same pipeline into one tool"},{"id":"t2","concept":"time-space-complexity","point":"Removing duplicates after sorting is one extra pass with almost no extra memory, while a set before sorting needs memory that grows with the number of distinct lines but leaves fewer lines to sort"},{"id":"t3","concept":"hash-functions","point":"A hash set finds repeats without sorting, because equal lines always hash the same, but different lines can collide, so the full lines must be compared"}]'::jsonb);
