insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 3) and s.position = 1), 'think', 'trace', 'A stable sort compares lines with case ignored, so A and a count as equal, and B and b count as equal. The input is b, A, a, B, in that order. In which position of the output does the capital B end up? Answer with one number.', null, '{"match":"number_exact","expected":4,"derivation":"With case ignored the a group comes first and the b group second. A stable sort keeps each group in input order: A came before a, and b came before B. The output is A, a, b, B, so B is fourth. The real sort with -f and -s prints the same. Proof script output: 4."}'::jsonb, null);
