insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 3), 2, 'Quicksort on sorted input', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 3) and s.position = 2), 'think', 'trace', 'A quicksort always picks the first line of a group as its pivot, compares every other line in the group with it once, and then sorts the smaller and larger lines the same way. It is given five lines that are already sorted: ant, bee, cat, dog and eel. How many comparisons with a pivot does it make in total? Answer with the total.', null, '{"match":"number_exact","expected":10,"derivation":"With sorted input the first line is always the smallest, so every split leaves nothing on one side. The groups shrink from 5 to 4 to 3 to 2 lines, costing 4, 3, 2 and 1 comparisons, so 10 in total. That is the square-shaped worst case; a pivot that splits evenly would do far fewer on large inputs. Proof script output: 10."}'::jsonb, null);
