insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 3) and s.position = 4), 'think', 'explain', 'Radix sort never compares two lines with each other. How can it still put lines in order, and when would it beat merge sort?', null, null, '[{"id":"p1","point":"It puts lines into buckets by one character position at a time, for example by first byte and then the next, so the order comes from the bucket order"},{"id":"p2","point":"Its work grows with the total number of characters rather than with n log n comparisons, so it wins on many short keys or keys with a small alphabet"},{"id":"p3","point":"It loses its edge on long lines that share long prefixes, and it needs extra memory for the buckets"}]'::jsonb);
