insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 3), null, 1, 'Explain how you would choose between the algorithms your tool offers for a given input, and how you make sure they all give the same answers.', '[{"id":"t1","concept":"sorting-algorithms","point":"Merge sort is stable, so equal lines keep their input order, quicksort can be unstable and degrade on unlucky pivots, heapsort is not stable, and radix sort avoids comparisons"},{"id":"t2","concept":"time-space-complexity","point":"Merge sort and heapsort take order n log n time in the worst case, quicksort can take order n squared, merge sort needs extra memory for the lists it merges while heapsort needs almost none"},{"id":"t3","concept":"unit-tests-first","point":"One set of tests, written before the algorithms, with edge cases such as empty input, equal lines, sorted input and duplicates, is run against every algorithm"}]'::jsonb);
