insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 4) and s.position = 1), 'think', 'predict', 'Your -R option picks a new random seed each run, hashes every line with it, and sorts by the hash. The input is fig, pear, fig and kiwi. However many times you run it, how many lines end up between the two fig lines? Answer with one number.', null, '{"match":"number_exact","expected":0,"derivation":"The same line always gives the same hash for a given seed, so both figs get the same key and sort next to each other. The seed moves the group around, but nothing can sit between them, so 0. The proof tries 500 seeds; the real sort -R kept the figs together in every run tried. Proof script output: 0."}'::jsonb, null);
