insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 4) and s.position = 3), 'think', 'predict', 'A file is too big for memory, so your tool sorts it in pieces and writes four sorted runs to temporary files. It then merges the four runs into the final output, always writing the smallest line it can see next. At most, how many lines does the merge need to hold in memory at once? Answer with one number.', null, '{"match":"number_exact","expected":4,"derivation":"Each run is already sorted, so the next output line is always one of the four front lines. The merge keeps the front line of each run, writes the smallest, and reads the next line from that run, so it never holds more than 4 lines, however long the runs are. Proof script output: 4."}'::jsonb, null);
