insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-sort') and m.position = 4), null, 1, 'A colleague wants to shuffle a 50 GB log file with your tool while keeping repeated lines together. Explain how the tool would cope with the size, how the shuffle works, and how you would test it.', '[{"id":"t1","concept":"external-sorting","point":"It sorts chunks that fit in memory, writes each sorted chunk to disk, then merges the chunks while holding only the front line of each"},{"id":"t2","concept":"hash-functions","point":"The shuffle sorts by a hash of each line with a seed chosen for the run, so equal lines get equal keys and stay together, and a new seed gives a new order"},{"id":"t3","concept":"differential-testing","point":"The output differs every run, so it is tested by properties against the real sort: the same lines come out, sorting them gives the real sort''s output, and equal lines are adjacent"}]'::jsonb);
