insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg') and m.position = 2), 4, 'Build into public', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg') and m.position = 2) and s.position = 4), 'think', 'trace', 'The content folder holds index.md, about.md and blog.md, and a build writes one HTML file for each into public. You delete blog.md and build again, but this build only writes files and never clears public first. How many HTML files are in public now?', null, '{"match":"number_exact","expected":3,"derivation":"The first build writes index.html, about.html and blog.html. The second build writes index.html and about.html again but never removes anything, so the stale blog.html stays: 3 files. A build that clears public first would leave 2. Proof script output: 3."}'::jsonb, null);
