insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg') and m.position = 3) and s.position = 3), 'think', 'explain', 'How can a program notice that files changed, and what does each way cost?', null, null, '[{"id":"p1","point":"Polling checks modification times on a timer, which is simple and portable but delayed and wasteful"},{"id":"p2","point":"Operating system notifications are fast and cheap, but they are platform-specific and may report bursts of events"}]'::jsonb);
