insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg') and m.position = 3) and s.position = 3), 'example', '', 'A mail app can check the server every minute, or hold a connection open and be told when mail arrives. The first is simple but late, the second is prompt but needs more machinery.', 'generated');
