insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg') and m.position = 3) and s.position = 4), 'think', 'trace', 'An editor saves a file by writing a temporary file, renaming it over the original, and updating its timestamp, so the watcher reports 3 events within 50 ms. How many rebuilds run if the tool rebuilds on every event, and how many if it waits 200 ms after the last event before rebuilding?', null, '{"match":"numbers_all","expected":[3,1],"derivation":"One rebuild per event gives 3. With a 200 ms wait after the last event, the three events inside 50 ms form one burst, so 1 rebuild. Proof script output: [3, 1]."}'::jsonb, null);
