insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg') and m.position = 3) and s.position = 4), 'example', '', 'Typing "hello" in a search box sends 5 key presses. A search that waits 300 ms after the last key runs once instead of five times.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg') and m.position = 3), null, 1, 'You edit a page while the development server is running. Explain what happens between saving the file and seeing the change in the browser, and how the server keeps requests safe.', '[{"id":"t1","concept":"file-watching","point":"A watcher notices the change, and the tool waits for the burst of events to settle before it rebuilds once"},{"id":"t2","concept":"live-reload-push","point":"The server keeps a connection open to the page and sends a message after the rebuild, and a small development-only script reloads the page"},{"id":"t3","concept":"static-file-serving","point":"The reloaded page is served by mapping the URL path to a file in public, with a Content-Type that matches the file"},{"id":"t4","concept":"untrusted-paths","point":"A request path is resolved and checked to still be inside public before any file is sent"}]'::jsonb);
