insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1), 1, 'Accept a long URL', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 1), 'think', 'predict', 'A client sends a POST to your service with a JSON body holding a field called link, set to https://www.example.com, instead of a field called url. What status code should your service answer?', null, '{"match":"number_exact","expected":400,"derivation":"The service needs a url field and the body has none, so the request itself is at fault. That is 400 Bad Request, not 404, because nothing was looked up and missed. Proof script output: 400."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 1), 'build', 'build', 'Accept a POST to the root with a JSON body holding url. Answer with a 2xx status and a JSON body holding key, long_url and short_url, for example the key Y3S9wb, the long URL https://www.example.com and the short URL http://localhost/Y3S9wb. A body without url gets 400 Bad Request and a message such as Missing field: url.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 1), 'hint', '', 'Is something missing at an address on the server, or is the request itself not what the service asked for?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 1), 'example', '', 'A clerk handed a form with your phone number in the box marked email hands the form back for you to fix. The office is not missing anything, your form is.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1), 2, 'The same URL twice', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 2), 'think', 'trace', 'The store starts empty. A client posts https://example.com, then https://example.org, then https://example.com again, and your service follows the challenge''s rule for a URL it has already shortened. How many entries does the store hold at the end?', null, '{"match":"number_exact","expected":2,"derivation":"The first two posts are new URLs, so each gets a key and an entry. The third post is a URL the store already holds, so the service answers with the existing key and adds nothing. That leaves 2 entries. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 2), 'build', 'build', 'When a long URL is posted that you have already shortened, answer with the same key, the same short URL and the same status as the first time, and leave the store unchanged.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 2), 'hint', '', 'What should happen to the store when a URL it already knows arrives a second time?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 2), 'example', '', 'A coat check that already holds your coat gives you the same ticket number again when you ask, instead of hanging up a second coat that is not there.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1), 3, 'Keep the keys', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 3), 'think', 'explain', 'While developing, you keep keys and long URLs in a map in memory. What happens to the short links people have shared when the server restarts, and what does a persistent key-value store give you?', null, null, '[{"id":"p1","point":"A map in memory is lost when the process stops, so every short link already shared stops working after a restart"},{"id":"p2","point":"A persistent store such as Redis, a database or a file keeps each key and its long URL on disk, so links survive a restart"},{"id":"p3","point":"The service only ever looks up a long URL by its key, so a simple key-value store is enough and needs no queries across entries"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 3), 'build', 'build', 'Store each key with its long URL in storage that survives a restart, such as a file, SQLite or Redis. The Redis server from another Coding Challenge works too. Restart your service and check that the entries are still there.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 3), 'hint', '', 'Where does a map in memory live, and what happens to that place when the program stops?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1) and s.position = 3), 'example', '', 'Notes written on a whiteboard are wiped at the end of the day, while notes in a notebook are there the next morning.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 1), null, 1, 'Explain what your service does with a POST, from checking the body to answering, and what happens when the same URL is posted twice or the server restarts.', '[{"id":"t1","concept":"rest-api-design","point":"A POST to the root creates a short URL. A body without url is the client''s fault and gets 400 with a message, and success gets a 2xx with the key, the long URL and the short URL"},{"id":"t2","concept":"idempotency","point":"Posting a URL that is already stored returns the existing key and leaves the store unchanged, so a client can safely send the request again"},{"id":"t3","concept":"key-value-store","point":"Each key is kept with its long URL in a persistent key-value store, so links keep working after a restart"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener'), 2, 'Make the keys', 'Turn a long URL into a short key with a hash, and handle two URLs that want the same key.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2), id from concept where slug in ('hash-functions', 'short-id-generation', 'idempotency');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2), 1, 'How many keys', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 1), 'think', 'predict', 'A toy shortener makes keys from the letters a, b and c only. How many different keys of 2 characters can it make, and how many of 3 characters? Give the first, then the second.', null, '{"match":"numbers_all","expected":[9,27],"derivation":"With 2 characters there are 3 choices for the first and 3 for the second, so 3 times 3 is 9: aa, ab, ac, ba, bb, bc, ca, cb and cc. A third character multiplies by 3 again, giving 27. Each extra character multiplies the number of keys by the size of the alphabet. Proof script output: [9, 27]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 1), 'build', 'build', 'Hash the long URL with a fixed hash function, write the result in base62, the 62 characters a to z, A to Z and 0 to 9, and keep the first few characters as the key. Choose a key length and note how many keys it allows.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 1), 'hint', '', 'Write a few keys out. For each choice of first letter, how many second letters can follow it?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 1), 'example', '', 'A bike lock with two dials, each showing 0 to 9, has ten settings for the first dial and ten for the second, so a hundred codes. Adding a third dial multiplies by ten again.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2), 2, 'When two URLs want one key', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 2), 'think', 'trace', 'Your store is empty. Both https://a.example and https://b.example hash to the key Y3S9wb. When a key is taken by a different URL, your service adds a counter to the URL and hashes again, and b.example with the counter hashes to Q7kx2T. The client posts a.example, then b.example, then a.example, then b.example. Which key does the last request get back?', null, '{"match":"text_ci","expected":"Q7kx2T","derivation":"a.example takes Y3S9wb. b.example also wants Y3S9wb, finds it holding a different URL, adds the counter and takes Q7kx2T. a.example again finds Y3S9wb holding itself and gets Y3S9wb back. b.example again finds Y3S9wb holding a.example, moves on to Q7kx2T, finds it holding b.example and returns it. Proof script output: Q7kx2T."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 2), 'build', 'build', 'Handle collisions: when the key is taken by a different long URL, add a counter or another unique value to the input and hash again, until the key is free or already holds this same URL.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 2), 'hint', '', 'At each of the four posts, ask whether the first key is free, holds this same URL, or holds a different one.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 2), 'example', '', 'If your usual hook at the gym holds someone else''s coat, you use the next hook. Next time you look at your usual hook first, see the other coat again, and find yours on the next one.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2), 3, 'Keys that stay put', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 3), 'think', 'spot_bug', 'With this code some old short links start leading to the wrong site, and after a restart the same URL gets a new key. Find the two problems and say how to fix each.', 'def shorten(long_url):
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 3), 'build', 'build', 'Make sure the same URL gets the same key after a restart. Then test collision handling by cutting the key down to one character for a moment, so that collisions happen after a handful of URLs.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 3), 'hint', '', 'Ask what put does when the key already holds something, and whether the built-in hash promises the same number tomorrow.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2) and s.position = 3), 'example', '', 'Two people given the same locker number will find each other''s things inside, and a locker number that changes every morning means nobody finds their things at all.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 2), null, 1, 'Explain how your service turns a long URL into a key, what it does when two URLs want the same key, and why the same URL always gets the same key back.', '[{"id":"t1","concept":"hash-functions","point":"A fixed hash function turns the long URL into a number, the same URL always gives the same number, and different URLs can still give the same one"},{"id":"t2","concept":"short-id-generation","point":"A few base62 characters of the hash form the key, and each extra character multiplies the number of possible keys, so short keys collide more often"},{"id":"t3","concept":"short-id-generation","point":"When the key is taken by a different URL, a counter is added and the URL hashed again until a free key or the URL''s own entry is found"},{"id":"t4","concept":"idempotency","point":"Because the hash is stable, posting the same URL again leads back to its own entry and returns the same key"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener'), 3, 'Redirect and delete', 'Send visitors of a short URL on to the long one, and let the owner delete a short URL.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), id from concept where slug in ('http-redirects', 'rest-api-design', 'key-value-store', 'idempotency');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), 1, 'Send the visitor on', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 1), 'think', 'predict', 'Someone visits a short URL whose key is in the store. Your service answers with a redirect. Which response header tells the browser where to go next?', null, '{"match":"text_ci","expected":"Location","derivation":"A redirect is a 3xx status plus a Location header holding the address to go to, and the browser follows it by itself. Proof script output: Location."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 1), 'build', 'build', 'Answer a GET for a known key with 302 Found and a Location header holding the long URL, and an unknown key with 404 Not Found and the body URL not found. curl -i should show the 302 and the location, and curl -L should follow it to the long URL''s page.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 1), 'hint', '', 'The status says go somewhere else. Which header names the somewhere?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 1), 'example', '', 'A note on a shop door saying we have moved is only useful if it also gives the new address.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), 2, 'Why 302 and not 301', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 2), 'think', 'explain', 'The challenge uses 302 Found for the redirect, not 301 Moved Permanently. What would go wrong for a URL shortener that answered with 301?', null, null, '[{"id":"p1","point":"A 301 is permanent, so the browser may remember it and send later visits straight to the long URL without asking the service"},{"id":"p2","point":"The service then cannot count visits, and a short URL that is deleted or changed keeps leading to the old address from the cache"},{"id":"p3","point":"A 302 is temporary, so the browser asks the service every time and the service stays in control of where the link goes"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 2), 'build', 'build', 'Log every redirect your service sends, visit the same short URL three times in a browser, and check that all three visits reach your service.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 2), 'hint', '', 'What is a browser allowed to remember about a permanent move, and who never hears about the next visit?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 2), 'example', '', 'When a shop puts up a sign saying it has moved for good, regular customers stop going to the old door at all, so if it moves again nobody at the old door can tell them.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), 3, 'Delete a short URL', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 3), 'think', 'trace', 'A client creates a short URL with the key Y3S9wb, then sends GET for Y3S9wb, then DELETE for Y3S9wb, which succeeds, then GET for Y3S9wb again. What status code does each of the two GETs get, in order?', null, '{"match":"numbers_all","expected":[302,404],"derivation":"The first GET finds the key and redirects with 302. The DELETE removes the key and its URL from the store. The second GET finds nothing under that key, so it gets 404. Proof script output: [302, 404]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 3), 'build', 'build', 'Accept DELETE for a key: remove the key and its long URL from the persistent store and answer 200 OK with an empty body. A GET for that key afterwards must give 404 Not Found with the body URL not found, even after a restart.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 3), 'hint', '', 'Write down what the store holds before each request, and what each GET finds there.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 3), 'example', '', 'Once a phone number has been disconnected, calling it gets you the number is not in service, not the person who used to have it.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), 4, 'Delete twice', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 4), 'think', 'explain', 'A client sends DELETE for a key, but the reply is lost on the way back, so the client sends the same DELETE again. What should the second request do to the store, and why does that matter for clients?', null, null, '[{"id":"p1","point":"The second DELETE finds nothing and changes nothing, so the store ends up the same as after one delete"},{"id":"p2","point":"Clients retry when a reply is lost, so repeating a request must not cause harm or an error the client cannot handle"},{"id":"p3","point":"Whether the second answer is 200 or 404, the client can treat the key as gone"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 4), 'build', 'build', 'Decide what a DELETE for a key that does not exist answers, since the challenge only says it should change nothing, and write a test that deletes the same key twice. If you want to go on, the challenge''s optional extras are a web page with a form that calls your API and shows the short URL with a copy button, and a pipeline that builds, tests and deploys every change to the main branch only when the tests pass.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 4), 'hint', '', 'Compare the store after one delete with the store after two. Is there any difference?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 4), 'example', '', 'Pressing a lift button that is already lit does not call a second lift, so pressing it again when unsure is safe.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), null, 1, 'Follow one short URL through its life: someone visits it, its owner deletes it, and someone visits it again. Explain what your service does and answers each time.', '[{"id":"t1","concept":"http-redirects","point":"The first visit gets 302 Found with a Location header holding the long URL, and 302 rather than 301 so the browser asks the service each time"},{"id":"t2","concept":"rest-api-design","point":"The DELETE on the key answers 200, and a GET for a deleted or unknown key answers 404 with a message"},{"id":"t3","concept":"key-value-store","point":"The delete removes the key and its URL from the persistent store, so the short URL stays gone after a restart"},{"id":"t4","concept":"idempotency","point":"Sending the same delete again leaves the store as it was, so a retried request does no harm"}]'::jsonb);
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-wc', 'Build your own wc', 'https://codingchallenges.fyi/challenges/challenge-wc') on conflict (source, slug) do nothing;
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), 1, 'How text is encoded', 'Code points, UTF-8''s variable length and why it is designed that way, UTF-16 code units and surrogate pairs, and what a user sees as one character.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1), id from concept where slug in ('text-encoding-utf8', 'utf16-code-units', 'grapheme-clusters');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1), 1, 'Bytes need an agreement', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 1), 'think', 'explain', 'A file is only bytes. What has to be agreed before those bytes can be shown as text, and what does a reader see when the program that wrote the file and the one reading it disagree?', null, null, '[{"id":"p1","point":"Both sides must use the same encoding, the rule that maps characters to bytes and back"},{"id":"p2","point":"With different encodings the same bytes decode to different characters, so the text looks garbled, for example é shown as two odd symbols"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 1), 'build', 'build', 'Optional exploration: write a small program that prints each character of a line of input with its code point and the number of bytes it takes in UTF-8. Try plain English, café, a Chinese word and an emoji.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 1), 'hint', '', 'Think of a code book. What happens if the sender and the receiver use different books?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 1), 'example', '', 'Two people agree that 1 means yes and 2 means no. A third person who thinks 1 means no reads the same message and gets the opposite answer, although nothing in the message changed.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1), 2, 'Why UTF-8 has variable length', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 2), 'think', 'predict', 'The grinning face emoji is the code point U+1F600. How many bytes does it take in UTF-8? Answer with one number.', null, '{"match":"number_exact","expected":4,"derivation":"UTF-8 uses one byte up to U+007F, two up to U+07FF, three up to U+FFFF and four above that. U+1F600 is above U+FFFF, so it needs four bytes: F0 9F 98 80. It cannot take fewer, because a three-byte sequence only carries 16 bits of the code point and U+1F600 needs 17. Proof script output: 4."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 2), 'build', 'build', 'Add -c to ccwc so it prints the byte count and the file name. For the challenge''s test.txt it should print 342190. Check it on a file holding café and one holding an emoji: the byte count should match what the lesson predicts.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 2), 'hint', '', 'Compare U+1F600 with the largest code point that fits in three bytes, U+FFFF.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 2), 'example', '', 'The euro sign is U+20AC. It is above U+07FF but not above U+FFFF, so it takes three bytes.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1), 3, 'Code units are not characters', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 3), 'think', 'trace', 'The thumbs up with a medium skin tone is two code points, U+1F44D and U+1F3FD. JavaScript and Java store strings in UTF-16 and their length counts code units. What length does a string holding only this emoji report? Answer with one number.', null, '{"match":"number_exact","expected":4,"derivation":"Both code points are above U+FFFF, so in UTF-16 each needs a surrogate pair of two units. Two code points times two units gives a length of 4, although a reader sees one thumb. Proof script output: 4."}'::jsonb, null);
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 3), 'hint', '', 'First decide how many UTF-16 units one code point above U+FFFF needs, then count the code points.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 3), 'example', '', 'The flag of India is two regional indicator code points, both above U+FFFF, so a UTF-16 string holding it has length 4 and a UTF-8 file holding it is 8 bytes.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1), 4, 'What counts as one character', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 4), 'think', 'explain', 'A sign-up form limits display names to 10 characters, and a user named José is told the name José is already taken, although no account shows exactly that name. Another user''s name, with a family emoji in it, is rejected as too long although it looks short. Explain what is going on in both cases, and what each form should do instead.', null, null, '[{"id":"p1","point":"é can be stored as one code point or as e plus a combining accent, so names that look the same can have different code points"},{"id":"p2","point":"Names should be normalised to one form, such as NFC, before they are stored or compared"},{"id":"p3","point":"A family emoji is several code points joined by invisible joiners, so counting code points counts it as many characters"},{"id":"p4","point":"A limit on what users see should count grapheme clusters, the visible characters"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 4), 'build', 'build', 'Add -m to ccwc so it counts characters as code points, as the real wc does in a UTF-8 locale. Try it on a file holding a family emoji and note that it reports five characters for one picture.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 4), 'hint', '', 'Look at the two ways é can be stored, and at what is hidden between the people in a family emoji.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1) and s.position = 4), 'example', '', 'Two keys can look identical and still not open the same lock, because the difference is inside. Text can look identical and still be different code points.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 1), null, 1, 'Explain to a teammate why counting characters in a UTF-8 file is harder than counting bytes, and why a language such as JavaScript or Java gives yet another number for the same text.', '[{"id":"t1","concept":"text-encoding-utf8","point":"UTF-8 stores each code point in one to four bytes, with ASCII in one byte, so bytes and characters differ for anything beyond ASCII"},{"id":"t2","concept":"text-encoding-utf8","point":"The first byte of each character says how long it is, so a counter can find where characters start"},{"id":"t3","concept":"utf16-code-units","point":"Java and JavaScript count UTF-16 code units, and a code point above U+FFFF such as most emoji takes two units"},{"id":"t4","concept":"grapheme-clusters","point":"What a reader sees as one character can be several code points, so even a code point count is not what users see"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), 2, 'Reading any size in constant memory', 'Why memory stays flat from 2 KB to 20 GB, what the read call really promises, and why buffers make reading fast.');
insert into milestone_concept (milestone_id, concept_id) select (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2), id from concept where slug in ('streaming-constant-memory', 'stream-read-contract', 'io-buffering');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2), 1, 'What state does the answer need?', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2) and s.position = 1), 'think', 'explain', 'You have a 20 GB log and a machine with 8 GB of memory. Which of these can you compute in one pass with memory that does not grow with the file: the number of bytes, the number of lines, the longest line, the number of distinct words? For each, say what has to be remembered while reading.', null, null, '[{"id":"p1","point":"Bytes, lines and the longest line need only a few running numbers, so their memory stays the same whatever the file size"},{"id":"p2","point":"Distinct words need a set of every word seen so far, which grows with the input"},{"id":"p3","point":"Constant memory means the state carried between chunks does not grow with the input"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2) and s.position = 1), 'build', 'build', 'Make ccwc -c count bytes by reading the input in fixed-size chunks and adding up what each read returns, instead of loading the whole file. Check that it still prints 342190 for test.txt, and that its memory use stays flat on a file of several gigabytes.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2) and s.position = 1), 'hint', '', 'For each count, imagine reading the file one page at a time. What must you write on a sticky note to carry to the next page?', 'generated');
