insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2) and s.position = 2), 'example', '', 'A delivery van that arrives half full has not delivered the last parcel of the year. It only means this trip carried fewer.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2), 3, 'Why buffers make it fast', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2) and s.position = 3), 'think', 'explain', 'Version A of a counter asks the operating system for one byte at a time. Version B asks for 64 KB at a time. Both read exactly the same bytes, yet A is many times slower on a 1 GB file. Explain why, and why making B''s buffer 64 MB would not make it much faster.', null, null, '[{"id":"p1","point":"Each read is a system call with a fixed cost, so one call per byte pays that cost a billion times"},{"id":"p2","point":"A larger buffer spreads the cost of one call over many bytes, which are then processed in memory"},{"id":"p3","point":"Beyond some tens of kilobytes the disk or memory speed is the limit, so a much bigger buffer only uses more memory"}]'::jsonb);
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2) and s.position = 3), 'hint', '', 'Think about the cost of each request, not the cost of each byte.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2) and s.position = 3), 'example', '', 'Fetching water one cup per trip to the well takes all day; carrying a bucket is far faster. A bucket the size of a bathtub does not help, because you can no longer carry it quickly.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 2), null, 1, 'Your tool might be handed a 2 KB file or a 20 GB log piped from another program. Explain how it reads the input, why its memory stays the same in both cases, and what could go wrong in the read loop.', '[{"id":"t1","concept":"streaming-constant-memory","point":"It reads fixed-size chunks and keeps only running totals, so its memory does not depend on the input size"},{"id":"t2","concept":"stream-read-contract","point":"It uses the count each read returns and stops only on the end marker, never on a short read"},{"id":"t3","concept":"io-buffering","point":"Chunks of some kilobytes keep the number of system calls low without wasting memory"}]'::jsonb);
