insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 3), 2, 'The invisible bytes at the start', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 3) and s.position = 2), 'think', 'explain', 'A script reads a CSV that someone saved from Excel as CSV UTF-8 and looks up the column called id. The header line looks exactly like id,name on screen, yet the lookup fails, and ccwc -m counts one character more than the visible text. What is hiding in front of id, and what should a reader of UTF-8 text do about it?', null, null, '[{"id":"p1","point":"The file starts with a byte order mark, U+FEFF, stored as the three bytes EF BB BF, which is invisible on screen"},{"id":"p2","point":"Without skipping it, the first column name is read as the mark followed by id, so it never equals id"},{"id":"p3","point":"A reader should skip a byte order mark at the start of UTF-8 text, or the tool should state that it counts it"}]'::jsonb);
