insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 3) and s.position = 3), 'think', 'explain', 'A 20 GB log contains a few bytes that are not valid UTF-8: a stray byte from a crashed process, and a character cut off at the very end of the file. What can a decoder do with such bytes, and what should a counting tool like ccwc do?', null, null, '[{"id":"p1","point":"A decoder can reject the input with an error, replace each bad sequence with the replacement character U+FFFD, or skip it"},{"id":"p2","point":"A counter should not stop on the first bad byte of a huge file; it should keep counting and handle bad bytes by a clear, documented rule"},{"id":"p3","point":"An unfinished character at the end of input is invalid too, and should be handled the same way when the input ends"}]'::jsonb);
