insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 3) and s.position = 3), 'example', '', 'A post office that gets a letter with a smudged address can return it, guess, or set it aside and keep sorting the rest. Stopping all mail for one smudge would be the worst choice.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 3), null, 1, 'Explain how your tool turns a stream of bytes into characters without ever breaking one, and what it does with bytes that are not valid text.', '[{"id":"t1","concept":"decoding-across-chunks","point":"The decoder keeps the bytes of a character cut off at the end of a chunk and finishes it with the start of the next chunk"},{"id":"t2","concept":"explicit-charsets","point":"It names UTF-8 explicitly instead of relying on a default that differs between machines, and decides what to do with a byte order mark"},{"id":"t3","concept":"malformed-input","point":"Invalid bytes are handled by one clear rule, such as replacing or skipping them, without stopping the whole count"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), 4, 'What lines and words really are', 'A line is a convention, newline or carriage return and newline, with or without a final newline. A word is a run of non-whitespace, and what counts as whitespace is not obvious.');
