insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 4), 1, 'One line fewer than the editor', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 4) and s.position = 1), 'think', 'explain', 'Your editor shows 10 lines in a file, but the real wc -l reports 9. Neither program is broken. Explain what is different and which definition wc follows.', null, null, '[{"id":"p1","point":"wc counts newline bytes, and the last line of this file has no newline after it"},{"id":"p2","point":"POSIX defines a line as text ending in a newline, while the editor counts the lines it displays"}]'::jsonb);
