insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 4) and s.position = 3), 'think', 'explain', 'Is don''t one word? Is rock-and-roll? What about two words separated by a no-break space copied from a web page? Explain the rule wc uses, why that rule lets it count words while streaming, and why the no-break space case can differ between machines.', null, null, '[{"id":"p1","point":"wc counts a word as any run of characters that are not whitespace, so punctuation belongs to the word and don''t and rock-and-roll are one word each"},{"id":"p2","point":"Counting needs only one remembered state, inside or outside a word, carried from one chunk to the next"},{"id":"p3","point":"Whether characters such as the no-break space count as whitespace depends on the tool, its version and the locale"}]'::jsonb);
