insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 4), null, 1, 'Explain to someone why wc''s line and word counts can differ from what they see in their editor or expect from reading the text.', '[{"id":"t1","concept":"line-endings","point":"Lines are counted by newline bytes, so a last line without a newline is not counted"},{"id":"t2","concept":"line-endings","point":"Windows line endings add a carriage return before each newline, which is an extra byte and stays in the line''s text"},{"id":"t3","concept":"word-state-machine","point":"A word is any run of non-whitespace, found by remembering whether you are inside a word"},{"id":"t4","concept":"word-state-machine","point":"Which characters count as whitespace depends on the locale, so word counts can differ between machines"}]'::jsonb);
