insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5) and s.position = 2), 'think', 'explain', 'A script runs ccwc on three files, and the second one does not exist. What should ccwc print, on which stream, and with what exit status? Why does it matter to the script?', null, null, '[{"id":"p1","point":"It prints the counts for the files that exist on standard output and keeps going after the missing one"},{"id":"p2","point":"It writes an error naming the missing file on standard error, so the results stay clean"},{"id":"p3","point":"It exits with a non-zero status, so the script can tell that something failed"}]'::jsonb);
