insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5) and s.position = 2), 'hint', '', 'Think about who reads each stream: the next program, or the person.', 'generated');
