insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5), 3, 'Same file, different answer', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5) and s.position = 3), 'think', 'explain', 'On one machine wc -m on the challenge''s test.txt prints 339292. In another terminal on the same machine it prints 342190, which is also the file''s byte count. Nothing changed in the file or in wc. Explain what is different, and how you would make test results reproducible.', null, null, '[{"id":"p1","point":"The locale differs, for example a UTF-8 locale in one terminal and the C locale in the other, through LANG or LC_ALL"},{"id":"p2","point":"In the C locale every byte counts as one character, so -m gives the byte count"},{"id":"p3","point":"Set the locale explicitly whenever the tool runs in tests and scripts, and record which locale an expected value came from"}]'::jsonb);
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5) and s.position = 3), 'hint', '', 'What did the second answer equal, and in which setting does every byte count as one character?', 'generated');
