insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5), 4, 'Proving it matches the real wc', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5) and s.position = 4), 'think', 'explain', 'Your own tests with expected numbers all pass, but running the real wc on the same file gives a different word count. What does comparing against the real tool catch that your own expected values miss, and which inputs would you compare on?', null, null, '[{"id":"p1","point":"Expected values come from your own understanding, so they share your code''s mistakes"},{"id":"p2","point":"The reference shows cases you did not think of, such as unusual whitespace, line endings, invalid bytes or the locale"},{"id":"p3","point":"Compare on many varied inputs, including empty files, no final newline, emoji, invalid bytes, large files and piped input, with the reference version and locale fixed"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5) and s.position = 4), 'build', 'build', 'Write a check that runs the real wc and ccwc on the same set of inputs, with the locale set explicitly, and reports any difference.');
