insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc') and m.position = 5), null, 1, 'Explain what makes ccwc a well-behaved Unix tool that other programs can rely on, and how you would prove it behaves like the real wc.', '[{"id":"t1","concept":"stdin-vs-file","point":"It reads standard input when no file is named, with the same counting loop, because both are byte streams"},{"id":"t2","concept":"cli-subcommands","point":"Results go to standard output, errors to standard error, and failure gives a non-zero exit status"},{"id":"t3","concept":"locale-settings","point":"Its character and word counts depend on the locale, so tests set the locale explicitly"},{"id":"t4","concept":"differential-testing","point":"It is compared with the real wc on the same varied inputs, with the reference version and locale pinned"}]'::jsonb);
