insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver'), 1, 'One request, one reply', 'Accept a TCP connection, read a whole request, and answer with the path that was asked for.');
