insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1), 1, 'Read the request line', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 1), 'think', 'predict', 'curl asks your server for http://localhost/docs/intro.html, and the request line it sends is GET /docs/intro.html HTTP/1.1. What path does your server take out of that line?', null, '{"match":"text_ci","expected":"docs/intro.html","derivation":"The request line has three parts separated by single spaces: the method GET, the path /docs/intro.html and the version HTTP/1.1. The path is the second part. The key leaves off the leading slash so that an answer of /docs/intro.html and one of docs/intro.html both match. Proof script output: docs/intro.html."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 1), 'build', 'build', 'Open a TCP socket bound to 127.0.0.1 on port 80, or on a port such as 8080 if your system needs administrator rights for 80. Accept one connection at a time, read the request line, and split it into the method, the path and the version.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 1), 'hint', '', 'The request line has three parts with a single space between each. Which part names what is being asked for?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 1), 'example', '', 'In the line POST /login HTTP/1.1 the method is POST, the path is /login and the version is HTTP/1.1.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1), 2, 'Read up to the empty line', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 2), 'think', 'predict', 'curl sends these lines, each ending with a carriage return and a line feed: GET / HTTP/1.1, then Host: localhost, then User-Agent: curl/8.4.0, then Accept: */*, then an empty line. How many header lines does this request have?', null, '{"match":"number_exact","expected":3,"derivation":"The first line is the request line, not a header. Host, User-Agent and Accept are the headers. The empty line is not a header either, it only marks where the headers end. So there are 3. Proof script output: 3."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 2), 'build', 'build', 'Keep reading from the connection, adding each read to what you already have, until you have seen the empty line that ends the headers. Log each header line, and make sure a request that arrives in several small pieces is read the same as one that arrives at once.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 2), 'hint', '', 'Name each line in turn. Is it the request line, a header, or the line that only marks the end?', 'generated');
