insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1), 3, 'Write the reply', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 3), 'think', 'spot_bug', 'This handler works with curl on your machine most of the time, but some clients get a garbled reply or a wrong path. Find the two problems and say how to fix each.', 'conn = accept(server)
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 3), 'build', 'build', 'Reply with the status line HTTP/1.1 200 OK, an empty line, and the body Requested path: followed by the path, then close the socket. Running curl http://localhost/ should print Requested path: /.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 3), 'hint', '', 'Ask what a single read is promised to return, and how a client knows the headers of the reply are over.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1) and s.position = 3), 'example', '', 'Someone reading a letter aloud over a crackly phone line may get it in pieces. You wait for the sign-off before you answer, not for the first pause.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 1), null, 1, 'Explain what your server does from the moment curl connects until curl prints the reply, and how the server knows it has the whole request.', '[{"id":"t1","concept":"tcp-sockets","point":"The server binds to an address and port and listens, and each accepted connection gets its own socket, a two-way stream of bytes that is closed after the reply"},{"id":"t2","concept":"message-framing","point":"TCP keeps no message boundaries, so the server keeps reading and buffering until the empty line that ends the headers has arrived"},{"id":"t3","concept":"http-message-format","point":"A request is a request line with method, path and version, then headers, then an empty line, and the reply is a status line, an empty line and the body, with every line ending in a carriage return and line feed"}]'::jsonb);
insert into milestone (challenge_id, position, title, summary) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver'), 2, 'Serve files from www', 'Turn the request path into a file in the www folder, and send it with the right status and length.');
