insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2), 1, 'Map paths to files', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2) and s.position = 1), 'think', 'trace', 'The www folder holds index.html and nothing else. Your server gets four requests, for the paths /, then /index.html, then /about.html, then /index. How many of them are answered with 200 OK?', null, '{"match":"number_exact","expected":2,"derivation":"The path / is mapped to index.html, so it gets 200. /index.html names the file directly, so it gets 200. There is no about.html, so that gets 404, and /index names a file called index with no extension, which does not exist either, so 404. That makes 2. Proof script output: 2."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2) and s.position = 1), 'build', 'build', 'Create a www folder holding an index.html. Answer / and /index.html with 200 OK and the contents of that file, and answer any path with no matching file with 404 Not Found. The challenge page''s sample shows 400 Not Found, but 404 is the code that means not found, so use 404.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2) and s.position = 1), 'hint', '', 'For each path, first apply the one special rule for a bare slash, then ask whether a file with exactly that name exists.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2) and s.position = 1), 'example', '', 'A library desk that hands you the welcome leaflet when you ask for nothing in particular still says no when you ask for a book it does not have.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2), 2, 'Where the body ends', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2) and s.position = 2), 'think', 'explain', 'Your server closes the connection after each reply, so the client knows the body is over. A browser would rather send several requests over one connection. How can it then tell where one reply''s body ends, and what must the server get exactly right?', null, null, '[{"id":"p1","point":"Closing the connection marks the end of the body, but that only works for one reply per connection"},{"id":"p2","point":"A Content-Length header tells the client how many bytes of body follow the empty line"},{"id":"p3","point":"If the length is too small, the rest of the body is read as the start of the next reply, and if it is too large the client waits for bytes that never come"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2) and s.position = 2), 'build', 'build', 'Send a Content-Length header with the size of the body in bytes and a Content-Type of text/html for HTML files, then check the headers with curl -i.');
