insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 2), null, 1, 'Explain how your server turns a request path into a reply, and how the client knows where the body of that reply ends.', '[{"id":"t1","concept":"static-file-serving","point":"The path is mapped to a file inside www, with / giving index.html, and the file is sent with 200 OK and a matching Content-Type, or 404 Not Found when there is no such file"},{"id":"t2","concept":"message-framing","point":"The body''s end is marked either by closing the connection or by a Content-Length header sent before the body"},{"id":"t3","concept":"bytes-vs-characters","point":"The file is read as bytes and Content-Length counts bytes, because a character can take more than one byte and images are not text"}]'::jsonb);
