insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3), 1, 'Serve clients side by side', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 1), 'think', 'trace', 'Three clients connect at the same moment, and your server takes 2 seconds to answer each request. How many seconds does the last client wait for its reply when the server handles one connection at a time, and how many when it handles each connection on its own thread? Give the first, then the second.', null, '{"match":"numbers_all","expected":[6,2],"derivation":"One at a time, the first reply is sent at 2 seconds, the second at 4 and the third at 6, because each client waits for the ones ahead of it. With a thread per connection all three are handled together, so every reply, the last one included, is sent at 2 seconds. Proof script output: [6, 2]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 1), 'build', 'build', 'Handle each connection on its own thread or task. To test it, make each request wait 20 seconds and log the thread id, then start 7 curl requests at once. All 7 should come back after about 20 seconds, with different thread ids in the log, not one after another.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 1), 'hint', '', 'Draw a timeline for each server. When can the second client''s request start being handled?', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 1), 'example', '', 'A shop with one till serves the queue one person at a time, so the third customer waits for the two before them. With three tills open, all three are served at once.', 'generated');
insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3), 2, 'Limits for slow clients', 15);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 2), 'think', 'explain', 'Your server now starts a new thread for every connection. What can go wrong when a client connects and never sends anything, or when thousands of clients connect at once, and what limits help?', null, null, '[{"id":"p1","point":"Each open connection holds a thread and its memory, so a silent client ties them up for as long as it stays connected"},{"id":"p2","point":"Thousands of connections at once means thousands of threads, which can run the machine out of memory or threads"},{"id":"p3","point":"A read timeout closes clients that send nothing, and a fixed pool of threads or an event loop caps what many clients can take"}]'::jsonb);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 2), 'build', 'build', 'Close a connection that has sent nothing for a few seconds, and decide how many connections your server will handle at once, for example with a thread pool.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 2), 'hint', '', 'What does one waiting thread cost, and does that cost go away while its client stays silent?', 'generated');
