insert into step (milestone_id, position, title, est_minutes) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3), 4, 'Choose the folder and test it', 10);
insert into task (step_id, role, kind, prompt, snippet, answer_key, rubric) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 4), 'think', 'predict', 'The www folder is /srv/www. It holds index.html and a folder docs, which holds guide.html. Your server answers 200 for an existing file inside www, 404 for a path inside www with no file, and 403 for any path that resolves outside www. What status does it send for each of these requests, in this order: /docs/../index.html, then /../secret.txt, then /docs/missing.html?', null, '{"match":"numbers_all","expected":[200,403,404],"derivation":"Joined to /srv/www, the first path is /srv/www/docs/../index.html, and applying the .. removes docs, giving /srv/www/index.html, which is inside and exists: 200. The second becomes /srv/www/../secret.txt, and the .. removes www, giving /srv/secret.txt, which is outside: 403. The third is /srv/www/docs/missing.html, inside but not there: 404. Proof script output: [200, 403, 404]."}'::jsonb, null);
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 4), 'build', 'build', 'Take the www folder as a startup argument, and refuse to start, with a message on the error stream and a non-zero exit status, if it does not exist. Write tests that send traversal attempts, including encoded dots and a sibling folder whose name starts with www, and check that none of them returns a file.');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 4), 'hint', '', 'Join each path to the folder, let every .. remove the folder name just before it, and only then look at where you ended up.', 'generated');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3) and s.position = 4), 'example', '', 'From the folder /home/sam/photos, going into trips and then up one level lands back in photos, but going up one level straight away lands in /home/sam, which is outside photos.', 'generated');
insert into question (milestone_id, concept_id, position, prompt, rubric) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver') and m.position = 3), null, 1, 'Someone on your network sends many requests at once, some of them slow and some asking for files outside www. Explain how your server keeps answering everyone, keeps the files safe, and learns which folder to serve.', '[{"id":"t1","concept":"concurrent-connections","point":"Each connection is handled on its own thread, a pooled thread or an event loop, so a slow client does not hold up the others, with timeouts and a cap on how many run at once"},{"id":"t2","concept":"untrusted-paths","point":"The request path is joined to www, resolved and normalised, and refused unless the result is still inside www, because filtering out the text .. is not enough"},{"id":"t3","concept":"cli-subcommands","point":"The www folder is given as a startup argument, and a missing or bad folder gives a message on the error stream and a non-zero exit status"}]'::jsonb);
