-- project coding_challenges/challenge-bitcask
do $$ begin if exists (select 1 from enrollment where challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask')) then
  raise exception 'project challenge-bitcask has learners, so its curriculum is frozen'; end if; end $$;
delete from milestone where challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask');
update challenge set title = 'Build your own Bitcask', source_url = 'https://codingchallenges.fyi/challenges/challenge-bitcask', level = 'intermediate',
  summary = 'A key-value store and command-line tool that appends every write to a log of checksummed records, keeps an in-memory index of where each value lives, deletes with tombstones, compacts old files with a merge that writes hint files, and recovers cleanly after a crash.', requirements = array['Set, get and delete keys from the command line, with the database directory given by -db', 'Append every write to the active log file as a record that starts with a CRC-32 checksum', 'Close the active file at a size limit and start a new one, leaving all older files unchanged', 'Keep an in-memory keydir with the file, position, size and timestamp of each key''s latest value', 'Read a value with one seek and one read, and never return a deleted key', 'Merge closed files into new ones holding only live values, with a hint file for each, and rebuild the keydir on startup']::text[],
  restate_rubric = '[{"id":"r1","point":"It is a key-value store that never changes data in place but appends every write to a log file"},{"id":"r2","point":"An in-memory index records where each key''s latest value is on disk, so a read is one seek"},{"id":"r3","point":"Deletes write tombstones, a merge removes stale data, and startup rebuilds the index and skips damaged records"}]'::jsonb, reflection_prompt = 'In your own words, what did you give up and what did you gain by never changing a record in place, and what would you change if the keys no longer fitted in memory?',
  primer = '{"what":"Bitcask is a way to build a key-value store on disk. Every write, even an update, is added to the end of a log file, and nothing already written is ever changed. A table in memory, called the keydir, remembers for each key where its latest value sits in the log, so reading means one jump to the right place. You will start with a first version that simply rewrites the whole table to one file after every change, then turn it into Bitcask.","why":"Adding to the end of a file is the fastest thing a disk does, and a crash can only damage the last record. It is how the Riak database stores data, and the same log idea sits under many modern databases.","example":"Suppose you set colour to red, then set colour to blue. The first version keeps a table in memory and writes it out whole after each change, so its file ends with a single line, colour then blue. The log version appends instead, so its file holds two records, one for red and one for blue, and the keydir entry for colour points at the second record.","words":[{"term":"log","meaning":"A file that is only ever added to at the end. Old records stay where they are."},{"term":"record","meaning":"One entry in the log, holding a checksum, a timestamp, the sizes of the key and value, then the key and the value."},{"term":"keydir","meaning":"The in-memory table from each key to the file, position and size of its latest value."},{"term":"active file","meaning":"The one log file currently being written. When it reaches a size limit it is closed and never changed again."},{"term":"checksum","meaning":"A number computed from a record''s bytes and stored with it, so damage can be detected when the record is read."},{"term":"tombstone","meaning":"A record that says a key has been deleted."}]}'::jsonb, figure_kind = 'log',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask');
    header = pack(timestamp(), size(key), size(value))
    crc = crc32(value)
    append(active_file, crc + header + key + value)
    print("ok")', null, '[{"id":"p1","point":"The CRC covers only the value, so a damaged timestamp, key size, value size or key is not detected"},{"id":"p2","point":"Compute the CRC over everything written after it, the header fields, the key and the value"},{"id":"p3","point":"It reports success before the record is forced to disk, so a crash right after can lose a write the user was told succeeded"}]'::jsonb);
    entry = keydir[key]
    file = open(active_file)
    seek(file, entry.value_position)
    value = read(file, entry.value_size)
    print(value)', null, '[{"id":"p1","point":"It always opens the active file, but the value may be in an older closed file, so it must open the file named by the entry''s file id"},{"id":"p2","point":"It looks up the key without checking it is there, so a key that was never set or was deleted crashes or prints junk instead of nil"}]'::jsonb);
    merged = new_file()
    for file in all_files(db):
        for record in file:
            if record is not a tombstone:
                append(merged, record)
        delete(file)', null, '[{"id":"p1","point":"It copies every value that is not a tombstone, including stale older values, so it should copy only the record the keydir points to for each key"},{"id":"p2","point":"It includes the active file, which is still being written, when merge should only touch closed files"},{"id":"p3","point":"It deletes each old file before the merged file is complete, synced and the keydir points at it, so a crash mid-merge loses data"}]'::jsonb);

