update challenge set title = 'Build your own spell checker using a Bloom filter', source_url = 'https://codingchallenges.fyi/challenges/challenge-bloom', level = 'beginner',
  summary = 'A command-line spell checker that squeezes a dictionary into a Bloom filter, saves it as a small binary file with its own header, loads it again and reports which words are probably spelt wrong, without ever storing the word list itself.', requirements = array['Size a Bloom filter from the number of words and the false positive rate you accept', 'Insert words by setting the bits chosen by several hash functions, such as FNV-1a', 'Build the filter from a dictionary file with a build option', 'Save it as a CCBF file, a big-endian header followed by the packed bits, and load it back after checking the header', 'Check the words given as arguments and print the ones that are probably spelt wrong']::text[],
  restate_rubric = '[{"id":"r1","point":"It stores a dictionary as a Bloom filter, a bit array set by several hash functions, instead of the words"},{"id":"r2","point":"A build option reads a dictionary and saves the filter to a file with a header, and the checker loads that file"},{"id":"r3","point":"Words given on the command line are checked and the ones that are not in the filter are reported as spelt wrong"}]'::jsonb, reflection_prompt = 'In your own words, what did you give up by storing bits instead of words, what did you get for it, and how would you choose the size differently for a different use?',
  primer = '{"what":"A Bloom filter answers one question about a set, is this item in it, using only a row of bits and a few hash functions. Adding a word runs it through each hash function, and each one picks a bit to turn on. Checking a word looks at the same bits. You will use one to build a spell checker that keeps a whole dictionary in a file far smaller than the word list.","why":"Storing every word takes a lot of space. A Bloom filter takes a fraction of it and answers fast, at the price of sometimes saying yes to a word that was never added. For a spell checker that trade is often fine.","example":"Picture a filter of 8 bits, all zero. Adding the word sun, its two hash functions point at bits 0 and 3, so those two bits become one. Checking the word sky, its hashes point at bits 3 and 5. Bit 5 is still zero, so sky was definitely never added. A bit can be turned on by more than one word, and turning on a bit that is already one changes nothing.","words":[{"term":"bit array","meaning":"A row of bits, each zero or one, numbered from 0. A new filter starts with every bit at zero."},{"term":"hash function","meaning":"A recipe that turns any word into a number, always the same number for the same word. FNV-1a is a simple, fast one."},{"term":"false positive","meaning":"The filter saying a word is probably there when it was never added."},{"term":"false negative","meaning":"The filter saying a word is missing when it was added. A Bloom filter never does this."},{"term":"header","meaning":"The first bytes of a file, which say what kind of file it is and the numbers needed to read the rest."},{"term":"big-endian","meaning":"Writing a number of several bytes with its most significant byte first, so 7 in two bytes is a zero byte, then a byte holding 7."}]}'::jsonb, figure_kind = 'bits',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bloom');
    result = []
    for i from 0 to k - 1:
        h = fnv1a(word)
        result.append(h)
    return result', null, '[{"id":"p1","point":"Every pass computes the same hash of the same word, so all k positions are the same bit and the filter behaves as if it had one hash function"},{"id":"p2","point":"Each pass should give a different value, for example by seeding the hash with i or by combining two hashes as the first plus i times the second"},{"id":"p3","point":"The hash is a large number used as a position without being reduced, so it must be taken as the remainder after dividing by m to land inside the bit array"}]'::jsonb);
for word in split(text, "\n"):
    filter.add(word)
save(filter, "words.bf")', null, '[{"id":"p1","point":"Windows line endings put a carriage return before each newline, so every word is stored with a carriage return on the end and never matches a word typed on the command line"},{"id":"p2","point":"Strip the carriage return, or trim whitespace, from each line before adding it"},{"id":"p3","point":"The final newline leaves an empty last piece, which is added as a word, so empty lines should be skipped"}]'::jsonb);
hashes = number_from_bytes(data[6..8], little_endian)
bits = number_from_bytes(data[8..12], little_endian)
filter = new_filter(bits, hashes, data[12..])', null, '[{"id":"p1","point":"It never checks that the first four bytes are CCBF and that the version is one it understands, so any other or newer file is silently misread"},{"id":"p2","point":"It should stop with a clear message on the error stream and a non-zero exit status when the identifier or version is wrong"},{"id":"p3","point":"It reads the numbers as little-endian, but the header is big-endian, so the hash count and bit count come out wrong"}]'::jsonb);

