update challenge set title = 'Build your own Brainfuck interpreter', source_url = 'https://codingchallenges.fyi/challenges/challenge-brainfuck', level = 'intermediate',
  summary = 'An interpreter for Brainfuck, a language of eight one-character commands that work on a tape of 30,000 byte cells. It starts as a REPL and a file runner, then compiles programs to bytecode for a small virtual machine and speeds it up with run-length merging and pattern rewrites, timed on a Mandelbrot program.', requirements = array['Start a REPL with no arguments, and run a program file when one is named', 'Run all eight commands on 30,000 cells that start at zero, ignoring every other character', 'Pair loop brackets correctly, including nested loops, and report unbalanced brackets', 'Compile the program to bytecode with comments removed and jump targets worked out, and run it on a virtual machine', 'Merge runs of the same command into one instruction, and turn common loops such as clearing a cell into single instructions', 'Time the Mandelbrot program at each stage and check that its picture never changes']::text[],
  restate_rubric = '[{"id":"r1","point":"The tool runs Brainfuck programs, from a REPL or from a file, on a tape of cells with a data pointer"},{"id":"r2","point":"It first interprets the source directly, then compiles it to bytecode that a small virtual machine runs"},{"id":"r3","point":"It adds optimisations such as merging repeated commands and replacing common loops, and measures the speedup on a Mandelbrot program"}]'::jsonb, reflection_prompt = 'In your own words, where did your interpreter spend its time at the start, which change gave the biggest speedup, and what would you try next?',
  primer = '{"what":"Brainfuck is a tiny programming language with only eight commands, each a single character. A program works on a long row of 30,000 cells, each holding a number that starts at zero, and a data pointer that marks one cell as the current one. Plus and minus add or take one from the current cell, the greater-than and less-than signs move the pointer one cell right or left, a full stop prints the current cell as a character, and a comma reads one character into it. Square brackets make a loop that repeats its body while the current cell is not zero.","why":"With so few commands you can write a working interpreter in an afternoon, and then spend the rest of the project on the ideas behind real language runtimes: compiling to bytecode, resolving jumps ahead of time, and optimising the instructions that run most often.","example":"Take the program plus, plus, greater-than, plus, plus, plus. The first two commands make the first cell 2, the greater-than moves the pointer to the second cell, and the three pluses make that cell 3. The program ends with the pointer on the second cell. Any letter, space or digit in the program would simply be skipped.","words":[{"term":"cell","meaning":"One slot on the tape, holding a small number. Usually a byte, from 0 to 255."},{"term":"data pointer","meaning":"Which cell the commands currently work on. The greater-than and less-than commands move it."},{"term":"program counter","meaning":"Which command of the program runs next. It normally moves forward by one, and brackets make it jump."},{"term":"loop","meaning":"A body between square brackets that runs again and again until the current cell is zero at a bracket."},{"term":"bytecode","meaning":"A compact list of instructions made from the source ahead of time, which a small virtual machine runs."}]}'::jsonb, figure_kind = 'tape',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-brainfuck');
while pc < length(code):
