update challenge set title = 'Build your own calculator', source_url = 'https://codingchallenges.fyi/challenges/challenge-calculator', level = null,
  summary = 'A calculator that reads an arithmetic expression as text, with plus, minus, times, divide and brackets, splits it into tokens, rearranges it into postfix order with the shunting yard algorithm, and evaluates it with a stack, respecting precedence and reporting invalid input.', requirements = array['Read an expression such as 2 * 3 + 4 and print its value', 'Read numbers with several digits as one number, and reject characters that are not part of an expression', 'Apply times and divide before plus and minus, work equal operators from left to right, and honour brackets', 'Decide between whole-number and floating-point results, and print whole results without a decimal part', 'Convert the expression to postfix order with the shunting yard algorithm and evaluate it with a stack', 'Report invalid input, such as unmatched brackets or a missing number, instead of crashing', 'Keep an automated set of tests that runs on every change']::text[],
  restate_rubric = '[{"id":"r1","point":"The calculator takes an arithmetic expression as text and prints its value"},{"id":"r2","point":"It respects precedence and brackets, so times and divide happen before plus and minus unless brackets say otherwise"},{"id":"r3","point":"It turns the expression into tokens, converts it to postfix order and evaluates that with a stack"}]'::jsonb, reflection_prompt = 'In your own words, how does your calculator decide the order of operations, and what would you change to add a power operator or functions such as sin?',
  primer = '{"what":"A calculator program takes an expression written as text, a few numbers joined by plus, minus, times and divide signs, perhaps with brackets, and prints its value. The hard part is not the arithmetic but the order: times and divide happen before plus and minus, and brackets override both. You will build one that splits the text into tokens, rearranges them so the order is explicit, and evaluates the result with a stack.","why":"The same three steps, reading tokens, sorting out the order of operators and evaluating with a stack, sit at the heart of every interpreter and compiler. A calculator is the smallest program that needs all three.","example":"Take 7 minus 2 times 3. The tokens are 7, minus, 2, times and 3. Times binds tighter than minus, so 2 times 3 is worked out first, giving 6, and 7 minus 6 gives 1. Working strictly from left to right would give 15, which is wrong.","words":[{"term":"token","meaning":"One meaningful piece of the expression, such as a whole number or an operator sign."},{"term":"precedence","meaning":"The rule for which operator is applied first. Times and divide come before plus and minus."},{"term":"associativity","meaning":"The rule for which of two operators with the same precedence, such as two minus signs in a row, is applied first."},{"term":"postfix notation","meaning":"Writing each operator after the two numbers it works on, so 2 plus 3 becomes 2, 3, plus. It needs no brackets."},{"term":"stack","meaning":"A pile where you only add to the top or take from the top."}]}'::jsonb, figure_kind = 'tokens',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-calculator');
