return tokens', null, '[{"id":"p1","point":"Each digit becomes its own number, so 22 turns into two numbers, 2 and 2. It should keep reading while digits follow and build one number from them"},{"id":"p2","point":"Any other character, such as a letter, a dollar sign or a decimal point, is silently skipped, so bad input gives a wrong answer. It should be reported as invalid input"}]'::jsonb);
    if is_number(token):
        output.append(token)
