        ops.push(token)
while not ops.empty():
    output.append(ops.pop())', null, '[{"id":"p1","point":"A closing bracket with no opening bracket before it keeps popping until the stack is empty and then fails on an empty stack. It should stop and report an unmatched closing bracket"},{"id":"p2","point":"An opening bracket still on the stack at the end is copied into the output as if it were an operator. It should be reported as an unclosed bracket"}]'::jsonb);
for token in postfix:
    if is_number(token):
        stack.push(token)
    else:
        a = stack.pop()
        b = stack.pop()
        stack.push(apply(token, a, b))   # works out a, the operator, then b
return stack.pop()', null, '[{"id":"p1","point":"The first number popped is the right-hand operand, so for 8 2 minus this works out 2 minus 8. The operands should be swapped so the second number popped is on the left"},{"id":"p2","point":"It does not check that two numbers are on the stack before an operator, or that exactly one number is left at the end, so input such as 1 2 or a lone plus is not reported as invalid"}]'::jsonb);

