update challenge set title = 'Build your own code comment remover', source_url = 'https://codingchallenges.fyi/challenges/challenge-code-comment-remover', level = null,
  summary = 'A command-line tool that reads a source file in Python, JavaScript, C, C++ or Go and writes it back with the comments removed and the code unchanged, while keeping the comments that tools rely on, such as Go doc comments and linter or build directives.', requirements = array['Remove Python comments that start with a hash and run to the end of the line', 'Remove line comments and block comments from JavaScript, C and C++', 'Leave comment markers that appear inside strings and character literals alone', 'Keep Go doc comments that sit directly above a top-level declaration, and remove the other Go comments', 'Keep tool and linter directives, such as noqa in Python and go:generate or go:build in Go', 'The cleaned program must behave exactly like the original']::text[],
  restate_rubric = '[{"id":"r1","point":"The tool reads source code and writes it back with the comments removed and the code unchanged"},{"id":"r2","point":"It handles Python hash comments and the line and block comments of JavaScript, C, C++ and Go"},{"id":"r3","point":"It keeps comments that tools read, such as Go doc comments and linter or build directives"}]'::jsonb, reflection_prompt = 'In your own words, how does your tool tell a comment from the same characters inside a string, and what would you change to support another language?',
  primer = '{"what":"A comment is a note for people inside a program''s source code, and the computer skips it. In Python a comment starts with a hash and runs to the end of the line. JavaScript, C, C++ and Go use two slashes for a comment to the end of the line, and a slash followed by a star to open a block comment that a star followed by a slash closes, possibly many lines later. You will build a command-line tool that reads a source file and writes it back with the comments taken out and the code untouched.","why":"Stripping comments is the smallest useful job of a lexer, the same first step that compilers, minifiers and code formatters take. It also shows that the same character can mean different things depending on where it appears.","example":"Take a JavaScript line that sets a total to zero and then has two slashes and the words start empty. The tool keeps everything before the slashes, drops the slashes and the note, and trims the spaces left at the end of the line, so only the code that sets the total remains. A line that held nothing but a comment disappears.","words":[{"term":"comment","meaning":"A note inside source code that the language ignores when it runs or compiles the program."},{"term":"line comment","meaning":"A comment that starts with a marker, a hash in Python or two slashes in C-style languages, and ends at the end of the line."},{"term":"block comment","meaning":"A comment that opens with slash star and closes with star slash, and can cover part of a line or many lines."},{"term":"string literal","meaning":"Text written between quote marks inside code, such as a message the program prints."},{"term":"lexer","meaning":"A program that reads source code character by character and splits it into pieces such as code, strings and comments."},{"term":"directive","meaning":"A comment that a tool reads as an instruction, for example telling a linter to skip a line."}]}'::jsonb, figure_kind = 'states',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-code-comment-remover');
    cleaned = replace_pattern(line, "#.*", "")
    write_line(trim_end(cleaned))', null, '[{"id":"p1","point":"A hash inside a quoted string, such as a colour code or part of a web address, is not a comment, but the pattern cuts the line there and breaks the string"},{"id":"p2","point":"The fix is to walk the line character by character, remember whether it is inside a string, and only treat a hash found outside a string as the start of a comment"}]'::jsonb);
while not at_end(src):
    if peek(src, 2) == "/*":
