update challenge set title = 'Build your own curl', source_url = 'https://codingchallenges.fyi/challenges/challenge-curl', level = null,
  summary = 'A small curl that takes a URL on the command line, writes an HTTP/1.1 request by hand over a TCP socket, and prints the reply. It supports GET, DELETE, POST and PUT, request bodies and extra headers, and a verbose mode that shows what was sent and received.', requirements = array['Split a URL into scheme, host, port and path, using port 80 when none is given', 'Write the request line and headers by hand and send them over a TCP connection', 'Read the reply until the server closes the connection', 'Print only the body by default, and the sent and received headers too with -v', 'Choose the method with -X, send a body with -d and add headers with -H', 'Send a Content-Length header with every body']::text[],
  restate_rubric = '[{"id":"r1","point":"It is a command-line HTTP client that sends a request to the host named in a URL and prints the reply"},{"id":"r2","point":"It writes the HTTP text itself over a TCP connection instead of using an HTTP library"},{"id":"r3","point":"It supports GET, DELETE, POST and PUT, with a body, extra headers and a verbose mode chosen by options"}]'::jsonb, reflection_prompt = 'In your own words, how does your tool turn a URL and a few options into bytes on a socket, and how does it know the reply has ended? What would change if it had to keep the connection open for a second request?',
  primer = '{"what":"curl is a command-line tool that sends a request to a web server and prints what comes back. HTTP/1.1 is plain text sent over a TCP connection: the client connects to a host and port, writes a request line, some header lines and an empty line, and the server writes back a reply of the same shape. You will build cccurl, which does this by hand for the GET, DELETE, POST and PUT methods against a public test site.","why":"Every API call from a browser, an app or a script works this way underneath. Writing the request yourself shows what HTTP libraries hide: how a URL becomes a connection, how lines and an empty line shape a message, and how a client knows a reply is complete.","example":"Given http://localhost:8080/status, cccurl reads the scheme http, the host localhost, the port 8080 and the path /status. It connects to port 8080 on localhost and sends the request line GET /status HTTP/1.1, then a Host header naming localhost and its port, then an Accept header, then an empty line. The server answers with a status line such as HTTP/1.1 200 OK, its own headers, an empty line and the body.","words":[{"term":"URL","meaning":"An address made of a scheme such as http, a host name, an optional port and a path."},{"term":"port","meaning":"A number that picks which program on the host receives the connection. When a URL leaves it out, the scheme''s usual port is used, which is 80 for http."},{"term":"request line","meaning":"The first line of a request, holding the method, the path and the HTTP version, separated by single spaces."},{"term":"header","meaning":"A line made of a name, a colon and a value, such as Host followed by the host name, that adds a detail to a message."},{"term":"method","meaning":"The verb at the start of the request line, such as GET to read or DELETE to remove, saying what to do with the path."},{"term":"body","meaning":"The optional data that follows the empty line, such as the JSON a POST sends."}]}'::jsonb, figure_kind = 'net',
