  summary = 'A command-line tool that prints the lines of files or piped text that match a pattern, with digit and word classes, start and end anchors, recursive search, inverted and case-insensitive matching, and the same exit status as grep. Use your language''s regex library, or write your own matching engine.', requirements = array['Print every line of the input that matches the pattern, where an empty pattern matches every line', 'Exit with status 0 when a line was printed, 1 when none was, and 2 on an error such as a missing file', 'Search a folder tree with -r, putting the file path before each printed line', 'Print the lines that do not match with -v, and ignore case with -i', 'Support a digit class, a word class, and anchors for the start and end of a line', 'Read standard input when no file name is given, so the tool works after a pipe']::text[],
  restate_rubric = '[{"id":"r1","point":"The tool prints the lines that match a pattern, from files, a folder tree or a pipe"},{"id":"r2","point":"It supports classes such as any digit, anchors for the start and end of a line, -v to invert and -i to ignore case"},{"id":"r3","point":"Its exit status says whether anything matched or an error happened, so scripts can act on it"}]'::jsonb, reflection_prompt = 'In your own words, how does your grep decide that a line matches, and what would change if you swapped the regex library for an engine you wrote yourself, or the other way round?',
  primer = '{"what":"grep reads text one line at a time and prints the lines that contain a match for a pattern. The pattern is a regular expression: plain letters match themselves, and a few special signs stand for a whole class of characters or for a position such as the start of a line. You will build a version that can search a folder tree, invert the search, ignore case, and tell a script through its exit status whether anything matched.","why":"Searching logs, code and data for lines of a certain shape is an everyday programming job, and grep''s exit status lets scripts decide what to do next. Writing one also shows how pattern matching works underneath.","example":"A file holds three lines: Rome, Paris and Oslo. Searching it for the letter s prints Paris and Oslo, because a line is printed when the pattern appears anywhere in it, at the start, the middle or the end. Rome has no s, so it is left out.","words":[{"term":"pattern","meaning":"The regular expression grep looks for in each line."},{"term":"match","meaning":"A place in a line where the whole pattern fits. One match anywhere is enough to print the line."},{"term":"character class","meaning":"One sign that matches any single character from a set, such as any digit."},{"term":"anchor","meaning":"A sign that matches a position rather than a character, such as the start or the end of a line."},{"term":"exit status","meaning":"A small number a program hands back when it ends, which scripts read to learn how it went."},{"term":"recursive search","meaning":"Searching every file in a folder, then every file in each folder inside it, all the way down."}]}'::jsonb, figure_kind = 'match',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep');
