update challenge set title = 'Build your own compression tool', source_url = 'https://codingchallenges.fyi/challenges/challenge-huffman', level = 'intermediate',
  summary = 'A command-line tool that compresses a file with Huffman coding. It counts how often each symbol appears, builds a tree that gives common symbols short codes, writes a header and the packed bits, and decompresses the result back into an exact copy of the original.', requirements = array['Read a file named on the command line and report an error if it cannot be read', 'Count how often each symbol occurs and build a Huffman tree from the counts', 'Turn the tree into a table of prefix-free bit codes', 'Write a compressed file with a header the decoder can rebuild the table from, followed by the packed bits', 'Decompress the file back into an exact copy of the original, with the output file name given as an option', 'Check that the test novel gets smaller and comes back byte for byte']::text[],
  restate_rubric = '[{"id":"r1","point":"The tool compresses a file by counting symbols, building a Huffman tree and replacing each symbol with its bit code"},{"id":"r2","point":"The compressed file holds a header that lets the decoder rebuild the codes, followed by the codes packed into bytes"},{"id":"r3","point":"Decompressing gives back exactly the original file, byte for byte"}]'::jsonb, reflection_prompt = 'In your own words, what does your compressed file contain and in what order, and what would you change to make the header smaller for short files?',
  primer = '{"what":"Huffman coding stores data in fewer bits by giving frequent symbols short codes and rare symbols long ones. You count how often each symbol occurs, build a binary tree by joining the two rarest entries again and again, and read each symbol''s code off the path from the root to its leaf. You will build a tool that compresses a file this way and decompresses it back to the original.","why":"Plain text spends eight bits on every character, however common it is. Fitting the length of a code to how often a symbol is used is the idea behind part of the compression in ZIP files, PNG images and JPEG photos.","example":"In the word banana, a appears three times, n twice and b once, so the frequency table has three entries, one per different letter. The tree joins the rarest entries first, so a never ends up with a longer code than n or b. Reading each code as a path of 0 for left and 1 for right, the whole word fits in 9 bits instead of the 48 that eight bits per letter would need.","words":[{"term":"frequency table","meaning":"A list of each different symbol in the input with the number of times it occurs."},{"term":"Huffman tree","meaning":"A binary tree whose leaves are the symbols, built by repeatedly joining the two lightest nodes into one whose weight is their sum."},{"term":"prefix-free code","meaning":"A set of codes in which no code is the start of another, so a stream of bits can be read back without separators."},{"term":"priority queue","meaning":"A collection that always hands back its smallest item first, whatever order the items went in."},{"term":"bit packing","meaning":"Putting codes of any length into whole bytes, eight bits to a byte, and padding the last byte."},{"term":"header","meaning":"The start of the compressed file, holding what the decoder needs before it can read the data."}]}'::jsonb, figure_kind = 'tree',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman');
