update challenge set title = 'Build your own JSON parser', source_url = 'https://codingchallenges.fyi/challenges/challenge-json-parser', level = 'intermediate',
  summary = 'A command-line tool that reads a file and decides whether it holds valid JSON. It splits the text into tokens, checks them against the JSON grammar with a recursive descent parser, prints a verdict and exits with status 0 for valid input and 1 for invalid input.', requirements = array['Read a file named on the command line and decide whether it holds valid JSON', 'Print a message and exit with status 0 for valid input and 1 for invalid input', 'Split the text into tokens first, then check the tokens against the JSON grammar', 'Support objects, arrays, strings, numbers, true, false and null, nested inside each other', 'Pass the test folders that come with the challenge, then the json.org checker suite']::text[],
  restate_rubric = '[{"id":"r1","point":"The tool reads a file and decides whether its text is valid JSON"},{"id":"r2","point":"It prints a message and exits with status 0 when the input is valid and 1 when it is not"},{"id":"r3","point":"It first splits the text into tokens and then checks them against the grammar, covering every kind of value and nesting"}]'::jsonb, reflection_prompt = 'In your own words, how do the lexer and the parser share the work in your design, and what would you change to turn the validator into a parser that builds the data in memory?',
  primer = '{"what":"JSON is a plain-text format for data. Objects sit in curly braces and hold pairs of a key and a value, arrays sit in square brackets and hold lists of values, and the simple values are strings in double quotes, numbers, true, false and null. You will build a tool that reads a file and says whether it is valid JSON, exiting with status 0 when it is and 1 when it is not.","why":"Web APIs and many configuration files speak JSON, and a parser is how a program decides whether to trust that text. Building one teaches the two-stage shape used by compilers and interpreters: a lexer, then a parser.","example":"Take the text made of an opening square bracket, the number 42, a comma, a space, the word true and a closing square bracket. The lexer skips the space and hands over five tokens: open bracket, the number 42, comma, true and close bracket. A string in double quotes becomes a single token however many letters or spaces it holds. The parser then checks the order of the tokens: an array opens, its values are separated by commas, and it closes. They are in order here, so the tool prints that the file is valid and exits with status 0.","words":[{"term":"token","meaning":"One meaningful piece of the text, such as a brace, a colon, a comma, a whole string, a number or the word null."},{"term":"lexer","meaning":"The first stage, which reads characters, groups them into tokens and skips the whitespace between them."},{"term":"parser","meaning":"The second stage, which checks that the tokens come in an order the grammar allows."},{"term":"grammar","meaning":"The rules for what may follow what, for example that a key in an object is always followed by a colon."},{"term":"recursive descent","meaning":"A way of writing a parser with one function per grammar rule, where a rule that contains others calls their functions."},{"term":"exit status","meaning":"The number a program hands back when it ends. Zero means success, and anything else means something went wrong."}]}'::jsonb, figure_kind = 'tokens',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-json-parser');
result = parse_value(tokens)
if result is not an error:
    print("valid JSON")
else:
    print("invalid JSON")
exit(0)', null, '[{"id":"p1","point":"It always exits with status 0, so a script cannot tell an invalid file from a valid one; invalid input must exit with status 1"},{"id":"p2","point":"It never checks that the parser used up every token, so text with something after the first value, such as two objects in a row, is called valid"},{"id":"p3","point":"After the top-level value the next token must be the end of the input, otherwise the file is invalid"}]'::jsonb);
