update challenge set title = 'Build your own rate limiter', source_url = 'https://codingchallenges.fyi/challenges/challenge-rate-limiter', level = 'intermediate',
  summary = 'A small HTTP service with a limited and an unlimited endpoint, protected in turn by a token bucket, a fixed window counter, a sliding window log and a sliding window counter, and finally by a limit shared between several servers through Redis.', requirements = array['Serve two endpoints, /limited and /unlimited, where only /limited is rate limited', 'Limit each client IP address with a token bucket of 10 tokens refilled at 1 token per second', 'Answer a rejected request with 429 Too Many Requests', 'Replace the token bucket with a fixed window counter whose windows are aligned to the clock', 'Implement a sliding window log and a sliding window counter, each with tests you design', 'Share one limit between two servers on different ports through a store such as Redis']::text[],
  restate_rubric = '[{"id":"r1","point":"The service limits how many requests each client can make to one endpoint and leaves the other endpoint unlimited"},{"id":"r2","point":"It implements several algorithms: a token bucket, a fixed window counter, a sliding window log and a sliding window counter"},{"id":"r3","point":"A rejected request gets the status 429 Too Many Requests"},{"id":"r4","point":"In the end several servers enforce one shared limit by keeping the counts in a shared store such as Redis"}]'::jsonb, reflection_prompt = 'In your own words, which of your limiters would you put in front of a real API, what does it cost in memory and in fairness at window boundaries, and what would you change to run it on many servers?',
  primer = '{"what":"A rate limiter sits in front of an API and decides, for each incoming request, whether the client has asked too often recently. If it has, the request is turned away with a status meaning too many requests, and the work behind the endpoint never runs. You will build one in four different ways and then make several servers share a single limit.","why":"Without a limit, one buggy script, one heavy user or one attacker can flood a service and slow it down for everyone. A limiter keeps each client to a fair share and lets the service survive sudden spikes.","example":"Picture a bucket for one client that holds at most 2 tokens and gains 1 token every second. The client sends 3 requests at the same instant. The first two each take a token and are served, and the third finds the bucket empty and is rejected. A second later one token has appeared, so the client''s next request is served again.","words":[{"term":"rate limiter","meaning":"The part of a service that counts each client''s recent requests and rejects the ones over the limit."},{"term":"token bucket","meaning":"A limiter where each request spends a token from a small store of tokens that refills at a steady pace."},{"term":"window","meaning":"A stretch of time, such as one minute, in which requests are counted against the limit."},{"term":"burst","meaning":"Many requests arriving close together, faster than the long-run allowed rate."},{"term":"429 Too Many Requests","meaning":"The HTTP status a server sends when it refuses a request because the client is over its limit."},{"term":"shared store","meaning":"A database such as Redis that several servers read and update, so they all see the same counts."}]}'::jsonb, figure_kind = 'bucket',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter');
