update challenge set title = 'Build your own Redis server', source_url = 'https://codingchallenges.fyi/challenges/challenge-redis', level = 'intermediate',
  summary = 'A small Redis-compatible server on port 6379 that speaks the Redis protocol, keeps keys in memory with optional expiry, serves many clients at once, supports counters and lists, saves its data to disk and can be measured against the real Redis with redis-benchmark.', requirements = array['Encode and decode every RESP type, including the null bulk string, and reject malformed input', 'Listen on port 6379 and answer PING with PONG and ECHO with its argument', 'Store values with SET and read them with GET, replying in the format the real Redis uses', 'Serve many clients at the same time without errors, checked with redis-benchmark', 'Support the expiry options EX, PX, EXAT and PXAT on SET', 'Add EXISTS, DEL, INCR, DECR, LPUSH, RPUSH and SAVE, and load the saved data on startup']::text[],
  restate_rubric = '[{"id":"r1","point":"It is an in-memory key-value server that clients talk to over TCP using the Redis protocol"},{"id":"r2","point":"It handles commands such as PING, ECHO, SET and GET, plus expiry, counters and lists"},{"id":"r3","point":"It serves many clients at once and can save its data to disk and load it again on startup"}]'::jsonb, reflection_prompt = 'In your own words, what decided how fast and how correct your server was under fifty clients at once, and what would you change to make it survive a crash without losing recent writes?',
  primer = '{"what":"Redis is a database that keeps all its data in memory and answers commands sent over a network connection, such as SET to store a value under a key and GET to read it back. Clients and server talk in a simple text-like format called RESP. You will build a small server that speaks RESP on port 6379, so the real redis-cli and redis-benchmark tools can talk to it.","why":"Holding data in memory makes every command fast, which is why Redis is used for caches, sessions and counters. Building it teaches how a protocol marks where one message ends on a stream of bytes, and how a server stays correct when many clients change the same data.","example":"When you type PING in redis-cli, the client sends an array holding one bulk string. On the wire that is a star and the digit 1, then a carriage return and a newline. Next comes a dollar sign and the digit 4, the length of the word, then a carriage return and a newline, then the four letters P, I, N and G, and one more carriage return and newline. Your server reads that, and replies with a plus sign, the word PONG and a carriage return and newline.","words":[{"term":"RESP","meaning":"The Redis protocol. The first byte of each value says its type, and every line ends with a carriage return and a newline."},{"term":"carriage return and newline","meaning":"The two bytes that end every line in RESP, often written as CRLF. Together they count as 2 bytes."},{"term":"simple string","meaning":"A short reply that starts with a plus sign, such as OK or PONG. It cannot contain a line break."},{"term":"bulk string","meaning":"A string that starts with a dollar sign and its length in bytes, so it can hold any bytes at all."},{"term":"array","meaning":"A list of values that starts with a star and the number of items it holds. Clients send every command as an array."},{"term":"key","meaning":"The name a value is stored under, such as Name in SET Name John."}]}'::jsonb, figure_kind = 'kv',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-redis');
