update challenge set title = 'Build your own sort', source_url = 'https://codingchallenges.fyi/challenges/challenge-sort', level = 'beginner',
  summary = 'A command-line tool that reads the lines of a file or of piped text and prints them in sorted order, with an option to drop duplicate lines, a choice of sorting algorithm and a random order that still keeps equal lines together.', requirements = array['Print the lines of a file, or of standard input, in lexicographic order', 'Drop duplicate lines with -u, giving the same result as sorting and then running uniq', 'Let the user choose between sorting algorithms such as merge sort, quicksort, heapsort and radix sort', 'Shuffle lines with -R so that equal lines still end up next to each other', 'Give the same output as the real sort, with the locale set to C, on the word list from the challenge']::text[],
  restate_rubric = '[{"id":"r1","point":"The tool reads lines from a file or standard input and prints them in sorted order"},{"id":"r2","point":"An option removes duplicate lines, and another lets the user pick the sorting algorithm"},{"id":"r3","point":"A random sort option shuffles the lines but keeps identical lines together"}]'::jsonb, reflection_prompt = 'In your own words, how does your design decide the order of two lines, where does it remove duplicates, and what would you change to sort a file far bigger than memory?',
  primer = '{"what":"sort is a small command-line tool that reads lines of text and prints them back in order. You give it a file name, or pipe text into it, and it compares the lines two at a time to decide which goes first. You will build your own version that matches the real one, then add options to drop duplicates, pick the algorithm and shuffle.","why":"Sorting is everywhere: file listings, logs, leaderboards, and as the step that lets other tools such as uniq do their job. Building it makes you decide what order text really has, and what a sorting algorithm costs.","example":"Given the lines dog, ant and cat, sort prints ant, cat, dog. To compare two lines it walks along them letter by letter, and the first letter that differs decides. Apple and apricot share a, p, then the third letters are p and r, and p comes first in the alphabet, so apple goes before apricot.","words":[{"term":"line","meaning":"The text up to a newline. sort treats each line as one item and never splits it."},{"term":"lexicographic order","meaning":"Dictionary-style order where two pieces of text are compared from the left and the first difference decides."},{"term":"byte order","meaning":"Ordering letters by the number each one is stored as, rather than by a language''s alphabet rules."},{"term":"locale","meaning":"The language and country settings of a machine, which can change how text is compared and sorted."},{"term":"duplicate","meaning":"A line that is exactly the same, byte for byte, as another line in the input."},{"term":"stable sort","meaning":"A sort that keeps items which compare as equal in the order they arrived."}]}'::jsonb, figure_kind = 'sort',
