  summary = 'A command-line tool that turns a folder of Markdown pages and an HTML theme into a static website, and can serve the site locally and refresh it when files change.', requirements = array['Create a new site with a content folder and a starting page', 'Create themes and new pages from the command line', 'Fill the theme template with each page''s title and rendered Markdown, and write the result to a public folder', 'Serve the site locally and update it when a page or the theme changes']::text[],
  restate_rubric = '[{"id":"r1","point":"It builds a static site from Markdown pages and an HTML theme"},{"id":"r2","point":"It has commands to create a site, a theme and a page, and a build command that writes the finished HTML to a public folder"},{"id":"r3","point":"It can serve the site locally and refresh it when files change"}]'::jsonb, reflection_prompt = 'In your own words, how does your design keep content, theme and output separate, and what would you change if the site had a thousand pages?',
  primer = '{"what":"A static site generator turns pages written in Markdown, a simple way of marking headings and paragraphs in plain text, into a finished website of HTML files. The look of the site lives in a theme, an HTML file with holes where each page''s title and text go. You will build one with commands to create a site, a theme and pages, a build command, and a local server that refreshes when you edit.","why":"Most blogs and documentation sites are plain files on a server. Generating them once, instead of building each page when someone asks for it, makes them fast, cheap and hard to break.","example":"After you create a site called mysite, a theme called cc and a page called about, the folder holds content/index.md and content/about.md, written by the author, and themes/cc/index.html, written by the designer. Building fills the theme once per page and writes public/index.html and public/about.html, ready to publish.","words":[{"term":"Markdown","meaning":"Plain text with light marks, such as a hash at the start of a line for a heading, that converts to HTML."},{"term":"theme","meaning":"The HTML that decides how every page looks, with placeholders for the page''s own title and content."},{"term":"placeholder","meaning":"A named hole in the theme, such as Title or Content in double curly braces, filled in for each page."},{"term":"build","meaning":"The step that reads the content and the theme and writes the finished site into the public folder."},{"term":"escaping","meaning":"Writing characters such as less-than and ampersand in a safe form, so the browser shows them as text."},{"term":"live reload","meaning":"The browser refreshing by itself when the development server rebuilds the site after an edit."}]}'::jsonb, figure_kind = 'pages',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-ssg');
