update challenge set title = 'Build your own URL shortener', source_url = 'https://codingchallenges.fyi/challenges/challenge-url-shortener', level = 'beginner',
  summary = 'A small web service that gives a long URL a short key, stores the pair, sends visitors of the short URL on to the long one, and lets the owner delete a short URL, all through a REST API.', requirements = array['POST to the root with a JSON body holding url creates a key and answers with the key, the long URL and the short URL', 'Posting the same long URL again returns the same key and changes nothing', 'A body without a url field gets 400 Bad Request with a message naming the missing field', 'GET for a key answers 302 Found with a Location header holding the long URL, and an unknown key gets 404 Not Found', 'DELETE for a key removes it from storage and answers 200 OK', 'Keys and long URLs are kept in storage that survives a restart']::text[],
  restate_rubric = '[{"id":"r1","point":"It turns a long URL into a short key and stores the two together"},{"id":"r2","point":"Visiting the short URL redirects the browser to the long URL, and unknown keys get 404"},{"id":"r3","point":"It is a REST API with POST to create, GET to follow and DELETE to remove a short URL"}]'::jsonb, reflection_prompt = 'In your own words, how does your service choose keys that stay unique, and what would you change if it had to hold a hundred million links?',
  primer = '{"what":"A URL shortener gives a long web address a short key, saves the pair, and when anyone visits the short address it sends their browser on to the long one. You build it as a small web service, an API, that other programs talk to over HTTP. Each request names a method, such as POST to create, GET to read and DELETE to remove, and every reply starts with a status code saying what happened.","why":"Short links are easier to share, type and print, and they let the owner count visits or retire a link. Building one teaches how a web API reports what happened, and how to make short names that stay unique.","example":"A client sends a POST to the service''s root with a JSON body whose url field holds https://www.example.com. The service picks a key, say Y3S9wb, saves it with the long address, and answers with the key and the short address http://localhost/Y3S9wb. Visiting that short address later takes the browser to example.com.","words":[{"term":"status code","meaning":"A three-digit number at the start of every reply. Codes in the 200s mean it worked, the 300s mean look somewhere else, and the 400s mean the client''s request was at fault, such as 400 when the request is malformed or missing something and 404 when nothing exists at that address."},{"term":"key","meaning":"The short name the service makes up, such as Y3S9wb, used as the last part of the short address."},{"term":"JSON","meaning":"A plain-text way to send named fields, such as a field called url holding a web address."},{"term":"hash function","meaning":"A recipe that turns any text into a number, always giving the same number for the same text."},{"term":"redirect","meaning":"A reply that tells the browser to go to another address, which the browser then does by itself."}]}'::jsonb, figure_kind = 'short',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener');
    key = first(base62(builtin_hash(long_url)), 6)
    store.put(key, long_url)
    return key', null, '[{"id":"p1","point":"When two URLs give the same key, put overwrites the first URL, so the older short link now leads to the other site"},{"id":"p2","point":"Check the store first: reuse the key if it already holds this URL, and add a counter and hash again if it holds a different one"},{"id":"p3","point":"A built-in hash can change between runs or versions of the language, so use a fixed algorithm such as FNV-1a or SHA-256 to get the same key every time"}]'::jsonb);

