update challenge set title = 'Build your own wc', source_url = 'https://codingchallenges.fyi/challenges/challenge-wc', level = 'beginner',
  summary = 'A command-line tool that counts the bytes, lines, words and characters of a file or of text piped into it, and gives the same numbers as the Unix wc tool. Building it teaches how text is really encoded, how to read input of any size in constant memory, and how a well-behaved Unix tool works.', requirements = array['Count bytes with -c, lines with -l, words with -w and characters with -m', 'With no option, print the line, word and byte counts followed by the file name', 'Read standard input when no file name is given', 'Give the same answers as the reference wc on the challenge''s sample file']::text[],
  restate_rubric = '[{"id":"r1","point":"The tool counts bytes, lines, words and characters"},{"id":"r2","point":"Each count has its own option, and with no option it prints lines, words and bytes"},{"id":"r3","point":"It reads standard input when no file is given"}]'::jsonb, reflection_prompt = 'Which idea from this project will you use outside wc first: text encodings, constant-memory streaming or the Unix tool contract? Describe a real situation where it would have saved you, or someone you know, from a bug.',
  primer = '{"what":"wc counts what is inside a file: bytes, lines, words and characters. You give it a file name, or pipe text into it from another program, and it prints the counts. You will build your own version, called ccwc, that gives the same answers as the real one.","why":"Counting sounds trivial, but it forces three real questions. How is text stored as bytes? How do you read input that may be far bigger than memory? And how does a small tool behave so that other programs can rely on it?","example":"A file is only a row of numbers called bytes. To show them as letters, a program needs an encoding, a rule that maps characters to bytes. In the common encoding UTF-8 the word cat is 3 bytes, one per letter, but café is 5 bytes, because é needs two. So asking \"how many characters?\" and \"how many bytes?\" about the same file can give different answers, and that difference is where this project starts.","words":[{"term":"byte","meaning":"The unit a file is stored in, a number from 0 to 255. Plain English letters take one byte each."},{"term":"encoding","meaning":"The agreed rule for turning characters into bytes and back. UTF-8 is the most common one."},{"term":"code point","meaning":"The number Unicode gives each character, written like U+00E9 for é."},{"term":"stream","meaning":"Data you read a piece at a time, start to end, without holding all of it at once."},{"term":"standard input","meaning":"The stream a program receives when another program''s output is piped into it."},{"term":"exit status","meaning":"The number a program returns when it ends. Zero means it worked, anything else means it failed."}]}'::jsonb, figure_kind = 'stream',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc');
