loop:
    n = read(input, buffer)
    total = total + 4096
    if n < 4096:
        stop
print(total)', null, '[{"id":"p1","point":"It adds the buffer size instead of the count the read returned, so a short last read adds bytes that are not there"},{"id":"p2","point":"A short read does not mean the end; a pipe or a network can return fewer bytes while more is coming, so only the end marker should stop the loop"}]'::jsonb);
loop:
    chunk = read(input, 4096)
    if chunk is the end marker:
        stop
    total = total + length(decode(chunk))
print(total)', null, '[{"id":"p1","point":"A character''s bytes can be split between two chunks, and decoding each chunk on its own breaks it into invalid pieces that are counted as extra characters"},{"id":"p2","point":"A decoder that keeps the bytes of an unfinished character and joins them to the next chunk fixes it"},{"id":"p3","point":"decode uses the platform default encoding, so the encoding should be named explicitly as UTF-8"}]'::jsonb);
