update challenge set title = 'Build your own web server', source_url = 'https://codingchallenges.fyi/challenges/challenge-webserver', level = 'intermediate',
  summary = 'An HTTP server built on a bare TCP socket. It reads each request, serves files from a www folder, handles many clients at the same time, and refuses any request that tries to reach a file outside that folder.', requirements = array['Listen on a TCP port on localhost and read the request line and headers of each request', 'Reply with a status line, an empty line and a body, then close the connection', 'Serve files from a www folder, mapping / and /index.html to index.html', 'Answer 404 Not Found when no file matches the path', 'Serve several clients at the same time, so a slow one does not hold up the others', 'Never send a file from outside www, and let the user choose the www folder at startup']::text[],
  restate_rubric = '[{"id":"r1","point":"It is an HTTP server that accepts TCP connections, reads each request and writes back a reply"},{"id":"r2","point":"It serves files from a www folder, giving index.html for / and 404 when a file is missing"},{"id":"r3","point":"It serves several clients at once and refuses paths that lead outside www"}]'::jsonb, reflection_prompt = 'In your own words, how does your server turn the bytes arriving on a socket into a safe reply, and what would you change to serve thousands of clients at once?',
  primer = '{"what":"A web server waits for browsers and tools such as curl to connect over TCP, reads the text request each one sends, and writes back a text reply. A request starts with a request line made of three parts separated by single spaces: the method, the path and the HTTP version. Header lines follow, one per line, and an empty line ends them. You will build a server that sends files from a folder called www to many clients at once, without letting anyone read files outside it.","why":"Every web page reaches you this way, and HTTP/1.1 is plain text, so you can read and write it yourself. Building a server shows how a stream of bytes becomes separate messages, and why anything a stranger sends must be checked.","example":"Visiting http://localhost/ with curl sends the request line GET / HTTP/1.1, so the method is GET, the path is a single slash and the version is HTTP/1.1. A few header lines such as Host: localhost follow, then an empty line. The server answers with the status line HTTP/1.1 200 OK, an empty line and a body, then closes the connection.","words":[{"term":"socket","meaning":"One end of a network connection. A program reads bytes from it and writes bytes to it, like a file."},{"term":"port","meaning":"A number that picks which program on a machine receives a connection. Web servers usually listen on 80."},{"term":"request line","meaning":"The first line of a request, holding the method, the path and the HTTP version, separated by spaces."},{"term":"header","meaning":"A line of the form name, colon, value, such as Host followed by localhost, that adds a detail to a message."},{"term":"CRLF","meaning":"A carriage return followed by a line feed, the two bytes that end every line of an HTTP message."},{"term":"status line","meaning":"The first line of a reply, holding the version, a status code such as 200 or 404, and a short phrase."}]}'::jsonb, figure_kind = 'net',
  content_status = 'generated', updated_at = now() where id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-webserver');
data = read(conn, 1024)
path = split(data, " ")[1]
write(conn, "HTTP/1.1 200 OK\r\n")
write(conn, "Requested path: " + path)
close(conn)', null, '[{"id":"p1","point":"One read can return only part of the request, so the server must keep reading and buffering until the empty line that ends the headers arrives"},{"id":"p2","point":"There is no empty line between the status line and the body, so the client reads the body as a header. Send a carriage return and line feed on its own line before the body"}]'::jsonb);
